window.JASTROW_CHUNKS[34]={"13600":{"h":"מְלַקֵּט II","r":"M01624","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <a href=\"#\" data-headword=\"מְלַקֶּטֶת\">מְלַקֶּטֶת</a> f. (<a href=\"#\" data-headword=\"לָקַט\">לָקַט</a>) <i>pinchers</i> for picking hair, wool &amp;c. <span class=\"citation\">Macc. III, 5</span>; <span class=\"citation\">Naz. 40ᵇ</span>, v. <a href=\"#\" data-headword=\"לָקַט\">לָקַט</a>. <span class=\"citation\">Kel. XIII, 8</span> (ed. Dehr. 10) <span dir=\"rtl\">ועשאן למלקטת</span> and he makes use of them as pinchers; <span class=\"citation\">Yeb. 43ᵃ</span> <span dir=\"rtl\">למלקט</span>. <span class=\"citation\">Tosef. Kel. B. Mets. III, 14</span> <span dir=\"rtl\">המְלַקֵּיט של כובסין</span> (ed. Zuck. <span dir=\"rtl\">המלקוט של כובשין</span>) the fullers’ pinchers (with which they remove knots in a web). <span class=\"citation\">Sabb. 97ᵃ</span> <span dir=\"rtl\">אי אפשר … שתילקט במ׳ וכ׳</span> a public road cannot be made even (as skin is made) with pinchers and razors.</div>","alt":[]},"13601":{"h":"מלקטי","r":"M01625","html":"<div class=\"sense\">, <span class=\"citation\">Y. Naz. I, 51ᵇ</span> bot., <span dir=\"rtl\">כמ׳ קייץ</span>, read: <a href=\"#\" data-headword=\"הֶלְקֵט\">הִלְקְטֵי</a>, v. <a href=\"#\" data-headword=\"קַיִץ\">קַיִץ</a></div>","alt":[]},"13602":{"h":"מַלְקְטָא","r":"M01626","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מלקטי\">preced. art.</a>) <i>snuffers</i>. <span class=\"citation\">Targ. Y. Num. IV, 9</span> (Ar. ed. Koh. <span dir=\"rtl\">מַלְקְטָטָהָא</span>, Var. <span dir=\"rtl\">מלְקְטָטַיָּא</span>; h. text <span dir=\"rtl\">מלקחי׳</span>). <span class=\"citation\">Targ. Y. Ex. XXV, 38</span>; <span class=\"citation\">XXXVII, 23</span> <span dir=\"rtl\">מַלְקָטַיָּיהָא</span> (Ar. <a href=\"#\" data-headword=\"מַלְקְטָתָא\">מַלְקְטָתָהָא</a>).</div>","alt":[]},"13603":{"h":"מְלַקֶּטֶת","r":"M01627","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְלַקֵּט II\"><span dir=\"rtl\">מְלַקֵּט</span> II</a></div>","alt":[]},"13604":{"h":"מַלְקְטָתָא","r":"M01628","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַלְקְטָא\">מַלְקְטָא</a></div>","alt":[]},"13605":{"h":"מְלַקֵּיט","r":"M01629","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְלַקֵּט II\"><span dir=\"rtl\">מְלַקֵט</span> II</a></div>","alt":[]},"13606":{"h":"מלריון","r":"M01630","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בלרין\">בלרין</a></div>","alt":["מלרין"]},"13607":{"h":"מִלְּרַע","r":"M01631","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"לִרַע\">לְּרַע</a></div>","alt":[]},"13608":{"h":"מַלְשִׁין","r":"M01632","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"לָשַׁן\">לָשַׁן</a>) <i>slanderer, informer</i>. <span class=\"citation\">Midr. Till. to Ps. CXX</span>.</div>","alt":[]},"13609":{"h":"מַלְשִׁינָא","r":"M01633","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ps. CXX, 3</span>.</div>","alt":[]},"13610":{"h":"מַלְשִׁינוּתָא","r":"M01634","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַלְשִׁינָא\">preced.</a>) <i>slander</i>. <span class=\"citation\">Targ. Ps. LII, 4</span>.</div>","alt":[]},"13611":{"h":"מֶלֶת","r":"M01635","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵילַת\">מֵילַת</a></div>","alt":[]},"13612":{"h":"מִלַּת","r":"M01636","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִילָּא I\"><span dir=\"rtl\">מִילָּא</span> I</a></div>","alt":[]},"13613":{"h":"מִלְּתָא","r":"M01637","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִילְּתָא\">מִילְּתָא</a></div>","alt":[]},"13614":{"h":"מִלֵּתָא","r":"M01638","html":"<div class=\"sense\"><i>mound</i>, v. <a href=\"#\" data-headword=\"מַלְיְתָא\">מַלְיְתָא</a>.</div>","alt":[]},"13615":{"h":"מְלָתָא","r":"M01639","html":"<div class=\"sense\"><i>place for drawing water</i>, v. <a href=\"#\" data-headword=\"מְלוֹיְתָא\">מְלוֹיְתָא</a>.</div>","alt":[]},"13616":{"h":"מֶלְתָּחָה","r":"M01640","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>wardrobe</i>. <span class=\"citation\">Gitt. 59ᵃ</span>, v. <a href=\"#\" data-headword=\"מָלַל II\"><span dir=\"rtl\">מָלַל</span> II</a>.</div>","alt":[]},"13617":{"h":"מֵלְתִין","r":"M01641","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵילַת\">מֵילַת</a></div>","alt":[]},"13618":{"h":"מלתירה","r":"M01642","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"מַלְתְּרָא\">מַלְתְּרָה</a>.</div>","alt":[]},"13619":{"h":"מַלְתְּרָא","r":"M01643","html":"<div class=\"sense\">, v, <a href=\"#\" data-headword=\"אֲמַלְתְּרָא\">אֲמַלְתְּרָא</a>.</div>","alt":["מַלְתְּרָה"]},"13620":{"h":"מ\"ם","r":"M01644","html":"<div class=\"sense\"><i>Mem</i>, name of the thirteenth letter of the alphabet. <span class=\"citation\">Sabb. 103ᵇ</span> מ&quot;ם דשם סתומה Ms. O. (ed. <a href=\"#\" data-headword=\"סְתוֹם\">סתום</a>) the Mem in <i>shem</i> is closed (final letter); <span dir=\"rtl\">מ&quot;ם שמעון פתוחה</span> (ed. <span dir=\"rtl\">פתוח</span>) the Mem in Shimʿon is open (initial letter). Ib. 104ᵃ <span dir=\"rtl\">מ&quot;ם פתוחה מ&quot;ם סתומה מאמר וכ׳</span> the open and the closed <i>Mems</i> intimate that there are subjects in the Law which are open to all, and such as are closed (esoteric studies). <span class=\"citation\">Y. Meg. I, 71ᵈ</span> <span dir=\"rtl\">מהו דין דכתיב מ&quot;ם מ&quot;ם וכ׳</span> why is it that the letters <i>Mem, Nun</i> &amp;c. are written in two ways?—<span class=\"citation\">Maas. Sh. IV, 11</span>; a. fr.—Pl. <span dir=\"rtl\">מֵמִין</span>, <span dir=\"rtl\">מֵימִין</span>. <span class=\"citation\">Sabb. 103ᵃ</span> one must not write <span dir=\"rtl\">מ׳ סמכין וכ׳</span> <i>Mem</i> like <i>Samekh</i> or vice versa; a. e.</div>","alt":["מֵם"]},"13621":{"h":"מִמַּאי","r":"M01645","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַאי\">מַאי</a></div>","alt":[]},"13622":{"h":"ממה","r":"M01646","html":"<div class=\"sense\">, <span class=\"citation\">Y. Erub. IV, end, 22ᵃ</span> <span dir=\"rtl\">בית מ׳</span>, v. <a href=\"#\" data-headword=\"מַמָּל\">מַמָּל</a></div>","alt":[]},"13623":{"h":"מִמָּה","r":"M01647","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָה\">מָה</a></div>","alt":[]},"13624":{"h":"מְמוּכָן","r":"M01648","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Memucan</i>, one of the seven princes of Persia and Media. <span class=\"citation\">Meg. 12ᵇ</span>; <span class=\"citation\">Esth. R. to I, 14</span> (play on the name), v. <a href=\"#\" data-headword=\"כּוּן\">כּוּן</a> a. <a href=\"#\" data-headword=\"מָרַס\">מָרַס</a>.</div>","alt":[]},"13625":{"h":"מַמּוּלָּאֵי","r":"M01649","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (מָלַל II) <i>frail, short-lived people</i> (by the way of play on <a href=\"#\" data-headword=\"מַמְלָא I\">מַמְלָא</a>, q. v.).—<i>Fem. </i> pl. <span dir=\"rtl\">מַמּוּלְיָאתָא</span>, <span dir=\"rtl\">(<span dir=\"rtl\">מוּלָּיָ׳</span>) <span dir=\"rtl\">מַמּוּלְיָיתָא</span></span> (with <a href=\"#\" data-headword=\"מילי\">מִילֵּי</a>) <i>frail words</i> (untenable arguments). <span class=\"citation\">Yeb. 75ᵇ</span> sq. <span dir=\"rtl\">משום דאַתּוּ מ׳ אמריתו מילי מ׳</span> because you are frail, you speak frail words; (Var. <span dir=\"rtl\">משום דאתיתו מִמּוּלָּאֵי … מוּלָּיָתָא</span> because you are descendants of &amp;c.); <span class=\"citation\">B. Mets. 109ᵃ</span>; <span class=\"citation\">B. Bath. 137ᵇ</span> (Ms. R. <span dir=\"rtl\">דאַתּוּן</span>); <span class=\"citation\">151ᵃ</span> (ed. Pes. <span dir=\"rtl\">מַמּוּלְיָאתָה</span>).</div>","alt":["*(מוּלָּאֵי)"]},"13626":{"h":"מְמוֹמֵי","r":"M01650","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹמֵי\">מוֹמֵי</a></div>","alt":[]},"13627":{"h":"מָמוֹן","r":"M01651","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (contr. of <span dir=\"rtl\">מהמון</span>, v. <a href=\"#\" data-headword=\"הָמוֹן\">הָמוֹן</a>; <a href=\"#\" data-headword=\"הָמָה\">הָמָה</a>) <i>accumulation, wealth, value</i> (in Greek writers: <i>Mammon</i>). Tanḥ. Matt. 7 <span dir=\"rtl\">אתם חיבבתם את מָמוֹנְכֶם וכ׳</span> you loved your wealth (of cattle) more than your souls; <span class=\"citation\">Num. R. s. 12</span>. Ib.; Tanḥ. l. c. 6 <span dir=\"rtl\">מ̇מ̇ון̇ מ̇ה שאתה מ̇ונ̇ה אינו כלום</span> money is named <i>mamon</i>, that which thou countest is nothing. <span class=\"citation\">B. Mets. 2ᵇ</span>, a. fr. <span dir=\"rtl\">מ׳ המוטל בספק</span> property of doubtful ownership (with several claimants). <span class=\"citation\">Tosef. B. Mets. VII, 13</span>; <span class=\"citation\">B. Kam. 116ᵇ</span> <span dir=\"rtl\">מחשבין לפי מ׳</span> the loss of a caravan attacked by robbers (the redemption paid them) is apportioned according to the value of the freight which each passenger carried, contrad. to <span dir=\"rtl\">לפי נפשות</span> according to the number of passengers. <span class=\"citation\">Ib. 83ᵇ</span> עין תחת עין מ׳ ‘eye for eye’ (<span class=\"citation\">Ex. XXI, 24</span>) means a fine in value, opp. <span dir=\"rtl\">עין ממש</span> an actual putting out of the eye; a. v. fr.—[<span class=\"citation\">Pesik. R. s. 21</span> (ed. Fr., p. 105ᵇ) <span dir=\"rtl\">אין אתה עומד במימיו</span>, read <span dir=\"rtl\">במָמוֹנוֹ</span>, thou canst not define its value; Fr. a. l. emends <span dir=\"rtl\">בטִימְיוֹ</span>, v. <a href=\"#\" data-headword=\"טִימִי I\">טִימֵי</a>.]—Pl. <span dir=\"rtl\">מָמוֹנוֹת</span>. <span class=\"citation\">Snh. I, 1</span>, v. <a href=\"#\" data-headword=\"דִּין\">דִּין</a>; a. fr.</div>","alt":[]},"13628":{"h":"מָמוֹן ²","r":"M01652","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. XXXVII, 26</span> <span dir=\"rtl\">מה מ׳</span> (Y. <span dir=\"rtl\">הניית מ׳</span>; h. taxt <span dir=\"rtl\">מה בצע</span>). <span class=\"citation\">Targ. Ex. XXI, 30</span> (h. text <a href=\"#\" data-headword=\"כֹּפֶר\">כֹּפֶר</a>); a. fr.—<span class=\"citation\">B. Kam. 15ᵃ</span> <span dir=\"rtl\">פלגא נזקא מ׳</span> the payment of ‘half-damage’ is considered as a due indemnity, opp. <a href=\"#\" data-headword=\"קְנָסָא\">קנסא</a> penalty. <span class=\"citation\">Ib. 108ᵃ</span> <span dir=\"rtl\">תרי גווני מ׳</span> two kinds of indemnity (for the same action); <span class=\"citation\">ib.</span> <span dir=\"rtl\">תרי ממונא</span> two indemnities; a. fr.</div>","alt":["מָמוֹנָא"]},"13629":{"h":"מְמוּנֶּה","r":"M01653","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מני\">מָנָה</a>) <i>appointed, deputy, superintendent</i>, in gen. <i>officer</i>. <span class=\"citation\">Tosef. Pes. II</span> (<span class=\"citation\">III), 11</span> <span dir=\"rtl\">זונין הממ׳</span>; <span class=\"citation\">Pes. 49ᵃ</span> מ׳ של ר&quot;ג Zunin the deputy of Rabban G. (superintendent of the College). <span class=\"citation\">Sot. 42ᵃ</span> <span dir=\"rtl\">שיש מ׳ על גביו</span> who has a superior in office. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">סגן לאו מ׳ הוא</span> the deputy high priest is no active officer. <span class=\"citation\">Snh. II, 1</span> <span dir=\"rtl\">המ׳ ממצעו וכ׳</span> the <i>m’munneh</i> places him between himself and the people; <span class=\"citation\">ib. 19ᵃ</span> <span dir=\"rtl\">היינו סגן היינו מ׳</span> the <i>sagan</i> (<span class=\"citation\">Tosef. ib. IV, 1</span>) is the same as the <i>m’munneh</i> (in Mish. l. c.), i.e. the deputy high priest. <span class=\"citation\">Shek. V, 4</span> <span dir=\"rtl\">שהוא מ׳ על וכ׳</span> who was the superintendent of seals &amp;c.; a. fr.—Pl. <span dir=\"rtl\">מְמוּנִּים</span>, <span dir=\"rtl\">מְמוּנִּין</span>. <span class=\"citation\">Ib. 1</span> <span dir=\"rtl\">אלו הן המ׳ וכ׳</span> those were the special officers in the Temple; a. e.</div>","alt":[]},"13630":{"h":"מְמוּשׁ","r":"M01654","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוּשׁ\">מוּשׁ</a>) <i>touch, feeling</i>. <span class=\"citation\">Targ. Y. II, Gen. XXVII, 22</span> (Y. I <span dir=\"rtl\">מַמַּשׁ … מֵימַשׁ</span>).</div>","alt":[]},"13631":{"h":"מְמוֹתָא","r":"M01655","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוּת\">מוּת</a>) <i>pestilence, death</i>. <span class=\"citation\">Targ. Ps. LXXVIII, 50</span> (Var. <a href=\"#\" data-headword=\"מוֹתָנָא\">מוֹתָנָא</a>).—Constr. <a href=\"#\" data-headword=\"מְמַת\">מְמַת</a>. <span class=\"citation\">Targ. Jer. XVI, 4</span>; a. e.</div>","alt":[]},"13632":{"h":"מֵמְזוּר","r":"M01656","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מָזַר\">מָזַר</a>) <i>twisted yarn, cord</i>. <span class=\"citation\">Y. Sabb. VII, 10ᶜ</span> top.</div>","alt":[]},"13633":{"h":"מַמְזִיג","r":"M01657","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְזַג\">מְזַג</a>) <i>druggist</i>. <span class=\"citation\">Targ. Y. Ex. XXX, 25</span>; <span class=\"citation\">35</span>, v. <a href=\"#\" data-headword=\"מְזַג\">מְזַג</a>.</div>","alt":[]},"13634":{"h":"מַמְזֵיר־","r":"M01658","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"מַמְזֵר\">מַמְזֵר</a>.</div>","alt":[]},"13635":{"h":"מַמְזֵר","r":"M01659","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , sec. r. of <span dir=\"rtl\">זר</span>, cmp. <span dir=\"rtl\">מַמְגֻּרָה</span>, <a href=\"#\" data-headword=\"מִמְכָּר\">מִמְכָּר</a>, v. Arnheim Hebr. Gr. p. 173) [<i>rejected, outcast</i>,] <i>bastard</i>. <span class=\"citation\">Yeb. IV, 13</span> <span dir=\"rtl\">איזהו מ׳ כל שאר וכ׳</span> who is a <i>mamzer</i>? The issue of any connection forbidden in the Torah; (oth. opin.) <span dir=\"rtl\">כל שחייבין עליו כרת וכ׳</span> the issue of a connection forbidden under the penalty of extinction; a. fr.—Pl. <a href=\"#\" data-headword=\"מַמְזֵרִי\">מַמְזֵרִים</a>, <a href=\"#\" data-headword=\"מַמְזֵרִי\">מַמְזֵרִין</a>, <a href=\"#\" data-headword=\"מַמְזֵרָא\">מַמְזֵי׳</a>. <span class=\"citation\">Kidd. III, 13</span> <span dir=\"rtl\">יכולין מ׳ ליטהר</span> there is a possibility for the issue of bastards to be rehabilitated. <span class=\"citation\">Yeb. VIII, 3</span>. Y. ib. 9ᶜ bot. <span dir=\"rtl\">מַמְזֵירֵיהֶן</span> the bastards among them; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"מַמְזֶרֶת\">מַמְזֶרֶת</a>. <span class=\"citation\">Tosef. Kidd. V, 2</span>. <span class=\"citation\">Yeb. 78ᵇ</span>; a. fr.</div>","alt":[]},"13636":{"h":"מַמְזֵרָא","r":"M01660","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Deut. XXIII, 3</span>.—<span class=\"citation\">Yeb. 78ᵇ</span>; a. e.—<i>Fem</i>. <a href=\"#\" data-headword=\"מַמְזֶרֶת\">מַמְזֵירְתָּא</a>, <a href=\"#\" data-headword=\"מַמְזֶרֶת\">מַמְזֵרְתָּה</a>. <span class=\"citation\">Lev. R. s. 32</span>; <span class=\"citation\">Y. Yeb. VIII, 9ᶜ</span> bot. <span dir=\"rtl\">שמע קלון קריין ממזירא ומ׳</span> he heard people call (certain persons) bastards.</div>","alt":["מַמְזֵי׳"]},"13637":{"h":"מַמְזֵרוּת","r":"M01661","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַמְזֵרָא\">preced.</a>) <i>the legal condition of a mamzer, bastardship</i>. <span class=\"citation\">Y. Gitt. IV, beg. 45ᶜ</span> <span dir=\"rtl\">שלא תבוא לידי מ׳</span> in order to prevent cases of bastardship. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בניה באין לידי מ׳</span> her children will be subjected to the restrictions of &amp;c. <span class=\"citation\">Y. Kidd. I, 58ᵈ</span> top <span dir=\"rtl\">מ׳ בנתים ואת וכ׳</span> the difference between the two opinions concerns bastardship, and you say so (that the several followers of the two opinions did not hesitate to intermarry)?; <span class=\"citation\">Y. Yeb. I, end, 3ᵇ</span> <a href=\"#\" data-headword=\"ממזרית\">ממזרית</a> (corr. acc.). <span class=\"citation\">Yoma 18ᵇ</span> <span dir=\"rtl\">וממלא … מ׳</span> and fills the world with cases of bastardship; <span class=\"citation\">Yalk. Lev. 617</span>; (<span class=\"citation\">Yeb. 37ᵇ</span> <span dir=\"rtl\">ממזרין</span>; a. e.</div>","alt":["מַמְזֵי׳"]},"13638":{"h":"מַמְזֵרִי","r":"M01662","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַמְזֵרוּת\">preced.</a>) <i>descendant of a mamzer, belonging to the mamzer class</i>. <span class=\"citation\">Kidd. IV, 1</span>; <span class=\"citation\">Tosef. ib. V, 1</span>.</div>","alt":["מַמְזֵי׳"]},"13639":{"h":"ממזרית","r":"M01663","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַמְזֵרוּת\">מַמְזֵרוּת</a></div>","alt":[]},"13640":{"h":"מַמְזֶרֶת","r":"M01664","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַמְזֵר\">מַמְזֵר</a>, <a href=\"#\" data-headword=\"מַמְזֵרָא\"><a href=\"#\" data-headword=\"מַמְזֵרָא\">מַמְזֵרָא</a>.</a></div>","alt":["מַמְזֵרְתָּא","מַמְזֵרְתָּה"]},"13641":{"h":"מָמִיקְנָא","r":"M01665","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוּק\">מוּק</a>) <i>scorner</i>. <span class=\"citation\">Targ. Prov. IX, 7</span>; a. fr.—Pl. <span dir=\"rtl\">מְמִיקְנֵי</span>, <a href=\"#\" data-headword=\"מְמִיקְנוּתָא\">מְמִקְ׳</a>. <span class=\"citation\">Targ. Ps. I, 1</span>; a. e.—<span class=\"citation\">Ib. XXXV, 16</span> מְמִיקְנַיָּא <i>scorning words</i> (ed. Wil. <a href=\"#\" data-headword=\"מְמִיקְנוּתָא\">מְמַקְ׳</a>).</div>","alt":["מָמִקְ׳"]},"13642":{"h":"מְמִיקְנוּתָא","r":"M01666","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָמִיקְנָא\">preced.</a>) <i>scorn</i>. <span class=\"citation\">Targ. Prov. I, 22</span>; a. e.).</div>","alt":["מְמִקְ׳"]},"13643":{"h":"מִמְכָּר","r":"M01667","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>sale</i>. <span class=\"citation\">B. Bath. 155ᵇ</span> <span dir=\"rtl\">מִמְכָּרָהּ מ׳</span> her sale is valid.—<span class=\"citation\">Ib.</span> <span dir=\"rtl\">מִמְכָּרָן מ׳</span> their sale &amp;c.; a. e.—מקח ומ׳ <i>commerce, commercial transactions</i>. <span class=\"citation\">B. Mets. 79ᵇ</span>; a. e.</div>","alt":[]},"13644":{"h":"ממכתא","r":"M01668","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XV, 13</span>, read with ed. Lag.: <a href=\"#\" data-headword=\"מַכִּיכְתָּא\">מַכִּיכְתָּא</a>.</div>","alt":[]},"13645":{"h":"מֶמֶל","r":"M01669","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (מָלַל II) <i>crushing tool, press-beam</i> (or <i>stone</i>) <i>for olives; mill</i>. <span class=\"citation\">B. Bath. IV, 5</span>; expl. <span class=\"citation\">ib. 67ᵇ</span> <a href=\"#\" data-headword=\"מַפְרַעְתָּא\">מַפְרַכְתָּא</a>. <span class=\"citation\">Tosef. Ter. III, 13</span> <span dir=\"rtl\">ניתן לתוך המ׳ ומהלך וכ׳</span> when he puts them in the mill and walks over them crosswise; Y. ib. III, 42ᵇ top <span dir=\"rtl\">תחת המ׳</span>. <span class=\"citation\">Maasr. I, 7</span> מבין המ׳ Mish. ed. (Bab. ed. <span dir=\"rtl\">מבית המ׳</span>; Y. ed. a. Ms. M. <span dir=\"rtl\">מן המ׳</span>) from the pulp under the press; Tosef. ib. I, 7 <span dir=\"rtl\">המאמל</span> ed. Zuck. (Var. <span dir=\"rtl\">הממל</span>, <span dir=\"rtl\">המָלוּל</span>).</div>","alt":[]},"13646":{"h":"מַמָּל","r":"M01670","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Mammal</i>. <span class=\"citation\">Tosef. Erub. IV</span> (<span class=\"citation\">III), 17</span> <span dir=\"rtl\">בית מ׳</span> the family of M.; Y. ib. IV, 22ᵃ <a href=\"#\" data-headword=\"ממה\">ממה</a> (corr. acc.).—<span class=\"citation\">Yeb. 105ᵃ</span>; <span class=\"citation\">Y. Bets. I, 60ᵇ</span> top, a. fr. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"בָּא I\">בא</a>) <span dir=\"rtl\">אבא בר מ׳</span></span>.</div>","alt":[]},"13647":{"h":"מַמְלָא I","r":"M01671","html":"<div class=\"sense\"><i>ore</i>, v. <a href=\"#\" data-headword=\"מִלְלָא\">מִלְלָא</a>.</div>","alt":[]},"13648":{"h":"מַמְלָא II","r":"M01672","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Mamla</i>, a place whose inhabitants were short-lived. <span class=\"citation\">Gen. R. s. 59</span>, beg.; Midr. Sam. ch. VIII; a. e.; v. <a href=\"#\" data-headword=\"מַמּוּלָּאֵי\">מַמּוּלָּאֵי</a>.</div>","alt":[]},"13649":{"h":"מַמְלָל","r":"M01673","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (מְלַל II) <i>speech</i>. <span class=\"citation\">Targ. Gen. XI, 1</span>. <span class=\"citation\">Targ. Ex. XXXIII, 11</span> (h. text <span dir=\"rtl\">פנים</span>); a. fr.</div>","alt":[]},"13650":{"h":"מִמְסָךְ","r":"M01674","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>mixture, mixed drink</i>. <span class=\"citation\">Num. R. s. 10</span> אין מ׳ אלא יין ביין <i>mimsakh</i> (<span class=\"citation\">Prov. XXIII, 30</span>) means a mixture of wine with wine.</div>","alt":[]},"13651":{"h":"מַמְצִיא","r":"M01675","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Mamtsi</i>, a Palestinian border town (v. Hildesh. Beitr., p. 26). <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span> <span dir=\"rtl\">מ׳ דאבהתא</span>; <span class=\"citation\">Tosef. Shebi. IV, 11</span> <span dir=\"rtl\">מ׳ דעכתא</span> (Var. <span dir=\"rtl\">דעב׳</span>, <span dir=\"rtl\">דגתא</span>); <span class=\"citation\">Sifré Deut. 51</span> <span dir=\"rtl\">מצי רעבתה</span>; <span class=\"citation\">Yalk. Deut. 874</span> <span dir=\"rtl\">מניא רעבת׳</span>.</div>","alt":[]},"13652":{"h":"מַמְצְיָיא","r":"M01676","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Mamtsia</i>. <span class=\"citation\">Y. Succ. IV, 54ᵇ</span> bot., v. <a href=\"#\" data-headword=\"מוֹצָא II\"><span dir=\"rtl\">מוֹצָא</span> II</a>.</div>","alt":[]},"13653":{"h":"מָמִקְנָא","r":"M01677","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">ממיק׳</span>.</div>","alt":["מְמִקְנוּתָא"]},"13654":{"h":"מִמְקָק","r":"M01678","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָקַק\">מָקַק</a>) <i>decay, worm-eaten material</i>. <span class=\"citation\">Sabb. IX, 6</span> (<span class=\"citation\">90ᵃ</span>) <span dir=\"rtl\">ממ׳ ספרים וממ׳ וכ׳</span> Y. ed., Ms. O. a. Ar. (v. Rabb. D. S. a. l. note 60; ed. <a href=\"#\" data-headword=\"מֶקֶק\">מֶקֶק</a>) worm-eaten sacred books and their worm-eaten bands.</div>","alt":[]},"13655":{"h":"מַמְרֵא I","r":"M01679","html":"<div class=\"sense\"> (b. h.) pr. n. m. (or pl.) <i>Mamre</i>. <span class=\"citation\">Gen. R. s. 42</span>, end (ref. to <span class=\"citation\">Gen. XIV, 13</span>) <span dir=\"rtl\">אתרא … מ׳</span> it was a place called M.; <span dir=\"rtl\">גברא … מ׳</span> it was a man &amp;c.—<span class=\"citation\">Men. 85ᵃ</span> name of an Egyptian sorcerer, v. <a href=\"#\" data-headword=\"יוֹחָנִי\">יוֹחָנִי</a>.</div>","alt":[]},"13656":{"h":"מַמְרֵא II","r":"M01680","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מרי I\">מרי</a>, <a href=\"#\" data-headword=\"מרי II\">מָרָה</a>) <i>rebellious</i>, <span dir=\"rtl\">(<span dir=\"rtl\">על פי ב&quot;ד</span>) <span dir=\"rtl\">זקן מ׳</span></span> an elder disregarding the decision of the Supreme Court. <span class=\"citation\">Snh. XI, 1</span> (<span class=\"citation\">84ᵇ</span>); 2 (86ᵇ). <span class=\"citation\">Y. Sabb. I, 3ᵈ</span>; a. e.</div>","alt":[]},"13657":{"h":"מַמְרוּ","r":"M01681","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>Mamru</i>, name of a plant. <span class=\"citation\">Gitt. 69ᵃ</span>, v. <a href=\"#\" data-headword=\"חוּמְתִי\">חוּמְתִי</a>.</div>","alt":[]},"13658":{"h":"מַמְרִיאָטִינוֹס","r":"M01682","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְוָרִטִינוֹס\">מְוָרִיטִינוֹס</a></div>","alt":[]},"13659":{"h":"מְמַרַע","r":"M01683","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרַע I\"><span dir=\"rtl\">מְרַע</span> I</a></div>","alt":["מְמָרְעָא"]},"13660":{"h":"מַמָּשׁ","r":"M01684","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָשַׁשׁ\">מָשַׁשׁ</a>) [<i>something tangible</i>,] <i>substance; substantial, real</i>. <span class=\"citation\">Ex. R. s. 14</span>, beg. (ref. to <span dir=\"rtl\">וימש</span>, <span class=\"citation\">Ex. X, 21</span>) <span dir=\"rtl\">שהיה בו מ׳</span> there was substance in the darkness (it was thick). <span class=\"citation\">Ab. Zar. 67ᵃ</span> <span dir=\"rtl\">כל שטעמו ומַמָּשׁוֹ אסור</span> anything the taste of which (in a mixture) as well as its substance is forbidden. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">טעמו ולא ממשו אסור</span> a mixture in which there is the taste of a forbidden thing whose substance, however, is not visible, is forbidden. <span class=\"citation\">Ḥull. 108ᵃ</span> <span dir=\"rtl\">טעמו ולא ממשו בעלמא דאורייתא</span> that a forbidden substance should ritually affect a mixture in which is left a taste after its removal, is in all cases a Biblical rule. <span class=\"citation\">Snh. 63ᵇ</span> <span dir=\"rtl\">יודעין … שאין בו מ׳ וכ׳</span> the Israelites knew very well that there is no reality in idols, yet they worshipped them for the sake of being permitted public licentiousness. <span class=\"citation\">B. Kam. 83ᵇ</span> <span dir=\"rtl\">עין מ׳</span>, v. <a href=\"#\" data-headword=\"מָמוֹן\">מָמוֹן</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מיתה מ׳</span> actual putting to death. <span class=\"citation\">Snh. 64ᵃ</span>, v. <a href=\"#\" data-headword=\"דָּבֵק\">דָּבַק</a>; a. v. fr.—<span class=\"citation\">Y. Ber. III, 6ᵈ</span> bot. <span dir=\"rtl\">מַשְׁמָשָׁהּ קיים</span> its substance remains (on the skin, even if dried up).</div>","alt":[]},"13661":{"h":"מַמָּשׁ ²","r":"M01685","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. II, Deut. XXXII, 17</span>.—<span class=\"citation\">Sabb. 152ᵇ</span> bot. <span dir=\"rtl\">דאית ביה מ׳</span> Ms. O. a. Ar. (ed. <a href=\"#\" data-headword=\"מְשַׁשׁ II\">מַשָּׁשָׁא</a>, v. Rabb. D. S. a. l. note 10) that there is substance in him (that it is not a mere apparition).—[<a href=\"#\" data-headword=\"מַמָּשׁ\">מַמַּשׁ</a> constr. <i>touch</i>, v. <a href=\"#\" data-headword=\"מְמוּשׁ\">מְמוֹש</a>.]</div>","alt":["מַמָּשָׁא"]},"13662":{"h":"מִמְשָׁל","r":"M01686","html":"<div class=\"sense\"><i>parable</i>, v. <a href=\"#\" data-headword=\"מָשָׁל\">מָשָׁל</a>.</div>","alt":["מִמְשָׁלָה"]},"13663":{"h":"מֶמְשָׁלָה","r":"M01687","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>rulership, power</i>. <span class=\"citation\">Koh. R. to X, 4</span> <span dir=\"rtl\">כי באתה לך מ׳ וכ׳</span> if rulership happens to be thine, leave not thy humility.—<span class=\"citation\">Gen. R. s. 53</span> <span dir=\"rtl\">נטלה … חמ׳</span> that rulership was taken from them; a. e.—[<span class=\"citation\">Gen. R. s. 20</span>, read: <span dir=\"rtl\">מְמַשְּׁלָהּ</span>, v. <a href=\"#\" data-headword=\"מָשַׁל I\">מָשַׁל</a>.]</div>","alt":[]},"13664":{"h":"מְמַשְׁמְשָׁנִית","r":"M01688","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשְׁמְשָׁנִית\">מַשְׁמְשָׁנִית</a></div>","alt":[]},"13665":{"h":"מְמַת","r":"M01689","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְמוֹתָא\">מְמוֹתָא</a></div>","alt":[]},"13666":{"h":"ממתו\"ס","r":"M01690","html":"<div class=\"sense\"> a combination of each first letter of the words <span dir=\"rtl\">מ̇נא מ̇נא ת̇קל ו̇פרס̇ין</span> divided off in groups of three letters each (<span class=\"citation\">Dan. V, 25</span>). <span class=\"citation\">Snh. 22ᵃ</span>; <span class=\"citation\">Cant. R. to III, 4</span>; v. <a href=\"#\" data-headword=\"אאלר\">אאלר&quot;ן</a></div>","alt":[]},"13667":{"h":"מַמְתַּקִּים","r":"M01691","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>sweet things</i>. Mekh. Yithro, Amal., s. 1.</div>","alt":["מַמְתַּקִּין"]},"13668":{"h":"מִן","r":"M01692","html":"<div class=\"sense\"> (b. h.) <i>from, of; more</i> (or <i>less</i>) <i>than</i>. <span class=\"citation\">Ab. Zar. 18ᵃ</span> <span dir=\"rtl\">מן השמים ירחמו</span> from heaven they will have mercy (on me), i.e. I trust in God. <span class=\"citation\">Sabb. 21ᵇ</span> <span dir=\"rtl\">המהדרין מן המהדרין</span> v. <a href=\"#\" data-headword=\"הָדַר\">הָדַר</a>.—<span dir=\"rtl\">מן המובחר</span>, v. <a href=\"#\" data-headword=\"בָּחַר\">בָּחַר</a>; <span dir=\"rtl\">מן המומחה</span>, v. <a href=\"#\" data-headword=\"מוּמְחֶה\">מוּמְחֶה</a>.—<span class=\"citation\">Tem. 28ᵃ</span> מן הבהמה להוציא וכ׳ ‘of the cattle’ (<span class=\"citation\">Lev. I, 2</span>) intimates the exclusion of &amp;c.; a. v. fr.—Prefix <a href=\"#\" data-headword=\"מִ־\">מִ־</a>, <a href=\"#\" data-headword=\"מִי I\">מָי־</a>, <span dir=\"rtl\">מֵ־</span>, <a href=\"#\" data-headword=\"מִי I\">מֵי־</a> q. v.—<a href=\"#\" data-headword=\"מִנַּיִן\">מִנַּיִן</a>, <a href=\"#\" data-headword=\"מִנַּיִין\">מִנַּיִין</a>, <a href=\"#\" data-headword=\"מִינַּיִּין\">מִינַּיִין</a> (= b. h. <a href=\"#\" data-headword=\"מָאִין\">מֵאַיִן</a>, v. <a href=\"#\" data-headword=\"אַיִן I\">אַיִן</a>) <i>whence?</i>, <i>whence is it proven?</i>—<span class=\"citation\">Yoma 32ᵃ</span> <span dir=\"rtl\">מ׳ לחמש וכ׳</span> whence is derived the regulation about five immersions &amp;c.? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ומ׳ שכל טבילה וכ׳</span> and whence is the rule derived that each immersion requires &amp;c.? <span class=\"citation\">Ib. 44ᵃ</span> <span dir=\"rtl\">אין לי אלא … מ׳</span> this would prove to me only in favor of …, whence do you derive that the same applies to …?; a. v. fr.</div>","alt":[]},"13669":{"h":"מִן ²","r":"M01693","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. I, 2</span>; a. v. fr.—With suffixes of pers. pron. <a href=\"#\" data-headword=\"מִנִּי\">מִנִּי</a>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a> <i>from me</i>; <span dir=\"rtl\">מִנָּךְ</span>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a> <i>from thee;</i> <span dir=\"rtl\">מִנֵּיה</span>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a> <i>from him</i>, it &amp;c. Ib. XXII, 12. Ib. III, 3; a. fr.—<span class=\"citation\">Y. Ber. II, 5ᵃ</span> bot. <span dir=\"rtl\">מן הן דסלק</span> to where he had come from. <span class=\"citation\">Sabb. 80ᵇ</span> <span dir=\"rtl\">מן דיליה דא ליה</span> this came to him from his own doing. <span class=\"citation\">Sot. 40ᵃ</span> <span dir=\"rtl\">ומאי נפקא ליך מִינָּהּ</span> and what difference does it make? <span dir=\"rtl\">מִנִּי ומִנֵּיה יתקלס וכ׳</span> through myself and him the Most High is exalted. <span class=\"citation\">B. Kam. 18ᵃ</span> <span dir=\"rtl\">קאזיל מיניה מיניה</span> it was lost through its (the chicken’s) action alone. <span class=\"citation\">Y. Peah VII, 20ᵇ</span> <span dir=\"rtl\">מיניה וביה הוא</span> (the sweetness) is entirely its own (no honey has been added). <span class=\"citation\">Snh. 39ᵇ</span>, v. <a href=\"#\" data-headword=\"אִבָּא\">אִבָּא</a>; a. fr.—<span dir=\"rtl\">לא כולא מיניה</span>, <span dir=\"rtl\">לא כל כמיניה</span> it is not at all in his power; v. <a href=\"#\" data-headword=\"כּוֹל\">כּוֹלָא</a>.—מן ד־ <i>from the time that, after</i>; <i>from the fact that; when</i>; <i>because</i>. <span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">מן דאכלון</span> after they had eaten; a. v. fr.; v. <a href=\"#\" data-headword=\"מִדְּ־\">מִדְּ־</a>.</div>","alt":["מִין"]},"13670":{"h":"מָן I","r":"M01694","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>portion, food</i>. <span class=\"citation\">Num. R. s. 12</span> (play on <span dir=\"rtl\">א̇ר̇ג̇מ̇ן̇</span>) the sun <span dir=\"rtl\">שיצרו הקב&quot;ה לארוג מן וכ׳</span> whom the Lord has created to weave (ripen) food for creatures; <span dir=\"rtl\">ואין מן אלא פירות וכ׳</span> <i>man</i> means fruits and food (with ref. to <span dir=\"rtl\">וימן</span>, <span class=\"citation\">Dan. I, 5</span>).—Esp. <span dir=\"rtl\">מָּן</span>(<a href=\"#\" data-headword=\"שַׁרְיֵי\">הַ</a>) <i>the manna</i> of the desert. <span class=\"citation\">Ex. R. s. 25</span>. Tanḥ. <span class=\"citation\">B’shall. 20</span>; Mekh. ib., Vayassa, s. 2 <span dir=\"rtl\">אוכלי המן</span> those eating manna (not troubling themselves about to-morrow). <span class=\"citation\">Yoma 75ᵃ</span>; a. fr.</div>","alt":[]},"13671":{"h":"מַן I","r":"M01695","html":"<div class=\"sense\"> (<i>a day’s</i>) <i>support</i>. <span class=\"citation\">Succ. 39ᵇ</span> <span dir=\"rtl\">בכדי מן</span> for as much only as is needed for the day. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דהאי מ׳ וכ׳</span> that <i>man</i> means support, v. preced.—Esp. <a href=\"#\" data-headword=\"מַנָּא\">מַנָּא</a> <i>the manna</i>. <span class=\"citation\">Targ. Ex. XVI, 31</span>. <span class=\"citation\">Targ. Y. ib. 27</span>; a. e. (some ed. <a href=\"#\" data-headword=\"מָאן\">מָנָא</a>).</div>","alt":["מַנָּא"]},"13672":{"h":"מַן","r":"M01696","html":"<div class=\"sense\"><i>who?, what?</i>, v. <a href=\"#\" data-headword=\"מַאן\">מַאן</a>. <span class=\"citation\">Targ. Gen. XXIV, 23</span>. <span class=\"citation\">Ib. XXXIII, 8</span> (ed. Berl. <a href=\"#\" data-headword=\"מָא\">מָא</a>; oth. ed. <span dir=\"rtl\">מאן</span>); a. fr.—Emphatic. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"מָאן\">מָנָא</a>) <a href=\"#\" data-headword=\"מְנֵי\">מְנָא</a></span>. <span class=\"citation\">Targ. Ps. XXXIX, 5</span>. <span class=\"citation\">Targ. Prov. IV, 19</span>; a. fr.</div>","alt":["מָן II"]},"13673":{"h":"מָן III","r":"M01697","html":"<div class=\"sense\"><i>thing, vessel, garment</i>; <i>coulter</i>, v. <a href=\"#\" data-headword=\"מָאן\">מָאן</a>.</div>","alt":["מָנָא I"]},"13674":{"h":"מְנָא I","r":"M01698","html":"<div class=\"sense\"><i>who?, what?</i>, v. <a href=\"#\" data-headword=\"מַן\"><span dir=\"rtl\">מַן</span> II</a>.</div>","alt":["(מָנָא  II)"]},"13675":{"h":"מְנָא II","r":"M01699","html":"<div class=\"sense\"> (apocop. of <span dir=\"rtl\">מִן אָן</span> = h. <a href=\"#\" data-headword=\"מִנַּיִן\">מִנַּיִן</a>; v. <a href=\"#\" data-headword=\"מְנָן\">מְנָן</a>) <i>whence?; whence is it proven?</i> <span class=\"citation\">B. Kam. 117ᵃ</span> <span dir=\"rtl\">ומ׳ תימרא דמקנסא וכ׳</span> but whence will you prove that we draw no analogy from fines? <span class=\"citation\">Ib. 44ᵃ</span> bot. <span dir=\"rtl\">ומ׳ ידעינן וכ׳</span> and how do we know &amp;c.? <span class=\"citation\">Snh. 61ᵇ</span> <span dir=\"rtl\">מ׳ אמינא לה</span> whence (on what evidence) do I say so?; a. fr.—<span dir=\"rtl\">מנא הני מילי</span>, <span dir=\"rtl\">מְנָהַנֵּי מילי</span>, v. <a href=\"#\" data-headword=\"מִילָּא II\"><span dir=\"rtl\">מִילָּא</span> II</a>.—<a href=\"#\" data-headword=\"מְנָאן\">מְנָאן</a>. <span class=\"citation\">Gen. R. s. 11</span>, v. <a href=\"#\" data-headword=\"יְדַע\">יְדַע</a>.—<span dir=\"rtl\">מנא לן</span>, <a href=\"#\" data-headword=\"מְנָלָן\">מְנָלָן</a> <i>whence do we have this?, how do we know?</i> <span class=\"citation\">Ber. 7ᵃ</span>. <span class=\"citation\">Meg. 2ᵃ</span> <span dir=\"rtl\">מ׳ מ׳ כדבעינן וכ׳</span> whence do we derive this?—Whence we derive this? (you ask, as if it were a law requiring an intimation in the Biblical text, while it is merely a measure of accommodation,) as we were going to explain further on. <span class=\"citation\">Ib. 20ᵃ</span>; a. v. fr.</div>","alt":[]},"13676":{"h":"מַנָּא","r":"M01700","html":"<div class=\"sense\"><i>manna</i>, v. <a href=\"#\" data-headword=\"מַן I\"><span dir=\"rtl\">מַן</span> I</a>.</div>","alt":["(מָנָא)"]},"13677":{"h":"מְנֵא","r":"M01701","html":"<div class=\"sense\"><i>to count</i>, v. <a href=\"#\" data-headword=\"מְנֵי\">מְנִי</a>.</div>","alt":[]},"13678":{"h":"מָנָא III","r":"M01702","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Mana</i> (<i>Mona</i>), name of several Amoraim. <span class=\"citation\">Y. Sabb. I, 2ᶜ</span> top. <span class=\"citation\">Y. Dem. IV, 24ᵃ</span> top; <span class=\"citation\">Taan. 23ᵇ</span> <a href=\"#\" data-headword=\"מָנַי\">מָנִי</a>.—<span class=\"citation\">Y. Ab. Zar. II, 42ᵃ</span> top; a. fr.—V. Fr. M’bo, p. 114ᵇ, sq.</div>","alt":["(מוֹנָא)"]},"13679":{"h":"מָנָא IV","r":"M01703","html":"<div class=\"sense\"><i>a weight</i>, v. <a href=\"#\" data-headword=\"מָנֶה\">מָנֶה</a>.</div>","alt":[]},"13680":{"h":"מנאין","r":"M01704","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to VII, 7</span>, <span dir=\"rtl\">תרין מ׳</span>, read with <span class=\"citation\">Y. Taan. IV, 68ᵃ</span>: <span dir=\"rtl\">מִנּוּיִין</span>, v. <a href=\"#\" data-headword=\"מִינּוּי\">מִינּוּי</a> ch.</div>","alt":[]},"13681":{"h":"מְנָאן","r":"M01705","html":"<div class=\"sense\"><i>whence?</i>, v. <a href=\"#\" data-headword=\"מְנָא II\"><span dir=\"rtl\">מְנָא</span> II</a>.</div>","alt":[]},"13682":{"h":"מָנְבָּז","r":"M01706","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּנְבָּז\">מוּנְבָּז</a></div>","alt":[]},"13683":{"h":"מַנְגְּדָנָא","r":"M01707","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְגַד\">נְגַד</a>) <i>lasher</i> at court. <span class=\"citation\">Yoma 15ᵃ</span>; <span class=\"citation\">54ᵇ</span> sq.; <span class=\"citation\">Zeb. 38ᵃ</span> (expl. <span dir=\"rtl\">כמצליף</span>) <span dir=\"rtl\">מחוי … כמ׳</span> R. Judah showed it by imitating the movement of the lasher, v. <a href=\"#\" data-headword=\"טִבְרֵר\">טִבְרֵר</a>.</div>","alt":[]},"13684":{"h":"מנגטן","r":"M01708","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַנְגָּנוֹן\">מַנְגָּנוֹן</a></div>","alt":[]},"13685":{"h":"מנגיאות","r":"M01709","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַנְגָּנָא\">next w.</a></div>","alt":[]},"13686":{"h":"מַנְגָּנָא","r":"M01710","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַנְגָּנוֹן\">next w.</a>) <i>any means of charming; art, contrivance</i>. Tanḥ. Lekh 15 (play on <span dir=\"rtl\">מִגֵּן</span>, <span class=\"citation\">Gen. XIV, 20</span>) <span dir=\"rtl\">מ׳ עשה הקב&quot;ה וכ׳</span> (ed. Bub. ib. 19 <span dir=\"rtl\">מגינה</span>, corr. acc.) the Lord made a charm …, for Abraham took dust &amp;c. <span class=\"citation\">Zeb. 116ᵇ</span> Ms. M. <a href=\"#\" data-headword=\"מַגָּאנָא\">מַגָּאנָא</a>; <span class=\"citation\">Yalk. Lev. 579</span> <a href=\"#\" data-headword=\"מַגָּנָה\">מַגָּנָה</a> = <span dir=\"rtl\">מַנְגָּ׳</span>, v. <a href=\"#\" data-headword=\"מָר\"><span dir=\"rtl\">מָרָא</span> II</a>.—Pl. <span dir=\"rtl\">מַנְגְּנָאוֹת</span>. <span class=\"citation\">Gen. R. s. 43</span> <span dir=\"rtl\">כמה מ׳ עשיתי וכ׳</span> (Ar. <a href=\"#\" data-headword=\"מַגָּנִיּוֹת\">מַגָּנִיּוֹת</a>) how many arts did I not contrive to bring them under thy power?; Yalk. ib. 74 <a href=\"#\" data-headword=\"מנגיאות\">מנגיאות</a> (corr. acc.).—Esth. R. end (ref. to <span class=\"citation\">Ps. LXVI, 3</span>) <span dir=\"rtl\">מה דחילין אינון מַנְגָּנוֹת שלך וכ׳</span> (corr. acc.) how fearful are thy contrivances; those to be slain slay their slayers &amp;c.; <span class=\"citation\">Midr. Till. to Ps. XXII</span> <span dir=\"rtl\">מַנְגָּנַיָּא דילך</span>; <span class=\"citation\">Yalk. Ex. 225</span>; <span class=\"citation\">Yalk. Ps. 790</span>; Pesik. B’shall., p. 81ᵃ <span dir=\"rtl\">מַנְגָנַיָּיה</span>.</div>","alt":[]},"13687":{"h":"מַנְגָּנוֹן","r":"M01711","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μάγγανον) <a href=\"#\" data-headword=\"מַנְגָּנָא\">same</a>, </div><div class=\"sense\"><b>1)</b> <i>charm, potion</i>. <span class=\"citation\">Gen. R. s. 88</span> <span dir=\"rtl\">מ׳ עשו לו לחנקו</span> (ed. Wil. <a href=\"#\" data-headword=\"מַנְגָּנוֹן\">מַנְגָּנִין</a>, pl.) they prepared a charm for him to choke him.</div><div class=\"sense\"><b>—2)</b> <i>art, contrivance</i>. <span class=\"citation\">Ex. R. s. 18</span> (play on <span dir=\"rtl\">נגינתי</span>, <span class=\"citation\">Ps. LXXVII, 7</span>) <span dir=\"rtl\">מ׳ שעשית וכ׳</span> (ed. Wil. <i>pl.</i>) thy contrivance in Egypt (in not sending the plague of the first-born at once). Ib. <span dir=\"rtl\">מי יודע מ׳ וכ׳</span> (ed. Wil. <a href=\"#\" data-headword=\"נגנין\">נגנין</a>, corr. acc.) who understands thy contrivances at the Red Sea (when those who had drowned the Israelitish children, were drowned)? Tanḥ. B’har 2 <span dir=\"rtl\">הופך אני מ׳ שלי וכ׳</span> (not <span dir=\"rtl\">שלו</span>) I will reverse my plans and make him (the poor) rich &amp;c. Y’lamd. to Deut. VII, 12, quot. in Ar. <span dir=\"rtl\">הפך הקב&quot;ה עליו מ׳</span> the Lord turned the plan (of drowning the Israelites) against him (v. supra).</div><div class=\"sense\"><b>—3)</b> <i>mechanic contrivance, machine</i>. <span class=\"citation\">Lev. R. s. 20</span>, beg. <span dir=\"rtl\">לא היה יודע מ׳ שלו</span> Ar. (ed. <span dir=\"rtl\">מנהגיו</span>) he did not know the mechanism (of the throne of Solomon); Pesik. Aḥăré, p. 168ᵃ <span dir=\"rtl\">מנהג מנגטן שלו</span> (corr. acc.); Tanḥ. Vaëthḥ. 1 <span dir=\"rtl\">מנגנין</span> (corr. acc.).—<span class=\"citation\">Yalk. Esth. 1046</span>; Targ. II Esth. I, 2 <span dir=\"rtl\">במ׳</span> by machinery (in the throne of Solomon).—Pl. <a href=\"#\" data-headword=\"מַנְגָּנוֹן\">מַנְגָּנִין</a>, <a href=\"#\" data-headword=\"מַנְגָּנוֹן\">מַנְגָּנוֹת</a>. Ib. Yalk. l. c. <span dir=\"rtl\">היו מנגנות פוקעים</span> the machinery burst; a. fr. (v. supra).—<span dir=\"rtl\">מַנְגָּנַיָּא</span>, <span dir=\"rtl\">מַנְגָּנַיָּיה</span>, v. <a href=\"#\" data-headword=\"מַנְגָּנָא\">preced.</a></div>","alt":[]},"13688":{"h":"מִנְדָּה","r":"M01712","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span class=\"citation\">Ezra IV, 13</span>; = <a href=\"#\" data-headword=\"מִדָּה\">מִדָּה</a>; cmp. <a href=\"#\" data-headword=\"מַנְדַּע\">מַנְדַּע</a> a. <a href=\"#\" data-headword=\"מַדַּע\">מַדַּע</a>) <i>land-tax</i>. Esth. R. introd.; <span class=\"citation\">Gen. R. s. 64</span>, v. <a href=\"#\" data-headword=\"מִדָּה\">מִדָּה</a>; <span class=\"citation\">Ned. 62ᵇ</span>; <span class=\"citation\">B. Bath. 8ᵃ</span> מ׳ זו מנת המלך <i>mindah</i> is the king’s share (of the crops).</div>","alt":[]},"13689":{"h":"מַנְדּוּ","r":"M01713","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>K’far Mandu</i> (Kafr Menda, north of Sepphoris; v. Sm. Bible Dict. s. v. Madon, a. Fischer a. Guthe Map of Palestine). Pesik. Shub., p. 163ᵇ; <span class=\"citation\">Yalk. Job 906</span>; <span class=\"citation\">Gen. R. s. 52</span> a. <span class=\"citation\">Lev. R. s. 1</span> ed. Wil. <a href=\"#\" data-headword=\"מַנְדִּי\">מנְדִּי</a>.—[<span class=\"citation\">Tosef. Yeb. X, 3</span> <span dir=\"rtl\">כפר מנורי</span> ed. Zuck., Var. <a href=\"#\" data-headword=\"מַנְדִּין\">מַנְדִּין</a>.]</div>","alt":["כְּפַר מ׳"]},"13690":{"h":"מַנְדִּי","r":"M01714","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַנְדּוּ\">preced.</a></div>","alt":[]},"13691":{"h":"מַנְדְּיָאן","r":"M01715","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִדְּיָין\">נִדְּיַין</a></div>","alt":[]},"13692":{"h":"מַנְדִּין","r":"M01716","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַנְדּוּ\">מַנְדּוּ</a></div>","alt":[]},"13693":{"h":"מנדמטין","r":"M01717","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָגִיסְטֵיר\">מָגִיסְטֵיר</a></div>","alt":[]},"13694":{"h":"מַנְדַּע","r":"M01718","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"מַדַּע\">מַדַּע</a>; cmp. <a href=\"#\" data-headword=\"מִנְדָּה\">מִנְדָּה</a>) <i>knowledge, wisdom</i>. <span class=\"citation\">Targ. Y. Deut. I, 13</span> <span dir=\"rtl\">מרי מ׳</span> possessors of knowledge (O., v. <a href=\"#\" data-headword=\"מַדַּע\">מַדַּע</a>). <span class=\"citation\">Targ. Job XXXIII, 3</span>; a. fr.</div>","alt":["מַנְדְּעָא"]},"13695":{"h":"מַנְדָּעוּתָא","r":"M01719","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"מַנְדַּע\">same</a>. <span class=\"citation\">Targ. Koh. IX, 11</span>.</div>","alt":[]},"13696":{"h":"מִנְדַּעַם","r":"M01720","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִדַּעַם\">מִדַּעַם</a></div>","alt":[]},"13697":{"h":"מַנְדַּעְתָּא","r":"M01721","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מִנְדַּעַם\">preced.</a> wds.) <i>sentiment, disposition</i>.—Pl. <a href=\"#\" data-headword=\"מַנְדַּעְתָּא\">מַנְדְּעָתָא</a> (cmp. <a href=\"#\" data-headword=\"דֵּעָה\">דֵּעָה</a>). <span class=\"citation\">Targ. Job XXXVI, 4</span> (some ed. <i>sing</i>.; Ms. <a href=\"#\" data-headword=\"מַנְדַּע\">מנדעא</a>; h. text <span dir=\"rtl\">דעות</span>).</div>","alt":[]},"13698":{"h":"מִנְדְּרוֹן","r":"M01722","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַדְרוֹן\">מַדְּרוֹן</a></div>","alt":["מִנְדְּרָן"]},"13699":{"h":"מנדרנא","r":"M01723","html":"<div class=\"sense\">, <span class=\"citation\">Y. Naz. I, 51ᵃ</span> bot., read: <a href=\"#\" data-headword=\"מַנְזִירְנָא\">מַנְזִרְנָא</a>.</div>","alt":[]},"13700":{"h":"מָנֶה","r":"M01724","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> from which μνᾶ,  [<i>one hundred</i>,] <i>Maneh</i>, a weight in gold or silver, equal to one hundred common or fifty sacred shekels (v. Zuckerm. Talm. Münz. p. 7, sq.). <span class=\"citation\">Bekh. 5ᵃ</span> <span dir=\"rtl\">מ׳ של קודש כפול היה</span> the sacred <i>Maneh</i> was double the weight of the common. <span class=\"citation\">Ib. VIII, 7</span> <span dir=\"rtl\">במ׳ צורי</span> taking the Tyrian <i>M</i>. as a standard. <span class=\"citation\">Ib. 49ᵇ</span> מ׳ צורי … מ׳ של צורי ‘the Tyrian M.’ … means the standard of the Tyrian system (one Sela = 4 Zuz, Rashi). <span class=\"citation\">Keth. I, 2</span> <span dir=\"rtl\">בתולה … מאתים ואלמנה מ׳</span> the widowhood of a maiden is two hundred (Zuz), and that of a widow (remarried) is one hundred (Zuz, a common Shekel). <span class=\"citation\">B. Kam. 90ᵇ</span> <span dir=\"rtl\">מ׳ צורי תנן או מ׳ מדינה תנן</span> does the Mishnah (<span class=\"citation\">Snh. VIII, 6</span>) mean a Tyrian or a country Maneh (twelve and a half Zuz)? <span class=\"citation\">Shebu. VI, 1</span> <span dir=\"rtl\">מ׳ לי בידך</span> thou owest me one hundred denars. <span class=\"citation\">Snh. VIII, 2</span> <span dir=\"rtl\">מ׳ בשר</span> meat of the weight of a Maneh. <span class=\"citation\">Shebi. I, 2</span> <span dir=\"rtl\">ששים מ׳ באיטלקי</span> the weight of sixty M. in the Italian system. <span class=\"citation\">Ker. 6ᵃ</span>; a. fr.—<span class=\"citation\">Erub. 85ᵃ</span> bot. <span dir=\"rtl\">פנו מקום לבן מאה מ׳</span> make room for one worth one hundred M. (in gold).—Trnsf. <span dir=\"rtl\">מ׳ בן פרס</span> a Maneh son of a P’ras (half a Maneh), i.e. <i>a distinguished son of a less distinguished father</i>. <span class=\"citation\">Taan. 21ᵇ</span>.—Pl. <span dir=\"rtl\">מָנִים</span>, <span dir=\"rtl\">מָנִין</span>. Y. Shek. VI, 49ᶜ bot. <span dir=\"rtl\">אלף … מ׳</span> the weight of fifteen hundred M. Ker. l. c.; a. e.—Chald. form: <a href=\"#\" data-headword=\"מָנֵי\">מָנֵי</a>. <span class=\"citation\">Targ. Ez. XLV, 12</span> (Kimḥi <a href=\"#\" data-headword=\"מָאן\">מָנָא</a>).—Pl. <span dir=\"rtl\">מָנִין</span>, <span dir=\"rtl\">מָנַיָּא</span>, <a href=\"#\" data-headword=\"מְנָן\">מָנָן</a>, <span dir=\"rtl\">מָנָאֵי</span>, <span dir=\"rtl\">מָנוֹי</span>. Ib. <span class=\"citation\">Targ. Is. VII, 23</span>. <span class=\"citation\">Targ. I Kings X, 17</span>; a. e.—<span class=\"citation\">Esth. R. to VI, 10</span>; <span class=\"citation\">Lev. R. s. 28</span>.—<span class=\"citation\">Sabb. 133ᵇ</span> <span dir=\"rtl\">שב מ׳ תרבא</span> (not <span dir=\"rtl\">מינאי</span>, v. Rabb. D. S. a. l. note 90) fat weighing seven M. (Rashi: seven <i>portions</i> of fat). <span class=\"citation\">Y. B. Kam. IX, 6ᵈ</span> bot. [read as Tosaf. to Bab. <span class=\"citation\">B. Kam. 100ᵇ</span>:) <span dir=\"rtl\">חמש מנוי עמר וח׳ מ׳ סממנין וכ׳</span> wool worth five M., dyeing material worth five, and ten M. wages. <span class=\"citation\">Y. Meg. IV, 74ᵈ</span> bot. <span dir=\"rtl\">מניי</span> (corr. acc.); a. e.</div>","alt":[]},"13701":{"h":"מָנָה I","r":"M01725","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מָנֶה\">preced.</a>) <i>share, portion</i>. <span class=\"citation\">Bekh. V, 1</span> <span dir=\"rtl\">שוקלין מ׳ כנגד מ׳</span> you must weigh one piece (of the meat of the first-born) against another piece (of secular meat of ascertained weight). <span class=\"citation\">Gitt. 59ᵇ</span>, a. e. <span dir=\"rtl\">ליטול מ׳ מ׳ יפה ראשון</span> that he (the priest) have the privilege of first choice (when a division is made). <span class=\"citation\">Sifré Deut. 53</span>; <span class=\"citation\">Yalk. ib. 875</span> <span dir=\"rtl\">מ׳ יפה</span> the best portion (at the meal). <span class=\"citation\">Yalk. Num. 765</span>, end <span dir=\"rtl\">מלך שבירר לעצמו מ׳ וכ׳</span> a king who selected a portion for himself, and another came and spoke disparagingly of it; a. fr.—Pl. <span dir=\"rtl\">מָנוֹת</span>. <span class=\"citation\">Sabb. 149ᵃ</span>; <span class=\"citation\">Tosef. ib. XVII</span> (<span class=\"citation\">XVIII), 5</span>. <span class=\"citation\">Ib. 4</span> <span dir=\"rtl\">מפיסין על מָנוֹתֵיהֶן</span> cast lots for their portions (at the table); a. e.—V. <a href=\"#\" data-headword=\"מְנָת\">מְנָת</a>.</div>","alt":[]},"13702":{"h":"מָנָה II","r":"M01726","html":"<div class=\"sense\"><i>to count</i>, v. <a href=\"#\" data-headword=\"מני\">מני</a>.</div>","alt":[]},"13703":{"h":"מִנְהָג","r":"M01727","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>conduct, manner, usage</i>. <span class=\"citation\">B. Mets. VII, 1</span> <span dir=\"rtl\">מִנְהַג המדינה</span> the usage of the country. <span class=\"citation\">Tosef. ib. VII, 13</span> <span dir=\"rtl\">מ׳ הולכי שיירא</span> the usage among members of a caravan; <span class=\"citation\">ib. 14</span> <span dir=\"rtl\">מ׳ הספנין</span> the usage of shippers (in cases of jetsam). <span class=\"citation\">Y. Pes. IV, 30ᵈ</span> top <span dir=\"rtl\">אינו מ׳</span> this is no religious usage (deserving recognition); <a href=\"#\" data-headword=\"מ׳\">מ׳</a> it is &amp;c. <span class=\"citation\">Ḥull. 13ᵇ</span> <span dir=\"rtl\">נכרים … אלא מ׳ אבותיהן בידיהן</span> the gentiles outside of Palestine are not to be considered as idolaters, they only continue the usages of their ancestors. <span class=\"citation\">Ab. Zar. 54ᵇ</span> <span dir=\"rtl\">עולם כמִנְהָגוֹ נוהג</span> the world (nature) follows its laws. Pesik. Aḥăré, p. 168ᵃ, v. <a href=\"#\" data-headword=\"מַנְגָּנוֹן\">מַנְגָּנוֹן</a>: a. fr.—Pl. <span dir=\"rtl\">מִנְהָגִים</span>. <span class=\"citation\">Lev. R. s. 20</span>, beg. <span dir=\"rtl\">מִנְהָגָיו</span> its arrangements, v. <a href=\"#\" data-headword=\"מַנְגָּנוֹן\">מַנְגָּנוֹן</a>.</div>","alt":[]},"13704":{"h":"מִנְהָגָא","r":"M01728","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ruth IV, 7</span>; a. e.—<span class=\"citation\">Snh. 46ᵇ</span> <span dir=\"rtl\">מ׳ בעלמא</span> a mere usage (is incidentally recorded in the Bible, not meant as a law). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דלא לשתני ממ׳</span> in order not to depart from the common custom; <span dir=\"rtl\">דלישתנו ממ׳</span> intimating that they will be treated differently from the common usage (as a disgrace). <span class=\"citation\">Nidd. 66ᵃ</span> אמינא לך איסורא ואת אמרת מ׳ I speak of a legal prohibition, and you quote a usage; <span class=\"citation\">Yeb. 13ᵇ</span>; a. e.—[<span class=\"citation\">Y. Ber. V, 9ᵃ</span> <span dir=\"rtl\">מנהגו מנהגיה</span>, v. <a href=\"#\" data-headword=\"הֲגִי\">הֲגִי</a></div>","alt":[]},"13705":{"h":"מַנְהוּמִי","r":"M01729","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְהַם\">נְהַם</a>) <i>roaring</i>. <span class=\"citation\">Yalk. Ps. 864</span>, v. <a href=\"#\" data-headword=\"מַגְעוּרִי\">מַגְעוּרִי</a>.</div>","alt":[]},"13706":{"h":"מַנְהִיג","r":"M01730","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָהַג\">נָהַג</a>) <i>leader, director</i>. <span class=\"citation\">Gen. R. s. 39</span>, beg.; a. e. <span dir=\"rtl\">תאמר שהעולם הזה בלא מ׳</span> is it possible that this world has no leader?—<span class=\"citation\">B. Bath. 91ᵃ</span> sq. <span dir=\"rtl\">אוי … שאבד מַנְהִיגוֹ וכ׳</span> woe to the world (humanity) whose leader is gone, woe to the ship whose captain is gone!; a. e.—Pl. <span dir=\"rtl\">מַנְהִיגִים</span>. <span class=\"citation\">Gen. R. s. 24</span> <span dir=\"rtl\">דור ודור ומַנְהִיגָיו</span> generation after generation and their several leaders. Ib. s. 12 <span dir=\"rtl\">ברא הן ומַנְהִיגֵיהֶן</span> created them (the heavens) and their directing agencies, v. <a href=\"#\" data-headword=\"נַוְוטָא\">נַוְוטָא</a>.—V. <a href=\"#\" data-headword=\"נָהַג\">נָהַג</a>.</div>","alt":[]},"13707":{"h":"מְנָהַנֵּי","r":"M01731","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"מְנָהַנֵּי\">מְנָא הַנֵּי</a>, v. <a href=\"#\" data-headword=\"מְנָא II\"><span dir=\"rtl\">מְנָא</span> II</a></div>","alt":[]},"13708":{"h":"מְנַהֲרָא","r":"M01732","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נְהַר I) [<i>light-giver</i>,] <i>morning star</i>. <span class=\"citation\">Y. Yoma III, beg. 40ᵇ</span>; Y. R. Hash. II, beg. 57ᵈ, v. <a href=\"#\" data-headword=\"בְּרַק I\"><span dir=\"rtl\">בְּרַק</span> I</a>.</div>","alt":[]},"13709":{"h":"מְנַהֲרוּתָא","r":"M01733","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְנַהֲרָא\">preced.</a>) <i>fine appearance, display of dignity</i>. <span class=\"citation\">Ned. 38ᵇ</span> עבדיו … למ׳ עבידן Ar. (v. Asheri a. l.; ed. <span dir=\"rtl\">למנחרותא</span>; Var. in R. Nissim <span dir=\"rtl\">למנקרותא</span>) slaves are mainly used for display (and need no fattening food).</div>","alt":[]},"13710":{"h":"מַנּוּ","r":"M01734","html":"<div class=\"sense\"> (= <span dir=\"rtl\">מַן הוּ</span>) <i>who is he?, who is it?</i> <span class=\"citation\">Snh. 14ᵃ</span> <span dir=\"rtl\">וחד דעימיה ומ׳ ר׳ יונתן וכ׳</span> and one with him, and who is the one? R. J. &amp;c.; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"מַנִּי\">מַנִּי</a> (= <span dir=\"rtl\">מַן הִי</span>). <span class=\"citation\">Sabb. 140ᵇ</span> <span dir=\"rtl\">לא תימרין מנו אלא מ׳</span> do not call, Who is he? (at the door) but ‘Who is she?’—Esp. <span dir=\"rtl\">(<span dir=\"rtl\">הא</span>) <a href=\"#\" data-headword=\"מני\">מני</a></span> (ellipt. for <span dir=\"rtl\">הָא דְמַן הִי</span>) <i>whose opinion is this?</i> <span class=\"citation\">Ḥull. 15ᵇ</span> <span dir=\"rtl\">מ׳ לא ר׳ וכ׳</span> whose opinion is it (you represent)? This is neither Rabbi’s nor &amp;c. <span class=\"citation\">Succ. 3ᵃ</span> דאמר לך מ׳ ב&quot;ש וכ׳ Ms. M. (v. Rabb. D. S. a. l. note) he who said this to thee,—do you know whose opinion he represents? Beth Shammai’s &amp;c.; a. fr.—[<span class=\"citation\">B. Bath. 91ᵃ</span> <a href=\"#\" data-headword=\"מַנּוּ\">מנו</a>, v. next w.]</div>","alt":[]},"13711":{"h":"מָנוֹבַיְיתָא","r":"M01735","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (comp. of <a href=\"#\" data-headword=\"מָנוֹן\">מָנוֹן</a> a. <a href=\"#\" data-headword=\"בֵּיתָא I\">בֵּיתָא</a>) <i>manager of the house, executor</i>. <span class=\"citation\">B. Bath. 91ᵃ</span> (prov.) <span dir=\"rtl\">עד דלא … קיימא מָנוֹבַיְיתֵיה</span> Ms. M. (ed. <span dir=\"rtl\">קימא מנו ב׳</span>, v. Rabb. D. S. a. l. note) before the dying man is dead, his executor stands (ready to assume the administration).</div>","alt":["מָנוֹבֵיתָא"]},"13712":{"h":"מָנוֹד","r":"M01736","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>shaking</i>; <span dir=\"rtl\">מְנוֹד רֹאשׁ</span> <i>shaking of the head, ready assent, submission</i>. <span class=\"citation\">Sabb. 104ᵃ</span> (ref. to the shapes of certain letters, v. <a href=\"#\" data-headword=\"כָּפַף\">כָּפַף</a>) <span dir=\"rtl\">שניתנה התורה במ׳ ר׳</span> (Ar. only <span dir=\"rtl\">במָ׳</span>) the Law has been given under repeated signs of assent.</div>","alt":[]},"13713":{"h":"מנוולין","r":"M01737","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*מַטּוּל II\"><span dir=\"rtl\">מַטּוּל</span> II</a> a. <a href=\"#\" data-headword=\"מַנְטוּלִין\"><a href=\"#\" data-headword=\"מַנְטוּלִין\">מַנְטוּלִין</a>.</a></div>","alt":[]},"13714":{"h":"מְנַוַּולְתָּא","r":"M01738","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (נְוַול I) <i>nasty, muddy</i>. <span class=\"citation\">Taan. 6ᵇ</span>, v. <a href=\"#\" data-headword=\"טֵבֵת\">טֵבֵת</a>.</div>","alt":[]},"13715":{"h":"מַנְוָותָא","r":"M01739","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְנַת\">מָנְתָא</a></div>","alt":[]},"13716":{"h":"מָנוֹחַ I","r":"M01740","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Manoah</i>, </div><div class=\"sense\"><b>1)</b>  the father of Samson. <span class=\"citation\">Ber. 61ᵃ</span>. <span class=\"citation\">Num. R. s. 10</span>. <span class=\"citation\">B. Bath. 91ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>M.</i>, father of R. Huna. <span class=\"citation\">Taan. 9ᵃ</span></div>","alt":[]},"13717":{"h":"מָנוֹחַ II","r":"M01741","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>rest</i>. <span class=\"citation\">Sabb. 152ᵇ</span> <span dir=\"rtl\">יש להן מ׳</span> (Ms. M. <a href=\"#\" data-headword=\"מְנוּחָה\">מנוחה</a>) find rest. <span class=\"citation\">Lam. R. to I, 3</span> <span dir=\"rtl\">אילו מצאה מ׳ וכ׳</span> if she (Judah) had found rest (among the nations), she would not have returned (to the Lord); a. e.</div>","alt":[]},"13718":{"h":"מְנוּחָה","r":"M01742","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.); <a href=\"#\" data-headword=\"מָנוֹחַ II\">same</a>. <span class=\"citation\">Num. R. s. 10</span> <span dir=\"rtl\">הנבואה נקראת מ׳</span> inspiration is called resting (ref. to <span class=\"citation\">Jer. LI, 59</span>, a. <span class=\"citation\">Is. XI, 2</span>). <span class=\"citation\">Ber. 64ᵃ</span> <span dir=\"rtl\">ת&quot;ח אין להם מ׳</span> scholars are never at rest (constantly progressing). <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">ראה שאין להם מ׳</span> he saw that they had no recreation from labor; a. fr.—Esp. <i>the seat of the central sanctuary</i> (with ref. to <span class=\"citation\">Deut. XII, 9</span>). <span class=\"citation\">Tosef. Zeb. XIII, 20</span>; <span class=\"citation\">Zeb. 119ᵃ</span>, sq.</div>","alt":[]},"13719":{"h":"מִנּוּי","r":"M01743","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"מִנְיָמִין\">מִינּ׳</a>.</div>","alt":["מִנּוּיָא"]},"13720":{"h":"מֹנוֹמָכוֹס","r":"M01744","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹנוֹמָכוֹס\">מוֹנוֹמָכוֹס</a></div>","alt":[]},"13721":{"h":"מְנוּמָּר","r":"M01745","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָמַר\">נָמַר</a></div>","alt":[]},"13722":{"h":"מָנוֹן","r":"M01746","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>manager, executor</i>. <span class=\"citation\">Gen. R. s. 22</span> (ref. to <span class=\"citation\">Prov. XXIX, 21</span>) <span dir=\"rtl\">כל מי שמפנק … סופו להיות מ׳ עליו וכ׳</span> if one indulges his passion in his youth, it will be his ruler in his old days; (<span class=\"citation\">Yalk. Prov. 962</span> <span dir=\"rtl\">מותח</span>, some ed. <span dir=\"rtl\">מושל</span>; <span class=\"citation\">ib. 961</span> <span dir=\"rtl\">מותק</span>). <span class=\"citation\">Succ. 52ᵇ</span>, v. <a href=\"#\" data-headword=\"א\">אטב&quot;ח</a>.—[<span class=\"citation\">Cant. R. to II, 1</span> <span dir=\"rtl\">מנון עבורי</span>, a corrupt gloss, perhaps for <span dir=\"rtl\">עיין שמ&quot;ר</span>, a reference to <span class=\"citation\">Ex. R. s. 23</span>.]</div>","alt":[]},"13723":{"h":"מַנּוֹנָא","r":"M01747","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַנָּא\">מַנָּא</a>; <a href=\"#\" data-headword=\"מְנֵי\">מְנֵי</a>) <i>the ordinary daily food</i>. <span class=\"citation\">Targ. Y. II, Deut. VIII, 3</span> (h. text <a href=\"#\" data-headword=\"לָחַם I\">לחם</a>).</div>","alt":[]},"13724":{"h":"מָנוּנֵי","r":"M01748","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹנִינֵי\">מוֹנִינֵי</a></div>","alt":[]},"13725":{"h":"מָנוֹס","r":"M01749","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>refuge</i>. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">נתן מ׳ למשה וכ׳</span> suffered Moses to take refuge with an idolater. <span class=\"citation\">Yalk. Job 906</span>; <span class=\"citation\">Yalk. Jud. 41</span>, v. <a href=\"#\" data-headword=\"לוּן\">לוּן</a>; a. e.</div>","alt":[]},"13726":{"h":"מְנוּסָה","r":"M01750","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"מָנוֹס\">same</a>. <span class=\"citation\">Midr. Till. to Ps. LXVIII</span> <span dir=\"rtl\">אין להם מ׳ להיכן נסים</span> have no resort to which to flee.</div>","alt":[]},"13727":{"h":"מְנוֹרָה","r":"M01751","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>candlestick, lamp</i>. Pesik. Ekhah, p. 123ᵃ, a. e., v. <a href=\"#\" data-headword=\"כפי\">כָּפָה</a>. <span class=\"citation\">Gen. R. s. 20</span> <span dir=\"rtl\">מ׳ של זהב ונר וכ׳</span> a golden candlestick with an earthen lamp on top (typical of a noble woman married to an ignoble husband); a. fr.—Esp. <i>the candlestick in the Sanctuary</i>. <span class=\"citation\">Num. R. s. 15</span>. <span class=\"citation\">Men. 29ᵃ</span>. <span class=\"citation\">Tam. III, 9</span>; <span class=\"citation\">Yoma 21ᵃ</span>, v. <a href=\"#\" data-headword=\"דִּישּׁוּן\">דִּישּׁוּן</a>; a. fr.—Pl. <a href=\"#\" data-headword=\"מְכוֹרוֹת\">מְנוֹרוֹת</a>. Men. l. c.</div>","alt":[]},"13728":{"h":"מנורי","r":"M01752","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַנְדּוּ\">מַנְדּוּ</a></div>","alt":["כפר מ׳"]},"13729":{"h":"מַנְוָתָא","r":"M01753","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְנַת\">מָנְתָא</a></div>","alt":[]},"13730":{"h":"מנזדנא","r":"M01754","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"מַנְזִירְנָא\">מַנְזִרְנָא</a>.</div>","alt":[]},"13731":{"h":"מַנְזִחְנָא","r":"M01755","html":"<div class=\"sense\"> (a feigned denom. of <a href=\"#\" data-headword=\"נָזִיחַ\">נזיח</a>, with suffix of first person) <i>I will be a Naziḥ</i> (substitute of Nazir), v. <a href=\"#\" data-headword=\"מַנְזִיקְנָא\">next w.</a></div>","alt":["מַנְזִיחְ׳"]},"13732":{"h":"מַנְזִיקְנָא","r":"M01756","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַנְזִחְנָא\">preced.</a>) <i>I will be a Nazik</i> (substitute for Nazir). <span class=\"citation\">Y. Naz. I, beg. 51ᵃ</span> [read:] <span dir=\"rtl\">היידן אינון כינויי כינויין … מ׳ מנזיחנא מפזיחנא</span> what are the substitutes of substitutes?… I will be a Nazik, a Naziḥ &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אין אלו כינויי כינויין כינויין ממש אינון אילן האומר מנזירנא שמא אינו נזיר כך האומר מנזיחנא מפזיחנא כאומר מנזירנא</span> these are not substitutes of substitutes; these are direct substitutes. If one said <i>manzirna</i> (I will be a Nazir), is he not a Nazir? So he who says &amp;c. (turning the substitute nouns into verbs) must be considered as if he had said <i>manzirna</i>. <span class=\"citation\">Ned. 10ᵇ</span> [read:] <span dir=\"rtl\">מנזקנא מנזחנא מפזחנא</span>.</div>","alt":["מַנְזִקְ׳"]},"13733":{"h":"מַנְזִירְנָא","r":"M01757","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַנְזִיקְנָא\">preced.</a>) <i>I will be a Nazir</i>. Y. Naz. I, beg. 51ᵃ (not <span dir=\"rtl\">מנזד׳</span>), v. <a href=\"#\" data-headword=\"מַנְזִיקְנָא\">preced.</a></div>","alt":["מַנְזִרְנָא"]},"13734":{"h":"מְנָח","r":"M01758","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>rest, relief</i>. <span class=\"citation\">Targ. O. Gen. VIII, 9</span>. <span class=\"citation\">Targ. Deut. XXVIII, 65</span> (Y. some ed. <a href=\"#\" data-headword=\"מְנָח\">מַנַּח</a>). <span class=\"citation\">Targ. Ps. CXVI, 7</span> <span dir=\"rtl\">מְנֻחָיְכִי</span> (Ms. <span dir=\"rtl\">ניח׳</span>, Regia <span dir=\"rtl\">נוח׳</span>).</div><div class=\"sense\"><b>—2)</b> <i>going to rest, decline</i> (v. <a href=\"#\" data-headword=\"מִנְחָה\">next w.</a>). <span class=\"citation\">Targ. Gen. III, 8</span> <span dir=\"rtl\">מְנַח יומא</span> (h. text <a href=\"#\" data-headword=\"רִיחַ\">רוּחַ</a>).</div>","alt":[]},"13735":{"h":"מִנְחָה","r":"M01759","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  [<i>laid down</i>,] <i>offering, present</i>.—Pl. <span dir=\"rtl\">מְנָחוֹת</span>. <span class=\"citation\">Num. R. s. 13</span> <span dir=\"rtl\">שלשלמה הביאו האומות מ׳ וכ׳</span> as the nations brought gifts to Solomon &amp;c.; a. e.—Esp. (in ritual) <i>meal-offering</i>. <span class=\"citation\">Men. I, 1</span> <span dir=\"rtl\">מִנְחַת חוטא</span> the sinner’s meal-offering (<span class=\"citation\">Lev. V, 11</span>). Ib. X, 6 (68ᵇ) <span dir=\"rtl\">מנחת בהמה</span> the meal-offering connected with animal offering (e. g. <span class=\"citation\">Lev. VII, 13</span>). Ib. XII, 3 הרי עלי מ׳ וכ׳ I vow a <i>minḥah</i> of barley; a. v. fr.—<i>Pl.</i> as ab. Ib. I, 1; a. fr.—<i>M’naḥoth</i>, name of a treatise of the Mishnah, Tosefta, and Talmud Babli of the Order of Kodashim.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"מְנָח\">preced.</a> 2) [<i>decline</i>,] <i>afternoon</i> (corresp. to b. h. <span dir=\"rtl\">בֵּין הָעַרְבַּיִם</span>); <span dir=\"rtl\">תְּפִלַּת המ׳</span> (or <a href=\"#\" data-headword=\"מִנְחָה\">מִנְחָה</a>) <i>afternoon-prayer</i>, <i>Minḥah</i>. <span class=\"citation\">Ber. IV, 1</span> (<span class=\"citation\">26ᵃ</span>) <span dir=\"rtl\">תפלת המ׳ עד הערב</span> the <i>Minḥah</i> may be read until sunset; ib. 26ᵇ <span dir=\"rtl\">תפלת המ׳ … שהרי תמיד של בין הערבים וכ׳</span> the Minḥah may be read &amp;c., because the daily sacrifice of the afternoon could be offered until sunset. Ib. <span dir=\"rtl\">עד פלג המ׳</span> up to the middle of the afternoon. Ib. <span dir=\"rtl\">מ׳ גדולה</span> (<span dir=\"rtl\">מ׳ קמא</span>) the large (first) afternoon, i.e. the time from six and a half hours after sunrise to sunset (the day being divided into twelve hours); <span dir=\"rtl\">(<span dir=\"rtl\">מ׳ אחרונה</span>) <span dir=\"rtl\">מ׳ קטנה</span></span> the smaller (later) afternoon, i.e. from nine and a half hours to sunset. Ib. <span dir=\"rtl\">פלג מ׳ אחרונה</span> the middle of the late (small) afternoon. Ib. top <span dir=\"rtl\">טעה ולא התפלל מ׳</span> if by mistake he failed to read the Minḥah; a. fr.</div>","alt":[]},"13736":{"h":"מְנַחֵם","r":"M01760","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Menahem</i>, </div><div class=\"sense\"><b>1)</b>  King of Israel. <span class=\"citation\">Yalk. Kings 236</span> (from Seder ʿOlam).—2) name of the Messiah to come. <span class=\"citation\">Snh. 98ᵇ</span>. <span class=\"citation\">Y. Ber. III, 5ᵃ</span> top; <span class=\"citation\">Lam. R. to I, 16</span>; <span class=\"citation\">Pirké d’R. El. ch. XIX</span> <span dir=\"rtl\">מ׳ בן עמיאל בן יוסף</span>.—3) M., associate judge of Hillel. <span class=\"citation\">Ḥag. II, 2</span>. <span class=\"citation\">Ib. 16ᵇ</span> יצא מ׳ לעבודת המלך M. resigned from the judgeship to enter the King’s (Herod’s) service.—4) M. bar Simai, surnamed ‘the son of saints’. <span class=\"citation\">Pes. 104ᵃ</span>; <span class=\"citation\">Ab. Zar. 50ᵃ</span>; (Y. ib. III, 42ᶜ top <span dir=\"rtl\">נחום איש קודש קדשים</span>).—5) name of several scholars. <span class=\"citation\">Y. Maasr. V, end, 52ᵃ</span> M. bar Mabsima.—<span class=\"citation\">Y. Erub. VII, 24ᶜ</span> top.—Tosef. ib. XI (VIII), 10 <span dir=\"rtl\">מ׳ איש גליא</span> (<span class=\"citation\">Keth. 60ᵃ</span> <span dir=\"rtl\">נחום</span>). <span class=\"citation\">Tosef. Shebu. I, 7</span> <span dir=\"rtl\">מ׳ איש גם זו</span>, v. <a href=\"#\" data-headword=\"גִּמְזוֹ\">גִּמְזוֹ</a>.—<span class=\"citation\">Tosef. Keth. V, 1</span>; a. fr.</div>","alt":[]},"13737":{"h":"מנחרותא","r":"M01761","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְנַהֲרוּתָא\">מְנַהֲרוּתָא</a></div>","alt":[]},"13738":{"h":"מְנַחֵשׁ","r":"M01762","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>diviner</i>, v. <a href=\"#\" data-headword=\"נָחַשׁ\">נָחַשׁ</a>.</div>","alt":[]},"13739":{"h":"מְנַחֵשׁ ²","r":"M01763","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Deut. XVIII, 10</span>.—Pl. <span dir=\"rtl\">מְנַחְשִׁין</span>, <span dir=\"rtl\">מְנַחְשַׁיָּא</span>. <span class=\"citation\">Targ. Y. Lev. XXVI, 30</span>; a. e.</div>","alt":["מְנַחְשָׁא"]},"13740":{"h":"מִנְחָתָא","r":"M01764","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>offering; meal offering</i>. <span class=\"citation\">Targ. Lev. II, 1</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"מִנְחָתָא\">מִנְחָוָתָא</a>. <span class=\"citation\">Targ. O. Num. XVIII, 9</span> ed. Berl. (ed. <span dir=\"rtl\">מִנְחַתְ׳</span>).</div><div class=\"sense\"><b>—2)</b> <i>afternoon, afternoon prayer, Minḥah</i>. <span class=\"citation\">Targ. I Kings XVIII, 29</span>.—Y. Pes. V, 30ᵈ top.—<span class=\"citation\">Sot. 39ᵇ</span> <span dir=\"rtl\">במ׳ דתענית</span> in the Minḥah of the fast-day.—Pl. <a href=\"#\" data-headword=\"מִנְחָתָא\">מִנְחָתָא</a>. <span class=\"citation\">R. Hash. 31ᵃ</span> <span dir=\"rtl\">במ׳ דשבתא</span> in the Minḥah of Sabbath days; a. e.</div>","alt":["מִנְחֲ׳"]},"13741":{"h":"מַנְטוּלִין","r":"M01765","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (correct <span dir=\"rtl\">מַנְטִי׳</span>, mantela, μαντήλιον, of Semitic origin, v. <a href=\"#\" data-headword=\"*מַטּוּל II\"><span dir=\"rtl\">מַטּוּל</span> II</a>) <i>napkin, handkerchief</i>. Y. Ber. III, 6ᵈ bot. <span dir=\"rtl\">דרקק אמ׳ וכ׳</span> quot. in Asheri to <span class=\"citation\">Ber. 24ᵇ</span> (ed. <span dir=\"rtl\">איצטלין</span>, Rashba <span dir=\"rtl\">אם טיילין</span>, Var. <span dir=\"rtl\">אם עצטלין</span>, corr. acc., and read: <span dir=\"rtl\">מותר</span> for <span dir=\"rtl\">אסור</span>) who spits into his handkerchief.—Pl. same. <span class=\"citation\">Gen. R. s. 5</span>; s. 28 <span dir=\"rtl\">ובמנוולין</span>, <span dir=\"rtl\">ובמנולין</span> (corr. acc.), v. <a href=\"#\" data-headword=\"*מַטּוּל II\"><span dir=\"rtl\">מַטּוּל</span> II</a>.</div>","alt":[]},"13742":{"h":"מִי׳ מִנְטַר","r":"M01766","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְטַר\">נְטַר</a>) </div><div class=\"sense\"><b>1)</b>  (infin. of <a href=\"#\" data-headword=\"נְטַר\">נְטַר</a>) <span dir=\"rtl\">דמסיר למ׳</span> <i>the charge of</i>. <span class=\"citation\">Targ. Y. Num. III, 36</span> (O. <span dir=\"rtl\">דמסיר למיטר ל־</span> ed. Berl., oth. ed. <span dir=\"rtl\">למַטַּר</span>).</div><div class=\"sense\"><b>—2)</b>  [<i>guard</i>,] <i>border, edge</i> of a cloak (corresp. to Lat. clavus). <span class=\"citation\">Targ. Y. Ex. XXVIII, 31</span>; <span class=\"citation\">34</span>.—Trnsf. (like clavus) <i>tunic</i>. <span class=\"citation\">Targ. I Chr. XV, 27</span>.</div>","alt":[]},"13743":{"h":"מנטרומין","r":"M01767","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָגִיסְטֵיר\">מָגִיסְטֵיר</a></div>","alt":[]},"13744":{"h":"מִנִּי","r":"M01768","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Land of Minni</i> (supposed to be <i>Minyas</i> in Armenia). <span class=\"citation\">Targ. Ps. XLV, 9</span>; (<span class=\"citation\">Targ. Jer. LI, 27</span> <a href=\"#\" data-headword=\"הוּרְמִינִי\">הוּרְמִינִי</a>).</div>","alt":["אֲרַע מ׳"]},"13745":{"h":"מָנַי","r":"M01769","html":"<div class=\"sense\"> pr. n. m., v. <a href=\"#\" data-headword=\"מָאן\">מָנָא</a></div>","alt":[]},"13746":{"h":"מַנִּי","r":"M01770","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַנּוּ\">מַנּוּ</a></div>","alt":[]},"13747":{"h":"מָנֵי","r":"M01771","html":"<div class=\"sense\"><i>a weight</i>, v. <a href=\"#\" data-headword=\"מָנֶה\">מָנֶה</a>.</div>","alt":[]},"13748":{"h":"מני","r":"M01772","html":"<div class=\"sense\"> (b. h.) <i>to divide, distribute</i>; <i>to count</i>. <span class=\"citation\">Bekh. IX, 7</span> <span dir=\"rtl\">ומוֹנֶה בשבט אחד וכ׳</span> (Bab. ed. 58ᵇ <span dir=\"rtl\">ומונין א׳</span>) and he counts with the rod, one, two &amp;c. Ib. <span dir=\"rtl\">מְנָאָם רביצין</span> if he counted them while they were crouching. <span class=\"citation\">Shebu. 34ᵃ</span> bot. <span dir=\"rtl\">מָנֶה מָנִיתִי לך וכ׳</span> (not <span dir=\"rtl\">מְנִיתִיךָ</span>, v. Rabb. D. S. a. l. note) I counted (delivered) to thee a Maneh (as a loan) in the presence &amp;c.; <span class=\"citation\">ib.ᵇ</span> <span class=\"citation\">R. Hash. 12ᵃ</span> <span dir=\"rtl\">חכמי ישראל מוֹנִין למבול וכ׳</span> the Jewish scholars count the dates of the flood in accordance with R. El. (beginning the year with Tishri), and the astronomical calendar in accordance with R. J. (beginning with Nisan), <span class=\"citation\">Pesik. R. s. 15</span>, beg. <span dir=\"rtl\">אין מונין ללבנה וכ׳</span> we count by the moon (fix the date of the new month) only when seen after sunset. <span class=\"citation\">Succ. 29ᵃ</span>, a. fr. <span dir=\"rtl\">מונין ללבנה</span> regulate the seasons by the moon (have a lunar year). <span class=\"citation\">Men. 65ᵇ</span>, a. e. <span dir=\"rtl\">מְנֵה ימים וכ׳</span> count the required number of days and proclaim (one day as) the New Moon Day. <span class=\"citation\">Yoma V, 3</span>; a. fr.—Part. pass. <span dir=\"rtl\">מָנוּי</span>; f. <span dir=\"rtl\">מְנוּיָה</span>; pl. <span dir=\"rtl\">מְנוּיִים</span>, <span dir=\"rtl\">מְנוּיִין</span>, <span dir=\"rtl\">מְנוּיִן</span>; <span dir=\"rtl\">מְנוּיוֹת</span> a) <i>counted</i>. <span class=\"citation\">Taan. 8ᵇ</span> <span dir=\"rtl\">דבר המ׳</span> that which has been counted (is known by number). <span class=\"citation\">Bekh. IX, 7</span> <span dir=\"rtl\">אחד מן המ׳</span> one of the sheep already counted.—b) <i>classified</i>; (<i>pl.</i>) <i>class</i>. <span class=\"citation\">Ḥag. 17ᵇ</span> <span dir=\"rtl\">מה חדש למְנוּיָיו אף עצרת למְנוּיָיו</span> (<a href=\"#\" data-headword=\"עֲצֶרֶת\">עצרת</a> = <span dir=\"rtl\">שבוע של ע׳</span>) as the New Moon festival belongs to its class (of days), so does the Pentecost (which is determined by counting weeks) belong to its class (of weeks), i.e. the pilgrim’s sacrifice (<a href=\"#\" data-headword=\"חֲגִיגָה\">חגיגה</a>) may be offered during the entire eighth week from Passover; <span class=\"citation\">R. Hash. 5ᵃ</span> <span dir=\"rtl\">למְנוּיָו</span>.—c) (v. <i>Nif.</i>) <i>entered for a share in the sacrifice</i>. <span class=\"citation\">Zeb. V, 8</span> <span dir=\"rtl\">אינו נאכל אלא למנויו</span> can be partaken of only by those registered for it. <span class=\"citation\">Pes. V, 3</span> (<span class=\"citation\">61ᵃ</span>) <span dir=\"rtl\">שחטו שלא לאוכליו ושלא למנוייו</span> (Bab. ed. <span dir=\"rtl\">למנויו</span>) if while slaughtering he had in mind such as were unable to partake of it (sick persons &amp;c.) or such as had not been registered for it. Ib. 61ᵃ bot. <span dir=\"rtl\">איתקש אוכלין למנויין</span> (Ms. M. <span dir=\"rtl\">אוכליו למנוייו</span>) the partakers (to be held in mind) are analogous to the registered. Ib. 70ᵃ אינה … למְנוּיֶהָ Ms. M. (ed. incorr. <span dir=\"rtl\">למנוייו</span>, <span dir=\"rtl\">למנויו</span>) it (the pilgrim’s sacrifice) can only be partaken of by those registered for it; a. fr.</div><div class=\"sense\"><b>Nif. נִמְנֶה  נִי׳</b> <div class=\"sense\"><b>1)</b> <i>to be counted</i>. <span class=\"citation\">Num. R. s. 1</span> <span dir=\"rtl\">אינן נִמְנִים ולא נמדדין</span> are neither numbered nor measured. <span class=\"citation\">Bets. 3ᵇ</span>, a. e. <span dir=\"rtl\">את שדרכו לִימָּנוֹת</span>, v. <a href=\"#\" data-headword=\"אֵת\">אֵת</a>. <span class=\"citation\">Gitt. V, 6</span> <span dir=\"rtl\">נִמְנוּ</span> (usu. <span dir=\"rtl\">נמנו וגמרו</span>) they (their votes) were counted, they resolved, v. <a href=\"#\" data-headword=\"גָּמַר II\"><span dir=\"rtl\">גָּמַר</span> II</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be counted on for a share in the Passover lamb, to be registered</i> (<span class=\"citation\">Ex. XII, 4</span>). <span class=\"citation\">Pes. VIII, 3</span> <span dir=\"rtl\">לעולם נִימְנִין עליו וכ׳</span> persons may continually be entered for a share in it, as long as there remains for each &amp;c. Ib. <span dir=\"rtl\">נימנין ומושכין וכ׳</span> they may be entered and withdraw again. Ib. 89ᵃ <span dir=\"rtl\">אבל לִימָּנוֹת</span> but as for registering (additional names). Tosef. ib. VII, 7 <span dir=\"rtl\">רצו להמשך ולהִמָּנוֹת וכ׳</span> (ed. Zuck. incorr.) if some of them wish to withdraw and have others entered on their share &amp;c.; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to be specified</i>. Y. Taan. IV, 68ᵇ (ref. to Mish. <span class=\"citation\">ib. IV, 5</span>) <span dir=\"rtl\">מה ראה … להִימָּנוֹת</span> what reason was there for that specification of the time when each family of priests and the people had to offer wood?; Y. Shek. IV, beg. 47ᵈ; Y. Meg. I, 70ᶜ top.</div></div><div class=\"sense\"><b>Hif. הִמְנָה  הִי׳</b> <div class=\"sense\"><i>to cause to be entered; to add to the number of sharers; to transmit one’s share to another person</i>. Y. Pes. VIII, 36ᵃ top <span dir=\"rtl\">הי׳ אותו על חנם</span> he gave him a share gratuitously. Tosef. ib. l. c. <span dir=\"rtl\">בני חבורה שרצו להַמְנוֹת וכ׳</span> (ed. Zuck. <span dir=\"rtl\">לַמְנוֹת</span>) members of a party who desire to give others a share in their own portion. Ib. <span dir=\"rtl\">המַמְנֶה אחרים על חלקו</span> (ed. Zuck. <span dir=\"rtl\">פסחו</span>) he who assigns to others a share in his portion; a. fr.</div></div><div class=\"sense\"><b>Hof. הוּמְנֶה</b> <div class=\"sense\"><i>to be added to the number; to be entered as a member of a group or of a family</i>. Tosef. ib. VIII, 3 <span dir=\"rtl\">ה׳ על אחד מהם</span> if he (the orphan) has been entered as his guest by one of the guardians. Ib. 6 <span dir=\"rtl\">בני חבורה שהוּמְנוּ וכ׳</span> ed. Zuck. (oth. ed. <span dir=\"rtl\">שנמנו</span>) members of a group who have been entered (in a body) in addition to the original participants; a. e.</div></div><div class=\"sense\"><b>Pi. מִנָּה  מִי׳</b> <div class=\"sense\"><i>to appoint, elect.</i> <span class=\"citation\">Gitt. V, 4</span> <span dir=\"rtl\">שמי׳ להן אביהן וכ׳</span> for whom their father had appointed an executor. Ib. <span dir=\"rtl\">שמִינָּהוּ אבי וכ׳</span> whom the father … has appointed. <span class=\"citation\">Taan. 10ᵇ</span> <span dir=\"rtl\">כל שראוי למַנּוֹתוֹ וכ׳</span> who is worthy to be elected manager &amp;c.; a. fr.—Part. pass. <a href=\"#\" data-headword=\"מְמוּנֶּה\">מְמוּנֶּה</a>; pl. <span dir=\"rtl\">מְמוּנִּים</span>. <span class=\"citation\">Sot. 42ᵃ</span> <span dir=\"rtl\">למה סגן ממ׳</span> for what purpose is a deputy high priest appointed?; <span class=\"citation\">Yoma 39ᵃ</span> <span dir=\"rtl\">מימינו</span> ed. (corr. acc.; v. Rabb. D. S. a. l. note); a. fr.—<span class=\"citation\">Hor. 13ᵇ</span> שאביהם ממונים פרנס וכ׳ Ms. M. (ed. <span dir=\"rtl\">שממ׳ אביהם</span>, = <span dir=\"rtl\">מן הממונים</span>) whose father is of those worthy to be elected manager (v. Taan. l. c.).—V. <a href=\"#\" data-headword=\"מְמוּנֶּה\">מְמוּנֶּה</a>.—Esp. <i>to ordain as teacher and judge</i>. Y. Snh. I, 19ᵃ bot. <span dir=\"rtl\">ב&quot;ד שמי׳ שלא וכ׳</span> a court that ordained without the consent of the Nasi. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">היה כל אחד מְמַנֶּה וכ׳</span> each teacher used to ordain his own pupils; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְמַנֶּה</b> </div><div class=\"sense\"><b>Nithpa. נִתְמַנֶּה</b> <div class=\"sense\"><b>1)</b> <i>to be appointed, designated as deputy, to be ordained</i>. Sifra Aḥăré Par. 5, ch. VIII <span dir=\"rtl\">לרבות כהן אחר המִתְמַנֶּה</span> to imply the other priest that is designated as a deputy. Y. Bicc. III, 65ᵈ top <span dir=\"rtl\">חכם שנ׳ וכ׳</span> when a scholar is ordained, his sins are forgiven. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">זה שהוא מתמ׳ בכסף וכ׳</span> (not <span dir=\"rtl\">מתמני</span>) before him who has been ordained for money, we must not stand up, nor do we call him rabbi, and the cloak upon him is like the cover of ass. <span class=\"citation\">Yoma 22ᵇ</span>. Y. Shek. V, 48ᵈ bot. <span dir=\"rtl\">מאי אם זה שנ׳ על … אתם שאתם מִתְמַנִּין וכ׳</span> if this one appointed superintendent of wicks, was privileged to be counted among the great of the generation, how much more you who are to be appointed over the preservation of lives (as directors of charities). <span class=\"citation\">R. Hash. II, 9</span> (<span class=\"citation\">25ᵃ</span>) <span dir=\"rtl\">שנִתְמַנּוּ ב&quot;ד על וכ׳</span> Ms. O. (ed. <span dir=\"rtl\">שעמדו</span>, v. Rabb. D. S. a. l. note 90) who have been ordained as a court for all Israel; a. fr.</div><div class=\"sense\"><b>—2)</b>  (of things) <i>to be assigned</i>. <span class=\"citation\">Tosef. Sot. VII, 20</span> <span dir=\"rtl\">נִתְמַנָּה לאדם פרנסה וכ׳</span> if a livelihood has been assigned to a man (by Providence, i.e. if he has succeeded in establishing a livelihood), he must buy a house; <span dir=\"rtl\">חזר נ׳ לו יקח וכ׳</span> (v. ed. Zuckerm. note) if more has been provided for him, he must buy a field … and then marry a wife.</div></div>","alt":["מָנָה"]},"13749":{"h":"מְנֵי","r":"M01773","html":"<div class=\"sense\"><b>1)</b> <i>to count</i>. <span class=\"citation\">Targ. Ps. LXXVIII, 9</span> <a href=\"#\" data-headword=\"מַנּוּ\">מנו</a> (<a href=\"#\" data-headword=\"ל\">ל</a>)<span dir=\"rtl\">קיצא</span> (ed. Lag. <span dir=\"rtl\">מיני</span>, corr. acc.) they calculated the term (of redemption). <span class=\"citation\">Targ. Num. I, 44</span>; <span class=\"citation\">49</span>; a. fr.—<span class=\"citation\">Men. 66ᵃ</span> <span dir=\"rtl\">למִימְנֵי יומי וכ׳</span> to count the days … and the weeks (of the ʿOmer. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">רבנן … מְנוֹ יוֹמֵי וכ׳</span> Ms. M. (ed. <a href=\"#\" data-headword=\"מני\">מני</a>) the scholars of … counted the days but not the weeks. <span class=\"citation\">Ḥull. 60ᵇ</span> <span dir=\"rtl\">לִימְנוּ בך וכ׳</span> the Israelites shall count days and years after thee (the moon); a. fr.—[<span class=\"citation\">Yalk. Is. 337</span> <span dir=\"rtl\">דמניין</span>, v. <a href=\"#\" data-headword=\"מוּג\">מוּג</a>.]</div><div class=\"sense\"><b>—2)</b> <i>to appoint</i>, v. infra.</div><div class=\"sense\"><b>Pa. מַנֵּי</b> <div class=\"sense\"><b>1)</b> <i>to appoint, ordain</i>. <span class=\"citation\">Targ. O. Gen. XLI, 33</span>, sq. (Y. <i>Pe</i>.); a. fr.—Y. Bicc. III, 65ᶜ bot. <span dir=\"rtl\">הוון בעיין מְמַנִּיתֵיה</span> they wanted to ordain him; ib.ᵈ top <span dir=\"rtl\">מְמַנְּיֵיה</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ומַנּוּנֵיה</span> and they ordained him. <span class=\"citation\">Sot. 40ᵃ</span> <span dir=\"rtl\">אִימְּנוּ רבנן עליה לממנייה ברישא</span> the scholars agreed to appoint him first; a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מְתַנָּא\">מְמַנָּא</a>, <span dir=\"rtl\">מְמַנִּי</span>; pl. <span dir=\"rtl\">מְמַנָּן</span> <i>appointed; officer</i> (v. <a href=\"#\" data-headword=\"מְמוּנֶּה\">מְמוּנֶּה</a>). <span class=\"citation\">Targ. Y. Num. II, 5</span>. <span class=\"citation\">Targ. Jer. XXXVII, 13</span>. <span class=\"citation\">Targ. I Chr. IX, 19</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to assign, commit</i>. <span class=\"citation\">Targ. Ps. XXXI, 6</span>. (h. text <a href=\"#\" data-headword=\"פְּקַד\">אפקיד</a>). <span class=\"citation\">Targ. II Chr. XII, 10</span>; a. e.</div></div><div class=\"sense\"><b>Af. אַמְנֵי</b> <div class=\"sense\"><b>1)</b> <i>to register, enter, designate for a share</i>. <span class=\"citation\">Pes. 89ᵃ</span> <span dir=\"rtl\">דאַמְנִינְהוּ מעיקרא</span> that he had originally designated them for participation in the Passover meal; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to take a vote</i>. Ib. 52ᵃ מַמְנוּ Ms. M. (ed. <span dir=\"rtl\">ממינן</span>, read <span dir=\"rtl\">מַמְנִין</span>), v. <a href=\"#\" data-headword=\"נִגְדָּא ²\"><span dir=\"rtl\">נִגְדָּא</span> II</a>.</div></div><div class=\"sense\"><b>Ithpa. אִתְמַנִּי  אִתְמַנָּא</b> </div><div class=\"sense\"><b>Ithpe. אִיתְמְנִי  אִימְּנִי</b> <div class=\"sense\"><b>1)</b> <i>to be numbered, counted; to vote</i>. <span class=\"citation\">Targ. Num. II, 33</span>; a. fr.—<span class=\"citation\">Sot. 40ᵃ</span>, v. supra. <span class=\"citation\">Gitt. 56ᵇ</span> <span dir=\"rtl\">ואִימְּנוּ להו חשיבי וכ׳</span> (not <span dir=\"rtl\">ואמינא … חשיבא</span>) the nobles of Rome have agreed to place thee at the head; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be appointed; to be ordained</i>. <span class=\"citation\">Targ. Ps. CX, 4</span>; <span class=\"citation\">6</span>; a. fr.—Y. Bicc. l. c. <span dir=\"rtl\">חד מן אילין דמיתמני בכסף</span> (read: <span dir=\"rtl\">דמִיתְמַנִּין</span>) one of those ordained for money’s sake. <span class=\"citation\">Ib.</span> (adapting <span class=\"citation\">Hab. II, 19</span>) <span dir=\"rtl\">לא בכספייא אי׳ וכ׳</span> has he not been ordained for money? &amp;c. Ib. <span dir=\"rtl\">לא קבל עלוי מִתְמַנֵּי</span> he would not allow himself to be ordained; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to be designated for a share</i>. <span class=\"citation\">Targ. O. Ex. XII, 4</span>.—<span class=\"citation\">Pes. 89ᵃ</span> ונִימְּנִינְהוּ בהדי כל חד וחד Ms. M. (Ms. O. <span dir=\"rtl\">ונִימְּנֵי כל חד וחד בהדיה</span>; ed. <span dir=\"rtl\">ונימני עילויה הני וכ׳</span>, read <span dir=\"rtl\">עילוי דהני</span>; v. Rabb. D. S. a. l. note) and let them be designated as participants with each of them (and let each of them be designated &amp;c.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בתר דשחיט מי קא מתמני</span> after the lamb is slaughtered how can he be entered? <span class=\"citation\">Ib. 60ᵇ</span> <span dir=\"rtl\">ומִימְּנוּ עילויה אחריני</span> (v. Rabb. D. S. a. l. note 200) and other persons will be entered for a share in it; a. e.</div></div>","alt":["מְנָא"]},"13750":{"h":"מִנְיוֹמִי","r":"M01774","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Minyomi</i>, a physician. <span class=\"citation\">Ab. Zar. 28ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"מִנְיָמִין\">מִנְיָמִין</a>). <span class=\"citation\">Sabb. 133ᵇ</span> (Ms. M. <span dir=\"rtl\">בניימין</span>; <span class=\"citation\">Snh. 99ᵇ</span> bot. <span dir=\"rtl\">בנימין</span>).</div>","alt":["מִי׳"]},"13751":{"h":"מִנְיוֹמִין","r":"M01775","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Minyomin</i>. <span class=\"citation\">Ḥull. 49ᵇ</span>, v. <a href=\"#\" data-headword=\"כַּנְדּוֹקָא\">כַּנְדּוֹקָא</a>.</div>","alt":[]},"13752":{"h":"מָנֵיט","r":"M01776","html":"<div class=\"sense\">, part. <i>Af</i>. of <a href=\"#\" data-headword=\"נוּט\">נוּט</a>.</div>","alt":[]},"13753":{"h":"מִנְיָימִין","r":"M01777","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִנְיָמִין\">מִנְיָמִין</a></div>","alt":[]},"13754":{"h":"מִנַּיִין","r":"M01778","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִן\">מִן</a> h.</div>","alt":[]},"13755":{"h":"מִנְיָין","r":"M01779","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִנְיָן\">מִנְיָן</a>, <a href=\"#\" data-headword=\"מִנְיַן\"><a href=\"#\" data-headword=\"מִנְיַן\">מִנְיָנָא</a>.</a></div>","alt":["מִנְיָינָא"]},"13756":{"h":"מָנְיָיק","r":"M01780","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּנְיָיק\">מוּנְיָיק</a></div>","alt":[]},"13757":{"h":"מניישא","r":"M01781","html":"<div class=\"sense\">, <span class=\"citation\">Y. Meg. II, 73ᵇ</span>, read <a href=\"#\" data-headword=\"מְנַשְׁיָיא\">מְנַשְׁיָא</a>.</div>","alt":[]},"13758":{"h":"מָנִיכָא","r":"M01782","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מני\">מני</a>, v. <a href=\"#\" data-headword=\"הַמְנִיכָא\">הַמְנִיכָא</a>) [<i>badge of office</i>,] <i>necklace</i>. <span class=\"citation\">Targ. Gen. XLI, 42</span>; a. e.—<span class=\"citation\">Tam. 32ᵃ</span>.—Pl. <span dir=\"rtl\">מָנִיכִין</span>. <span class=\"citation\">Targ. Y. II, Gen. XLIX, 22</span>.</div>","alt":["מְ׳"]},"13759":{"h":"*מָנִיכָה","r":"M01783","html":"<div class=\"sense\"> f. h. form, <a href=\"#\" data-headword=\"מָנִיכָא\">same</a>. <span class=\"citation\">Pirké d’R. El. ch. XLIII</span> <span dir=\"rtl\">ואחזו אותו במְנִיכַת ראשו</span> quot. in Men. Hamm. V, ch. V, 1, 2 (ed. <span dir=\"rtl\">במינקת</span>) they seized him by his necklace.</div>","alt":[]},"13760":{"h":"מִנְיָמִין","r":"M01784","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Minyamin</i>, name of several persons; </div><div class=\"sense\"><b>1)</b>  M., an Egyptian proselyte. <span class=\"citation\">Tosef. Kidd. V, 4</span>; (<span class=\"citation\">Sifré Deut. 253</span> <span dir=\"rtl\">בנימין</span>); <span class=\"citation\">Sot. 9ᵃ</span>; <span class=\"citation\">Yeb. 78ᵃ</span></div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">מ׳ בר איהי</span>. <span class=\"citation\">Meg. 28ᵃ</span> (Ms. M. <span dir=\"rtl\">בנ׳ בר איתי</span>; v. Rabb. D. S. a. l. note).</div><div class=\"sense\"><b>—3)</b>  <span class=\"citation\">Nidd. 65ᵃ</span>, v. <a href=\"#\" data-headword=\"*גִּנְזַכָּיָיה\">גִּנְזַכָּיָיה</a></div><div class=\"sense\"><b>—4)</b>  <span class=\"citation\">Ab. Zar. 28ᵇ</span>, v. <a href=\"#\" data-headword=\"מִנְיוֹמִי\">מִנְיוֹמִי</a></div>","alt":["מִנְיָי׳","מִינְ׳"]},"13761":{"h":"מִנַּיִן","r":"M01785","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִן\">מִן</a> h.</div>","alt":[]},"13762":{"h":"מִנְיָן","r":"M01786","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>number, count; ballot, vote</i>. <span class=\"citation\">B. Mets. 6ᵇ</span>; <span class=\"citation\">Bekh. 59ᵇ</span>, a. e. <span dir=\"rtl\">מ׳ הראוי פוטר</span> a count properly begun redeems, i.e. if one began to count ten or more animals for tithing purposes, and during the count one animal died or ran off, those which passed the rod are redeemed. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">איפטרו להו במ׳ הראוי</span> they were redeemed by means of the (interrupted) count properly begun.—<span dir=\"rtl\">רוב המ׳</span>, <span dir=\"rtl\">רוב מִנְיָנוֹ</span>, v. <a href=\"#\" data-headword=\"בִּנְיָן\">בִּנְיָן</a>.—<span class=\"citation\">Bets. 3ᵇ</span> דבר שישנו במ׳ Ms. M. (ed. <span dir=\"rtl\">דבר שבמ׳</span>); <span class=\"citation\">Zeb. 73ᵃ</span> <span dir=\"rtl\">דבר שיש בו מ׳</span> objects sold by the piece.—<span class=\"citation\">Y. Ber. I, 3ᵃ</span> top <span dir=\"rtl\">נעמוד על המ׳</span> let us decide by vote; <span class=\"citation\">Tosef. Ohol. IV, 2</span> <span dir=\"rtl\">נעמוד למ׳</span>. <span class=\"citation\">Eduy. I, 5</span>, a. fr. <span dir=\"rtl\">גדול … בחכמה ובמ׳</span> superior to a previous meeting of scholars in learning and numbers. <span class=\"citation\">Bets. 5ᵃ</span> <span dir=\"rtl\">כל דבר שבמ׳ צריך מ׳ וכ׳</span> a prohibitory measure passed by ballot, requires another ballot to be abrogated (although the reason for the measure has ceased to exist). <span class=\"citation\">Snh. 26ᵃ</span> <span dir=\"rtl\">קשר … אינו מן המ׳</span> a measure passed in a meeting of wicked men does not count (deserves no consideration on the part of successors). <span class=\"citation\">Ḥull. 97ᵇ</span> <span dir=\"rtl\">אין … מן המ׳</span> does not count, is not included.—<span class=\"citation\">Num. R. s. 1</span> <span dir=\"rtl\">במִנְיַן ישראל</span> at the census of the Israelites in the desert; a. fr.—[In later Hebrew: <a href=\"#\" data-headword=\"מ׳\">מ׳</a> <i>the requisite number of males for congregational worship</i>.]</div>","alt":["מִנְיָין","מִי׳"]},"13763":{"h":"מִנְיַן","r":"M01787","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. XXXIV, 30</span>. <span class=\"citation\">Targ. Num. I, 2</span>; a. fr.—<span class=\"citation\">Sabb. 73ᵇ</span> <span dir=\"rtl\">מ׳ למה לי</span> why does the Mishnah state the number (39)?; <span class=\"citation\">Kerith. 2ᵇ</span>; a. fr.—<span class=\"citation\">Bekh. 60ᵃ</span> bot. <span dir=\"rtl\">הואיל ואיתיה במ׳ פרסאה וכ׳</span> because it occurs in the Persian (?) system of counting that they call ten <i>one</i>.—<span class=\"citation\">Snh. 36ᵃ</span>; <span class=\"citation\">Gitt. 59ᵃ</span> אנא הואי במ׳ I was one of the voters in the school of Rabbi, and with me they commenced. <span class=\"citation\">Y. Snh. I, 18ᶜ</span> top [read:] <span dir=\"rtl\">אין אנא סלקית ממ׳ וכ׳</span> whether or not I was counted in (to make up the required number); a. fr.—Pl. <span dir=\"rtl\">מִנְיָנַיָּא</span>, <span dir=\"rtl\">מִנְיָינֵי</span>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a>. <span class=\"citation\">Targ. Num. I, 44</span>; a. fr.—Gitt. l. c.; <span dir=\"rtl\">כולהו מִנְיָנַיְיהוּ וכ׳</span> in all their ballots they began their vote from the side benches (with the juniors).—<span class=\"citation\">Sabb. 66ᵇ</span> <span dir=\"rtl\">כל מ׳ וכ׳</span> all incantations which are repeated several times, must contain the name of the patient’s mother; a. e.</div>","alt":["מִנְיָנָא","מִנְיָי׳","מִי׳"]},"13764":{"h":"מְנִיפָא","r":"M01788","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נוּף\">נוּף</a>) <i>fan</i>. <span class=\"citation\">B. Mets. 86ᵃ</span> <span dir=\"rtl\">הניפי עלי במ׳</span> (Ms. M. a. oth. <span dir=\"rtl\">במְנִיפָיךְ</span>) fan me with the (thy) fan; v. <a href=\"#\" data-headword=\"מְנָפָה\">מְנָפָה</a>.</div>","alt":[]},"13765":{"h":"מֵנִיקָה","r":"M01789","html":"<div class=\"sense\"> &amp;c., v. sub <a href=\"#\" data-headword=\"מִנְיָמִין\">מֵינ׳</a>.</div>","alt":["מֵנִיקוּת"]},"13766":{"h":"מנישא","r":"M01790","html":"<div class=\"sense\">, <span class=\"citation\">Y. Meg. II, 73ᵇ</span>, read: <a href=\"#\" data-headword=\"מְנַשְׁיָיא\">מְנַשְׁיָא</a>.</div>","alt":[]},"13767":{"h":"מִנִּית","r":"M01791","html":"<div class=\"sense\"> (b. h.) pr. n. pl. <i>Minnith</i>, in Palestine. <span class=\"citation\">Lam. R. to III, 16</span> (play on <span dir=\"rtl\">בחטי מ׳</span>, <span class=\"citation\">Ez. XXVII, 17</span>) <span dir=\"rtl\">חטי דלא מניין</span> wheat dishes without number; ib. <span dir=\"rtl\">כמנין מ׳</span> as many as the numerical value of <a href=\"#\" data-headword=\"מִנִּית\">מנית</a> (500); <span class=\"citation\">Koh. R. to I, 8</span> (corr. acc.).</div>","alt":[]},"13768":{"h":"מנכייה","r":"M01792","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sot. V, 20ᶜ</span> bot., v. <a href=\"#\" data-headword=\"הַנְכָּיָה\">הַנְכָּיָיה</a></div>","alt":[]},"13769":{"h":"מְנָלָן","r":"M01793","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְנָא II\"><span dir=\"rtl\">מְנָא</span> II</a>.—[<span class=\"citation\">Yalk. Koh. 971</span> <span dir=\"rtl\">מרי מנלן</span>, v. <a href=\"#\" data-headword=\"מֵיכְלָא II\"><span dir=\"rtl\">מֵיכְלָא</span> II</a>.]</div>","alt":[]},"13770":{"h":"מנם","r":"M01794","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to V, 11</span> <span dir=\"rtl\">נתמנם</span> some ed., read: <a href=\"#\" data-headword=\"נוּם\">אִתְנַמְנֵם</a>, v. <a href=\"#\" data-headword=\"נוּם\">נַמְנֵם</a></div>","alt":[]},"13771":{"h":"מנמנמי","r":"M01795","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Num. XXVI, 9</span> Ar. (ed. <span dir=\"rtl\">מערעי</span>), read: <span dir=\"rtl\">מְזַמְּנֵי</span>, v. <a href=\"#\" data-headword=\"זְמַן I\"><span dir=\"rtl\">זְמַן</span> I</a></div>","alt":[]},"13772":{"h":"מְנָן","r":"M01796","html":"<div class=\"sense\"> (= <span dir=\"rtl\">מן אן</span>; cmp. <a href=\"#\" data-headword=\"מְנָא II\"><span dir=\"rtl\">מְנָא</span> II</a>) <i>whence?</i> <span class=\"citation\">Targ. Num. XI, 13</span>. <span class=\"citation\">Targ. O. Gen. XVI, 8</span> (Y. <span dir=\"rtl\">מן האן</span>). <span class=\"citation\">Targ. Jon. I, 8</span> (some ed. <span dir=\"rtl\">מפן</span>, corr. acc.); a. e.</div>","alt":["מְנַן","מִנָּן","מִי׳"]},"13773":{"h":"מִנַּסָּח","r":"M01797","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XXIX, 21</span>, v. <a href=\"#\" data-headword=\"נְסַח\">נְסַח</a>.</div>","alt":["מְנַסַּח"]},"13774":{"h":"מנסטאר","r":"M01798","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָגִיסְטֵיר\">מָגִיסְטֵיר</a></div>","alt":[]},"13775":{"h":"מנסקי","r":"M01799","html":"<div class=\"sense\">, <span class=\"citation\">Num. R. s. 12</span>; <span class=\"citation\">Sifré Num. 45</span>, v. <a href=\"#\" data-headword=\"אִסְקְפַסְטִי\">אִסְקְפַסְטִי</a></div>","alt":[]},"13776":{"h":"מָנַע","r":"M01800","html":"<div class=\"sense\"> (b. h.) [<i>to cut off</i>,] <i>to withhold, refuse, refrain</i>. <span class=\"citation\">Pes. 113ᵇ</span> <span dir=\"rtl\">המוֹנֵעַ מנעלים מרגליו</span> he who denies shoes to his feet. <span class=\"citation\">Keth. 96ᵃ</span> <span dir=\"rtl\">המונע תלמידו מלשמשו כאילו מונע וכ׳</span> he who denies to his pupil the privilege of attendance, is considered as if denying kindness to him. <span class=\"citation\">Ber. 10ᵃ</span>, sq. <span dir=\"rtl\">אל יִמְנַע עצמו מן הרחמים</span> must not cut himself off from (despair of) divine mercy. <span class=\"citation\">Gen. R. s. 76</span>, end (ref. to <span class=\"citation\">Job VI, 14</span>) <span dir=\"rtl\">מָנַעְתָּ מרעך וכ׳</span> thou (Jacob) didst refuse kindness to thy friend (Job); a. fr.</div><div class=\"sense\"><b>Nif. נִמְנַע</b> <div class=\"sense\"><b>1)</b> <i>to restrain one’s self; to shrink.</i> <span class=\"citation\">Eduy. IV, 8</span>; <span class=\"citation\">Yeb. I, 4</span> <span dir=\"rtl\">לא נִמְנְעוּ</span> (<a href=\"#\" data-headword=\"מ\">מ</a>)<span dir=\"rtl\">לישא וכ׳</span> they did not refrain from intermarriage. Ib. <span dir=\"rtl\"><span dir=\"rtl\">לא נ׳</span> (<span dir=\"rtl\">להיות</span>) <span dir=\"rtl\">עושין טהרות וכ׳</span></span> they did not shrink from relying on one another in the observances of levitical pureness; Tosef. ib. I, 10. Ib. 12 <span dir=\"rtl\"><span dir=\"rtl\">מן הספק לא היו נִמְנָעִין</span> (<a href=\"#\" data-headword=\"אָבֵל I\">אבל</a>) <span dir=\"rtl\">נמנעין וכ׳</span></span> they did not shrink (from interchange) where the case was doubtful &amp;c.; <span class=\"citation\">Yeb. 14ᵇ</span>. <span class=\"citation\">Gitt. 36ᵃ</span> <span dir=\"rtl\">נמנעו מלהלוות וכ׳</span> they hesitated to lend money to one another; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be withheld</i>. <span class=\"citation\">Num. R. s. 15</span> <span dir=\"rtl\">נִמְנְעָה השמחה וכ׳</span> (some ed. <span dir=\"rtl\">נִמְנַעַת</span></div></div><div class=\"sense\"><b>Hif. הִמְנִיעַ</b> <div class=\"sense\"><i>to keep apart</i>. Y. Taan. I, 64ᵇ top <span dir=\"rtl\">שאת מַמְנִיעָן זו מזו</span> for thou keepest them (the rain-drops) from commingling (v. <a href=\"#\" data-headword=\"דָּפוּס\">דָּפוּס</a>); Y. Ber. IX, 14ᵃ top <span dir=\"rtl\">ממנימען</span> (corr. acc.).</div></div>","alt":[]},"13777":{"h":"מְנַע","r":"M01801","html":"<div class=\"sense\">, <i>to diminish; to withhold</i>. <span class=\"citation\">Targ. Gen. XXII, 16</span>. <span class=\"citation\">Ib. XXX, 2</span>. <span class=\"citation\">Targ. O. Deut. XIII, 1</span> (h. text <a href=\"#\" data-headword=\"גָּרַע I\">גרע</a>); a. fr.</div><div class=\"sense\"><b>Ithpe. אִתְמְנַע  אִימְּנַע</b> <div class=\"sense\"><b>1)</b> <i>to be diminished; to cease, omit</i>. <span class=\"citation\">Targ. Ex. V, 11</span> (O. ed. Vien. <span dir=\"rtl\">יִתִּמְנַע</span>; h. text <a href=\"#\" data-headword=\"גָּרַע I\">גרע</a>). <span class=\"citation\">Ib. IX, 29</span> (h. text <a href=\"#\" data-headword=\"חָדַל\">חדל</a>). <span class=\"citation\">Targ. Deut. XXIII, 23</span> (O. ed. Vien. <span dir=\"rtl\">תִתִּמְנַע</span>). <span class=\"citation\">Targ. Jud. XV, 7</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to restrain one’s self; to refuse, shrink</i>. <span class=\"citation\">Targ. Ex. XXIII, 2</span>; a. e.—<span class=\"citation\">Gitt. 52ᵇ</span> <span dir=\"rtl\">אתי לאִימְּנוּעֵי</span> he might shrink (from becoming a guardian). Y. Sabb. VII, 9ᵇ bot. <span dir=\"rtl\">לא מִתְמַנְעִין</span>, v. <a href=\"#\" data-headword=\"ה\">ה&quot;א</a>; a. e.</div></div>","alt":[]},"13778":{"h":"מַנְעוּל","r":"M01802","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>lock</i>. <span class=\"citation\">B. Bath. 65ᵇ</span>; <span class=\"citation\">Tosef. ib. III, 1</span> <span dir=\"rtl\">את הנגר ואת המ׳</span> the bolt (fastened to the wall) and the lock (fastened to the door), opp. to <span dir=\"rtl\">מפתח</span> the portable key. <span class=\"citation\">M. Kat. I, 10</span>. <span class=\"citation\">Zab. IV, 3</span>; a. fr.—Trnsf. <i>the lock of the buttock, anus</i>. <span class=\"citation\">Koh. R. to III, 19</span>; <span class=\"citation\">Gen. R. s. 17</span> (some ed. <a href=\"#\" data-headword=\"מַנְעָל\">מַנְעָל</a>); <span class=\"citation\">Yalk. Koh. 969</span> <span dir=\"rtl\">מנעל</span>; v. <a href=\"#\" data-headword=\"*אֱפִיפְּיוֹן\">אֱפִיפְּיוֹן</a>.</div>","alt":[]},"13779":{"h":"מִנְעוֹל","r":"M01803","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"נַעַל\">נַעַל</a>) <i>foot-covering, shoe</i>, contrad. to <a href=\"#\" data-headword=\"סַנְדָּל\">סנדל</a> sole. <span class=\"citation\">Kel. XXVI, 4</span>. <span class=\"citation\">Esth. R. to IV, 15</span>, v. <a href=\"#\" data-headword=\"לָחַךְ\">לָחַךְ</a>. <span class=\"citation\">Yeb. XII, 1</span>. <span class=\"citation\">Tosef. ib. XII, 10</span> <span dir=\"rtl\">במ׳ שנפרם וכ׳</span> with a torn shoe which still covers the larger portion of the foot; a. fr.—Pl. <span dir=\"rtl\">מִנְעָלִים</span>, <span dir=\"rtl\">מִנְעָלִין</span>. <span class=\"citation\">Sabb. 129ᵃ</span>. <span class=\"citation\">Pes. 113ᵇ</span>, v. <a href=\"#\" data-headword=\"מָנַע\">מָנַע</a>. <span class=\"citation\">Y. Sabb. VI, 8ᵃ</span>; a. fr.—<span class=\"citation\">Kil. IX, 7</span> <span dir=\"rtl\">מִנְעֲלוֹת הפינון</span>. cloth <i>socks</i>, v. <a href=\"#\" data-headword=\"דַּרְדְּסָא\">דַּרְדְּסָא</a>.</div>","alt":["מִנְעָל"]},"13780":{"h":"מַנְעָל","r":"M01804","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַנְעוּל\">מַנְעוּל</a></div>","alt":[]},"13781":{"h":"מְנָפָה","r":"M01805","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נוּף\">נוּף</a>) </div><div class=\"sense\"><b>1)</b> <i>fan.</i> <span class=\"citation\">Kel. XVI, 7</span> (Ar. <span dir=\"rtl\">מנפא</span>). <span class=\"citation\">Yeb. 63ᵃ</span> במ׳ תתנופפי Ar., v. <a href=\"#\" data-headword=\"נוּף\">נוּף</a> ch.—V. <a href=\"#\" data-headword=\"מְנִיפָא\">מְנִיפָא</a>.—</div><div class=\"sense\"><b>*2)</b>  (v. <a href=\"#\" data-headword=\"מַפָּה\">מַפָּה</a>) <i>flag</i>.—Pl. <span dir=\"rtl\">מְנָפוֹת</span>. Mekh. B’shall., s. 2 <span dir=\"rtl\">מגפות</span> (corr. acc.); v., however, <a href=\"#\" data-headword=\"סִיגְנוּם\">סִיגְנוֹן</a>.</div>","alt":[]},"13782":{"h":"מנפוח","r":"M01806","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 17</span>, read: <a href=\"#\" data-headword=\"מִנְפִּיס\">מִנְפִּיס</a>.</div>","alt":[]},"13783":{"h":"מָנְפּוֹל","r":"M01807","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μονοπώλιον) <i>a trading mart enjoying a monopoly.</i> <span class=\"citation\">Dem. V, 4</span> <span dir=\"rtl\">בלוקח מן המ׳</span> when he buys (loaves of bread) in a monopolized market (where the numbers of bakers and of retailers are limited). Y. ib. 24ᵈ top <span dir=\"rtl\">איזהו מ׳ וכ׳</span> what sort of a mart? Where there are nine sellers supplied by eight bakers, so that eight may have bought from one baker severally, but one baker must necessarily have supplied at least two sellers.</div>","alt":[]},"13784":{"h":"מִנְפִּיס","r":"M01808","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Μένφ, Μέμφις) <i>Memphis</i>, in Egypt. <span class=\"citation\">Pesik. R. s. 17</span> <span dir=\"rtl\">נוף מנפוח</span>; Pesik. Vayhi, p. 63ᵇ <a href=\"#\" data-headword=\"מרפיס\">מרפיס</a> (corr. acc.) the Biblical Nof is Memphis; v. <a href=\"#\" data-headword=\"מָפֵיס\">מָפֵיס</a>.</div>","alt":[]},"13785":{"h":"מנפש","r":"M01809","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. III, 1</span> ed. Zuck., v. <a href=\"#\" data-headword=\"מְגָפַיִּים\">מְגָפַיִים</a></div>","alt":[]},"13786":{"h":"מַנְצְפַ\"ךְ","r":"M01810","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>Mantsʾfakh</i>, a vox memorialis for the five letters (<a href=\"#\" data-headword=\"מ\">מ</a>, <a href=\"#\" data-headword=\"נ\">נ</a>, <a href=\"#\" data-headword=\"צ\">צ</a>, <a href=\"#\" data-headword=\"פ\">פ</a>, a. <a href=\"#\" data-headword=\"כ\">ך</a>) which have separate forms at the end of words. <span class=\"citation\">Y. Meg. I, 71ᵈ</span> <span dir=\"rtl\">מ׳ הלכה וכ׳</span> the double forms for the five letters are a Mosaic tradition. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מהו מ׳ … מ̇ה שהתקינ̇ו לך̇ הצ̇ופ̇ים</span> what does the vox M. intimate? What the inspired seers (prophets) have instituted for thee; <span class=\"citation\">Gen. R. s. 1</span>. Ib.; <span class=\"citation\">Sabb. 104ᵃ</span>; <span class=\"citation\">Meg. 2ᵇ</span> מ׳ צופים אמרום M. intimates that the seers indited them; <span class=\"citation\">Num. R. s. 18</span>; Tanḥ. Korah 12.</div>","alt":[]},"13787":{"h":"מנקדותא","r":"M01811","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְנַקִּירוּתָא\">מְנַקִּירוּתָא</a></div>","alt":[]},"13788":{"h":"מנקט","r":"M01812","html":"<div class=\"sense\">, <span class=\"citation\">Ab. d’R. N. ch. XVIII</span>, end, v. <a href=\"#\" data-headword=\"מְלַקֵּט I\">מְלַקֵּט</a></div>","alt":[]},"13789":{"h":"מְנַקְטָא","r":"M01813","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְקַט\">נְקַט</a>) <i>holder</i>, <span dir=\"rtl\">מ׳ פארי</span> <i>a band on which various trinkets are suspended</i>. <span class=\"citation\">Sabb. 59ᵇ</span> (defining <a href=\"#\" data-headword=\"קטלא\">קטלא</a>), v. <a href=\"#\" data-headword=\"פְּאֵרָא\">פְּאֵרָא</a>.</div>","alt":[]},"13790":{"h":"*מְנַקִּיּוֹת","r":"M01814","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"><i>tubes</i>. <span class=\"citation\">Men. 97ᵃ</span> (ref. to <span class=\"citation\">Ex. XXV, 29</span>) <span dir=\"rtl\">מְנַקִּיּוֹתָיו אלו קנים</span> by <i>m’naḳḳiyoth</i> are meant the tubes placed between the show-loaves to let the air pass; Rashi: ‘which keep the bread clean from mould’, fr. <a href=\"#\" data-headword=\"נקי\">נָקָה</a>); v. <a href=\"#\" data-headword=\"סָכַךְ I\">סָכַךְ</a> I <i>Pi.</i>—[LXX translates our w. with κύαθοι.]</div>","alt":[]},"13791":{"h":"מְנַקִּירוּתָא","r":"M01815","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (נְקַר II) <i>cleanliness</i>. <span class=\"citation\">Ḥull. 105ᵇ</span> (Ar. <span dir=\"rtl\">מנקד׳</span>). <span class=\"citation\">Ab. Zar. 30ᵃ</span> (Ar. <span dir=\"rtl\">מנקד׳</span>; Ms. M. <a href=\"#\" data-headword=\"נַקְיוּתָא\">נַקְיוּתָא</a>.]</div>","alt":["מְנַקְּרוּתָא"]},"13792":{"h":"מֵנֶקֶת","r":"M01816","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָנַק\">יָנַק</a>, a. <a href=\"#\" data-headword=\"מֵינֶקֶת\">מֵינֶקֶת</a>.</div>","alt":[]},"13793":{"h":"מְנָרְתָּא","r":"M01817","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>lamp</i>. <span class=\"citation\">Targ. Ex. XXV, 31</span>; a. fr.—<span class=\"citation\">Y. Yoma III, 41ᵃ</span> top, expl. <a href=\"#\" data-headword=\"נִבְרֶשֶׁת\">נברשת</a>. <span class=\"citation\">Gen. R. s. 63</span>, end (translat. <span dir=\"rtl\">צפה הצפית</span>, <span class=\"citation\">Is. XXI, 5</span>) <span dir=\"rtl\">סדר מ׳</span> arrange the lamp; <span class=\"citation\">Cant. R. to III, 4</span> <span dir=\"rtl\">אקימת מ׳ וכ׳</span> thou (Belshazzar) hast put up the lamp, kindled the light; a. fr.—Pl. <a href=\"#\" data-headword=\"מְנָרְתָּא\">מְנָרָתָא</a>. <span class=\"citation\">Targ. Jer. LII, 19</span>; a. e.</div>","alt":["מְנַר׳"]},"13794":{"h":"מְנַשֶּׁה","r":"M01818","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Manasseh</i>, </div><div class=\"sense\"><b>1)</b>  son of Joseph; also <i>the tribe of Manasseh</i>. <span class=\"citation\">Gen. R. s. 84</span> מ׳ גרם לשבטים לקרוע M. was the cause that the sons of Jacob rent their garments (<span class=\"citation\">Gen. XLIV, 13</span>; v. <span class=\"citation\">Gen. R. s. 91</span>); a. fr.</div><div class=\"sense\"><b>—2)</b> M., King of Judah. <span class=\"citation\">Snh. X, 2</span>; <span class=\"citation\">Tosef. ib. XII, 11</span>. <span class=\"citation\">Yeb. 49ᵇ</span> מ׳ הרג וכ׳ M. put Isaiah to death; a. fr.</div><div class=\"sense\"><b>—3)</b> M., grandfather of Jonathan (<span class=\"citation\">Jud. XVIII, 30</span>). <span class=\"citation\">Tosef. Snh. XIV, 8</span>; <span class=\"citation\">B. Bath. 109ᵇ</span> <span dir=\"rtl\">וכי בן מ׳ וכ׳</span> was he the son of M.? Was he not the son of Moses? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מתוך שעשה מעשה מ׳ וכ׳</span></div><div class=\"sense\"><b>—4)</b> M., a scholar. <span class=\"citation\">Y. Meg. II, 73ᵃ</span> bot.</div>","alt":[]},"13795":{"h":"מְנַשְׁיָיא","r":"M01819","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>M’nashia</i>. <span class=\"citation\">Y. M. Kat. III, 83ᶜ</span> top; <span class=\"citation\">Y. Meg. III, 73ᵇ</span> <a href=\"#\" data-headword=\"מניישא\">מניישא</a>, <a href=\"#\" data-headword=\"מנישא\">מנישא</a> (corr. acc.).</div>","alt":["מְנַשְׁיָא"]},"13796":{"h":"מְנָת","r":"M01820","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>portion, share</i>. <span class=\"citation\">B. Bath. 12ᵃ</span> מ׳ בכרם וכ׳ I sell thee a portion of my vineyard.—<span dir=\"rtl\">מְנַת המלך</span> the king’s share (<i>annona</i>). <span class=\"citation\">Ned. 62ᵇ</span>; <span class=\"citation\">B. Bath. 8ᵃ</span>, v. <a href=\"#\" data-headword=\"מִנְדָּה\">מִנְדָּה</a>. <span class=\"citation\">Ab. Zar. 71ᵃ</span> <span dir=\"rtl\">הפס עלי מ׳ מלך</span> settle for me the <i>annona</i> (in kind or money).</div><div class=\"sense\"><b>—2)</b> <i>appointment</i>; <span dir=\"rtl\">בִּמְנַת</span>, <span dir=\"rtl\">עַל מְנַת</span> (abbrev. <span dir=\"rtl\">ע&quot;מ</span>) <i>on condition that, for the sake of</i>. <span class=\"citation\">Tosef. Dem. VI, 13</span> <span dir=\"rtl\">ואם התנה עמו במ׳ כן</span> ed. Zuck. (Var. … <span dir=\"rtl\">מתחלה ע&quot;מ לעשות כן</span>) but if he originally had made that agreement (of dividing the profits) with him. <span class=\"citation\">Ib. VII, 3</span> <span dir=\"rtl\">ע&quot;מ שהמעשרות שלי</span> with the condition that the tithes be mine. <span class=\"citation\">Y. B. Mets. V, 10ᵇ</span> bot. <span dir=\"rtl\">במ׳ לעלות לו וכ׳</span> with the condition that he will give him (as his share) one new-born animal or one crop of wool. <span class=\"citation\">Ab. I, 3</span>, v. <a href=\"#\" data-headword=\"עֶבֶד\">עֶבֶד</a>. <span class=\"citation\">Tosef. Snh. XI, 2</span> יודע אני וע&quot;מ כן אני עושה I know (the nature of the offence and its penalty), and on that condition I am committing it; Mekh. Mishp. s. 20 <span dir=\"rtl\">יודע אני ע&quot;מ כן</span> (read: <span dir=\"rtl\">וע&quot;מ</span>). <span class=\"citation\">Kidd. 6ᵇ</span> <span dir=\"rtl\">מתנה ע&quot;מ להחזיר</span> a present made with the condition that it shall be returned (possession for the time being); a. v. fr.—<span class=\"citation\">Ab. Zar. 37ᵃ</span>, a. fr. <span dir=\"rtl\">כל האומר ע&quot;מ … מעכשיו דמי</span> if a man says ‘on condition’, it is to be considered as if he had said ‘from now’, i.e. the stipulated transaction takes retrospective effect when the condition is fulfilled.—<span class=\"citation\">B. Bath. X, 8</span> (<span class=\"citation\">175ᵇ</span>) <span dir=\"rtl\">על מְנָתוֹ הלוהו</span> Ar. (ed. <span dir=\"rtl\">אמונתו</span>, v. <a href=\"#\" data-headword=\"אֱמוּנָה\">אֱמוּנָה</a>) he extended the loan to him (the friend) on the condition which he (the guarantor) offered.</div>","alt":[]},"13797":{"h":"מְנַת","r":"M01821","html":"<div class=\"sense\"> <span class=\"citation\">Targ. II Sam. VI, 19</span> (ed. Wil. <a href=\"#\" data-headword=\"מְנַת\">מָנָתָא</a>).—<span class=\"citation\">B. Bath. 167ᵃ</span> (in a contract) <span dir=\"rtl\">מנת ראובן ושמעון אַחֵי</span> the share of Reuben and Simeon the brothers. <span class=\"citation\">B. Kam. 113ᵇ</span> <span dir=\"rtl\">מ׳ דמלכא</span> = <span dir=\"rtl\">מנת המלך</span>, v. <a href=\"#\" data-headword=\"מְנָת\">preced.</a> <span class=\"citation\">B. Mets. 109ᵇ</span> <span dir=\"rtl\">מ׳ דילך</span> thy share. <span class=\"citation\">Yeb. 37ᵇ</span>; a. e.—<span dir=\"rtl\">על מ׳</span>, v. <a href=\"#\" data-headword=\"מְנָת\">preced.</a> <span class=\"citation\">Targ. Y. II, Gen. XLIV, 18</span> <span dir=\"rtl\">ע&quot;מ מיעבד וכ׳</span> even if it must be done against the will &amp;c.—Pl. <a href=\"#\" data-headword=\"מַנְוָותָא\">מַנְוָותָא</a>. Targ. II Esth. II, 9.</div>","alt":["מְנָתָא"]},"13798":{"h":"מַס I","r":"M01822","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָסַס\">מָסַס</a>) </div><div class=\"sense\"><b>1)</b>  (cmp. <a href=\"#\" data-headword=\"מִסְמֵס II\"><span dir=\"rtl\">מִסְמֵס</span> II</a>) <i>juice</i>. <span class=\"citation\">Num. R. s. 14</span> (play on <span dir=\"rtl\">כמ̇שמ̇ר̇ו̇ת̇</span>, <span class=\"citation\">Koh. XII, 11</span>) <span dir=\"rtl\">כמ̇ס̇ מ̇ר̇ו̇ת̇</span> (bitter) as the juice of bitter things, v. <a href=\"#\" data-headword=\"מִסְמֵס II\"><span dir=\"rtl\">מִסְמֵס</span> II</a>.</div><div class=\"sense\"><b>—2)</b> <i>melting, fainting</i>. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">שרתי</span>, v. <a href=\"#\" data-headword=\"לָמַס\">לָמַס</a>.</div>","alt":[]},"13799":{"h":"מַס II","r":"M01823","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.; = <span dir=\"rtl\">מנס</span>; <span dir=\"rtl\">נסה</span> = <span dir=\"rtl\">נשא</span>) <i>impost, tribute, tax</i>. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">שרתי</span>, v. <a href=\"#\" data-headword=\"לָמַס\">לָמַס</a> a. <a href=\"#\" data-headword=\"מַסָּא I\"><span dir=\"rtl\">מַסָּא</span> I</a>.—Pl. <a href=\"#\" data-headword=\"מִיסִּים\">מִסִּים</a>, <a href=\"#\" data-headword=\"מִיסִּים\">מִסִּין</a>. <span class=\"citation\">Y. Dem. II, 22ᵈ</span> top <span dir=\"rtl\">מעלי מ׳ כמי שנתכבשו</span> the places which were made tributary (under Joshua) are considered as conquered (belonging to the Holy Land); <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span> bot. <span dir=\"rtl\">בעלי סיסין</span> (corr. acc.); <span class=\"citation\">Gen. R. s. 98</span>. <span class=\"citation\">Lev. R. s. 33</span>, end <span dir=\"rtl\">לא למסגד אלא למפלח במ׳ וכ׳</span> (this <span dir=\"rtl\">ועבדתם</span>, <span class=\"citation\">Deut. IV, 28</span>) does not mean ‘to worship’ but ‘to serve’ by paying imposts, <i>annonae</i> &amp;c. Ib.; <span class=\"citation\">Cant. R. to II, 14</span> <span dir=\"rtl\">אם למ׳ … את מלך עלינו וכ׳</span> (some ed. <span dir=\"rtl\">לפסים</span></div>","alt":[]},"13800":{"h":"מִסָּא","r":"M01824","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Prov. XII, 24</span>, v. <a href=\"#\" data-headword=\"מַדָּאתָא\">מַדָּאתָא</a>.—Pl. <a href=\"#\" data-headword=\"מִיסִּים\">מִסִּין</a>, <a href=\"#\" data-headword=\"מִיסִּים\">מִיסִּין</a>. <span class=\"citation\">Targ. Josh. XVII, 13</span>; a. fr.</div>","alt":["מִיסָּא"]},"13801":{"h":"מַסָּא I","r":"M01825","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> I, <i>melting</i>; <span dir=\"rtl\">מ׳ דליבא</span> <i>faint heartedness</i>. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">שרתי</span>, v. <a href=\"#\" data-headword=\"לָמַס\">לָמַס</a>.</div>","alt":[]},"13802":{"h":"מַסָּא II","r":"M01826","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">נסא</span>, v. <a href=\"#\" data-headword=\"נְסַח\">נְסַח</a>) <i>peel, shovel</i> for taking bread out of the oven. <span class=\"citation\">Taan. 25ᵃ</span> <span dir=\"rtl\">אייתי מ׳ וכ׳</span> bring the shovel, for thy bread is getting charred. <span class=\"citation\">Bekh. 27ᵃ</span> <span dir=\"rtl\">שקלה לה בריש מ׳</span> she takes the priest’s gift of the dough on the point of the shovel (to avoid direct contact).</div>","alt":[]},"13803":{"h":"מְסָא","r":"M01827","html":"<div class=\"sense\"><i>to melt</i>, v. <a href=\"#\" data-headword=\"מְסֵי\">מְסֵי</a> a. <a href=\"#\" data-headword=\"מְסַס\"><a href=\"#\" data-headword=\"מְסַס\">מְסַס</a>.</a></div>","alt":[]},"13804":{"h":"מְסָאָב","r":"M01828","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְאֵב I\">סְאַב</a>) <i>repulsive; unclean</i>. <span class=\"citation\">Targ. O. Lev. V, 2</span> (Y. <a href=\"#\" data-headword=\"מְסָאִיב\">מְסָאִיב</a>). Ib. XIII, 45; a. fr.—<span class=\"citation\">Eduy. VIII, 4</span> Ms. M. (ed. <span dir=\"rtl\">מסתאב</span>); <span class=\"citation\">Ab. Zar. 37ᵃ</span>; a. e.—Pl. <span dir=\"rtl\">מְסָאֲבִין</span>, <span dir=\"rtl\">מְסַאֲבִין</span>. <span class=\"citation\">Targ. Lev. XI, 26</span>; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"מְסָאָב\">מְסָאֲבָא</a>, <span dir=\"rtl\">מְסָאַבְתָּא</span>. <span class=\"citation\">Targ. Ez. IV, 14</span>. <span class=\"citation\">Targ. Lev. V, 2</span>; a. fr.—<span class=\"citation\">Y. Kil. IX, 32ᶜ</span> bot. <span dir=\"rtl\">ארעא מ׳</span> an unclean land (outside of Palestine); <span class=\"citation\">Y. Keth. XII, 35ᵇ</span> <span dir=\"rtl\">מְסָאַבְתָּה</span>.</div>","alt":["מְסָאֲבָא"]},"13805":{"h":"מסאחייא","r":"M01829","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסַחֲרַיָּא\">מְסַחֲרַיָּא</a></div>","alt":[]},"13806":{"h":"מסאחתא","r":"M01830","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְחֲתָא\">מְסַחְתָּא</a></div>","alt":[]},"13807":{"h":"מְסָאִיב","r":"M01831","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסָאָב\">מְסָאָב</a></div>","alt":[]},"13808":{"h":"מְסָאנָא","r":"M01832","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סאן <i>to tread;</i> v. <a href=\"#\" data-headword=\"סֵינָא\">סֵינָא</a>) <i>shoe</i>. <span class=\"citation\">Targ. Ps. LX, 10</span> (ed. Wil. <a href=\"#\" data-headword=\"מְסַן\">מְסָנַי</a> <i>pl.</i>); a. e.—<span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">הוה שליפא מ׳</span> she happened to be barefooted. <span class=\"citation\">Ib. 56ᵇ</span> <span dir=\"rtl\">הוה סיים חד מ׳</span> (not <span dir=\"rtl\">מסאני</span>) he had put on one shoe. <span class=\"citation\">Kidd. 49ᵃ</span>, v. <a href=\"#\" data-headword=\"כַּרְעָא\">כַּרְעָא</a>. <span class=\"citation\">Gen. R. s. 41</span>, beg.; s. 52, end, v. <a href=\"#\" data-headword=\"טוֹלְמִיסִין\">טוֹלְמִיסִין</a>; a. e.—<i>Pl.</i> <span dir=\"rtl\">מְסָאנֵי</span>. <span class=\"citation\">Lam. R. to I, 5</span> <span dir=\"rtl\">תרין מְסָאנַי</span> both my shoes. <span class=\"citation\">Taan. 22ᵃ</span> <span dir=\"rtl\">מ׳ אוכמי</span> black shoes (worn by gentiles).—Contr. <a href=\"#\" data-headword=\"מְסַן\">מְסַן</a>, <a href=\"#\" data-headword=\"מְסַן\">מְסָנָא</a>, q. v.</div>","alt":[]},"13809":{"h":"מסאנא","r":"M01833","html":"<div class=\"sense\">, <span class=\"citation\">Y. Dem. II, 21ᵈ</span> bot., v. <a href=\"#\" data-headword=\"מְסַנְתָּא\">מְסַנְתָּא</a></div>","alt":[]},"13810":{"h":"מַסָּאסָא","r":"M01834","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נסא <i>to move; Hif. to drive</i>; v. Fl. to Levy Talm. Dict. III, p. 313ᵃ) <i>ox-goad</i>. Pesik. Baḥod., p. 153ᵃ; <span class=\"citation\">Lev. R. s. 29</span>; <span class=\"citation\">Yalk. Lev. 645</span> <a href=\"#\" data-headword=\"מאסאסה\">מאסאסה</a> (corr. acc.); <span class=\"citation\">Yalk. Num. 782</span>. [Ar. s. v. <a href=\"#\" data-headword=\"סְקַד\">סקד</a>: <a href=\"#\" data-headword=\"מַסָּסָא\">מַסָּסָא</a>.]</div>","alt":[]},"13811":{"h":"מְסַאר","r":"M01835","html":"<div class=\"sense\"><i>to saw</i>, v. <a href=\"#\" data-headword=\"מְסַר II\"><span dir=\"rtl\">מְסַר</span> II</a>.</div>","alt":[]},"13812":{"h":"מְסָארָא","r":"M01836","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסָרָא\">מְסָרָא</a></div>","alt":[]},"13813":{"h":"מְסָאתָא","r":"M01837","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָסָא\">נְסָא</a>; v. P. Sm. 2179; 2391) <i>balance, pair of scales</i>. <span class=\"citation\">Targ. Prov. XVI, 11</span> ed. Lag. (ed. Wil. <a href=\"#\" data-headword=\"מְסָחָא\">מְסָחָא</a>). <span class=\"citation\">Ib. XI, 1</span> ed. Lag. (Var. <span dir=\"rtl\">מסאכא</span>, corr. acc.; ed. Wil. <a href=\"#\" data-headword=\"מְסָחָא\">מסחא</a>). <span class=\"citation\">Ib. XX, 23</span> (ed. Lag. a. oth. <a href=\"#\" data-headword=\"מְשַׁחְתָּא\">מִשְׁחֲתָא</a>); v. <a href=\"#\" data-headword=\"מִסְחֲתָא\">מִסְחֲתָא</a>.</div>","alt":[]},"13814":{"h":"מִסַּב","r":"M01838","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִיסַּב\">מִיסַּב</a></div>","alt":["מֵסַב"]},"13815":{"h":"מֵסֵב","r":"M01839","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>dining couch</i>. <span class=\"citation\">Sabb. 63ᵃ</span> top <span dir=\"rtl\">במ׳ רחב וכ׳</span> on a wide couch or on a narrow couch (an obscene disguise for a fat or a lean woman, v. <a href=\"#\" data-headword=\"גּוּרְדְּלִי\">גּוּרְדְּלִי</a>).—<span class=\"citation\">Cant. R. to I, 12</span> במְסִבּוֹ ברקיע ‘on his couch’ (ib.), in heaven.</div>","alt":["מֵי׳"]},"13816":{"h":"מְסִבָּה","r":"M01840","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מֵסֵב\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>banqueting party</i>. <span class=\"citation\">Sabb. 149ᵇ</span> bot.</div><div class=\"sense\"><b>—2)</b> <i>banquet, dinner</i>. <span class=\"citation\">Ber. 52ᵇ</span> <span dir=\"rtl\">סתם מְסִבַּת כותים לע&quot;ז</span> (Ms. M. <span dir=\"rtl\">הסבת גוים</span>) the banqueting of gentiles is presumed to be dedicated to idolatry. <span class=\"citation\">B. Bath. 120ᵃ</span> <span dir=\"rtl\">במ׳ הלך אחר זקנה</span> in sitting down for a festive meal age takes the precedence.</div><div class=\"sense\"><b>—3)</b>  (b. h.) <i>winding staircase.</i> <span class=\"citation\">Tam. I, 1</span> <span dir=\"rtl\">מ׳ ההולכת וכ׳</span> the staircase leading (to a well) under the Temple. <span class=\"citation\">Midd. IV, 5</span>; a. fr.</div>","alt":["מְסִיבָּה"]},"13817":{"h":"מְסִבְּתָא","r":"M01841","html":"<div class=\"sense\">, <i>winding staircase</i>. <span class=\"citation\">Targ. Ez. XLI, 7</span> (h. text <span dir=\"rtl\">נסבה</span>!).—Pl. <a href=\"#\" data-headword=\"מְסִבְּתָא\">מְסִבָּתָא</a>, <a href=\"#\" data-headword=\"מְסִבְּתָא\">מְסִי׳</a>. Ib. <span class=\"citation\">Targ. I Kings VI, 8</span> (h. text <span dir=\"rtl\">לולים</span>).</div>","alt":["מְסִי׳"]},"13818":{"h":"*מַסְבֵּךְ","r":"M01842","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָבַךְ\">סָבַךְ</a>) <i>a netted, meshy plant</i>, perh. <i>pine-cone.</i> <span class=\"citation\">Par. III, 3</span> <span dir=\"rtl\">קושרין מקל ומ׳ וכ׳</span> (Var. <span dir=\"rtl\">או מ׳</span>) they tied (to the top of the rope) a stick with a cone (to which the ashes would adhere).</div>","alt":[]},"13819":{"h":"מסבלי","r":"M01843","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסוּבְלָא\">מְסוּבְלָא</a></div>","alt":[]},"13820":{"h":"מסבסלה","r":"M01844","html":"<div class=\"sense\">, a corrupt. for <span dir=\"rtl\">מִסְפִּילָא</span> m. pl. (μέσπιλα) <i>medlars</i>. <span class=\"citation\">Y. Sabb. VII, 10ᵃ</span> bot. [read:] <span dir=\"rtl\">ההן דשטח … מ׳ ומלקטן</span> he who spreads (for drying) dates, grapes or medlars and gathers them (on the Sabbath).</div>","alt":["מסוסלא"]},"13821":{"h":"מִסְגֵּי","r":"M01845","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סְגֵי I) <i>multitude</i>. <span class=\"citation\">Targ. Y. Deut. X, 22</span>. <span class=\"citation\">Targ. O. Gen. XXX, 30</span>; a. e.—[<span class=\"citation\">Targ. Is. V, 24</span>, v. <a href=\"#\" data-headword=\"מַסְגָּן\">מַסְגָּן</a>.]—V. <a href=\"#\" data-headword=\"סְגֵי III\"><span dir=\"rtl\">סְגֵי</span> III</a>.</div>","alt":[]},"13822":{"h":"מַסְגֵּירָא","r":"M01846","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסְגֵּרָא\">מַסְגֵּרָא</a></div>","alt":[]},"13823":{"h":"מַסְגָּן","r":"M01847","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סְגֵי I) <i>greatness</i>. <span class=\"citation\">Targ. Is. V, 24</span> (ed. Lag. <a href=\"#\" data-headword=\"מִסְגֵּי\">מִסְגֵּי</a>).</div>","alt":[]},"13824":{"h":"מַסְגֵּר","r":"M01848","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>enclosure</i>. <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">ונעל המ׳ בפניה</span> he locked the enclosure up before it (the cattle). <span class=\"citation\">Y. B. Kam. V, 4ᵈ</span> bot.; ib. VI, 5ᵇ bot. (in Chald. diction) <span dir=\"rtl\">דאית לה מ׳</span> (not <span dir=\"rtl\">ליה</span>) when it (the stack of grain) has an enclosure around it.</div><div class=\"sense\"><b>—2)</b> <i>locksmith;</i> (allegorically) <i>scholar</i>. <span class=\"citation\">Snh. 38ᵃ</span>; <span class=\"citation\">Gitt. 88ᵃ</span>; v. <a href=\"#\" data-headword=\"סָגַר\">סָגַר</a>.</div>","alt":[]},"13825":{"h":"מַסְגֵּרָא","r":"M01849","html":"<div class=\"sense\">, <i>enclosure, prison</i>. <span class=\"citation\">Targ. Ps. CXLII, 8</span>.</div>","alt":["מַסְגֵּי׳"]},"13826":{"h":"מִסְגַּרְיָא","r":"M01850","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Misgaria</i>, in Babylonia. <span class=\"citation\">Kidd. 72ᵃ</span> (Rashi: <span dir=\"rtl\">מסיגריא</span>).</div>","alt":[]},"13827":{"h":"מִסְגֶּרֶת","r":"M01851","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>rim</i>. <span class=\"citation\">Men. 96ᵇ</span> <span dir=\"rtl\">מִסְגַּרְתּוֹ</span> the rim of the table; <span class=\"citation\">Succ. 5ᵃ</span>; <span class=\"citation\">Yalk. Ex. 369</span>.</div>","alt":[]},"13828":{"h":"מָסָה","r":"M01852","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מסי\">מסי</a></div>","alt":[]},"13829":{"h":"מַסָּה","r":"M01853","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>trial; wonder</i>.—Pl. <a href=\"#\" data-headword=\"מסות\">מַסּוֹת</a>. <span class=\"citation\">Pesik. R. s. 33</span>. <span class=\"citation\">Deut. R. s. 7</span>, v. <a href=\"#\" data-headword=\"מָסָה\">מָסָה</a>.</div>","alt":[]},"13830":{"h":"מְסַהֲדָא","r":"M01854","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְהֵד\">סְהַד</a>) <i>witness</i>. <span class=\"citation\">Targ. Job XVI, 19</span>.</div>","alt":[]},"13831":{"h":"מְסוֹ","r":"M01855","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָסָה\">מָסָה</a>; cmp. <a href=\"#\" data-headword=\"הֶמְסֵס\">הֶמְסֵס</a>) <i>a liquid substance used for curdling</i>. <span class=\"citation\">Gen. R. s. 4</span>, end <span dir=\"rtl\">טיפה אחת של מ׳</span> one drop of <i>m’so</i>. <span class=\"citation\">Gen. R. s. 14</span>; <span class=\"citation\">Lev. R. s. 14</span>; <span class=\"citation\">Yalk. Job 905</span>.</div>","alt":[]},"13832":{"h":"מסו","r":"M01856","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 78ᵃ</span>, read with Ms. M. <a href=\"#\" data-headword=\"מְסַן\">מַסָּן</a> = <a href=\"#\" data-headword=\"מְאַסָּא\">מְאַסָּן</a>, v. <a href=\"#\" data-headword=\"אֲסִי\">אֲסִי</a></div>","alt":[]},"13833":{"h":"מַסּוּאָה","r":"M01857","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשּׂוּאָה\">מַשּׂוּאָה</a></div>","alt":[]},"13834":{"h":"מְסוּבֶּה","r":"M01858","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָבַב\">סָבַב</a>; v. <a href=\"#\" data-headword=\"מְסִבָּה\">מְסִבָּה</a>) <i>reclining; invited guest</i>. <span class=\"citation\">Lam. R. to IV, 2</span> (in Chald. diction) <span dir=\"rtl\">לית את מ׳</span> thou art not invited.—Pl. <span dir=\"rtl\">מְסוּבִּין</span> <i>guests, dining party</i>. <span class=\"citation\">Gen. R. s. 71</span> <span dir=\"rtl\">רוב מ׳ של לאה היו אעפ&quot;כ וכ׳</span> (not <a href=\"#\" data-headword=\"לְפִיכָךְ\">לפיכך</a>) most of the guests (assembled at Boas’ wedding, <span class=\"citation\">Ruth IV, 11</span>) were descendants of Leah, and yet they made Rachel the chief person (placing her before Leah); Ruth R. to l. c.; Pesik. Ronni, p. 141ᵇ (not <span dir=\"rtl\">מסובן</span>); a. e.</div>","alt":[]},"13835":{"h":"מְסוּבִיתָא","r":"M01859","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְבָא\">סְבָא</a>; v. <a href=\"#\" data-headword=\"סַבּוֹיָתָא\">סַבּוֹיָתָא</a>) <i>keeper of a wine shop</i>. <span class=\"citation\">Ab. Zar. 70ᵇ</span> ההיא מ׳ דמסרה לאקלידא לגויה Ms. M. (ed. incorr.) a shopkeeper who gave her key in charge of a gentile woman.—[<span class=\"citation\">Sabb. 105ᵇ</span> Alf. Ms. <span dir=\"rtl\">מס׳</span>, v. <a href=\"#\" data-headword=\"מְצוֹבִיתָא\">מְצוּבִיתָא</a>.</div>","alt":[]},"13836":{"h":"מְסוּבְלָא","r":"M01860","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְבַל\">סְבַל</a>) <i>load</i>.—Pl. <span dir=\"rtl\">מְסוּבְלֵי</span>. <span class=\"citation\">B. Bath. 86ᵃ</span> במס׳ דתומי Ar. (Ms. H. <a href=\"#\" data-headword=\"מסבלי\">מְסַבְלֵי</a>, Ms. M. <span dir=\"rtl\">מְסָאבְלֵי</span>, v. Rabb. D. S. a. l. note; ed. <a href=\"#\" data-headword=\"*מְתָאכְלֵי\">מְתָאכְלֵי</a> q. v.) in the case of loads of garlic (which are not packed in bags or baskets).</div>","alt":[]},"13837":{"h":"מסובריא","r":"M01861","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסוֹכְרָיָא\">מְסוֹכְרָיָא</a></div>","alt":[]},"13838":{"h":"*מְסוּגִין","r":"M01862","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סוּג\">סוּג</a>; cmp. <a href=\"#\" data-headword=\"סְיָג\">סְיָג</a>) <i>low border-marks</i> (v. <a href=\"#\" data-headword=\"מְסִיפָס\">מְסִיפָס</a>). <span class=\"citation\">Y. B. Bath. II, 13ᵇ</span> bot. <span dir=\"rtl\">אילין דעבדין מ׳ וכ׳</span> if partners of a property divide off between one another by means of border-marks (which can easily be stepped over), they may object (to opening a school; v. <span class=\"citation\">Tosef. ib. I, 4</span>).</div>","alt":[]},"13839":{"h":"מַסְוֶה","r":"M01863","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , Ges. Thes., Ges. Thes. p. 941) <i>cover, sheath</i>; <span dir=\"rtl\">מ׳ שבמעדר</span> the (iron) sheath of the ploughshare. <span class=\"citation\">Tosef. Kel. B. Bath. I, 7</span> (R. S. to <span class=\"citation\">Kel. XXI, 2</span> <span dir=\"rtl\">המ׳ שבמעצד</span>). <span class=\"citation\">Erub. 22ᵃ</span> Ms. O., v. <a href=\"#\" data-headword=\"מַשּׂוֹא\">מַשּוֹֹא</a>.</div>","alt":[]},"13840":{"h":"מַסְוִוין","r":"M01864","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַסְוֶה\">preced.</a>) <i>veils, masks</i>. <span class=\"citation\">Lam. R. to IV, 3</span>, v. <a href=\"#\" data-headword=\"יָרוֹד\">יָרוֹדָא</a>.</div>","alt":["מַסְוָון"]},"13841":{"h":"מְסוּטָּף","r":"M01865","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סָטַף\">סָטַף</a></div>","alt":[]},"13842":{"h":"מַסּוֹי","r":"M01866","html":"<div class=\"sense\"><i>load</i>, v. <a href=\"#\" data-headword=\"מַשּׂוֹא\">מַשּוֹֹא</a>.</div>","alt":[]},"13843":{"h":"מסוך","r":"M01867","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 22</span>, beg. <a href=\"#\" data-headword=\"לִימּוּדִים\">למ׳</a>, v. <a href=\"#\" data-headword=\"סְכַךְ\">סְכַךְ</a>.</div>","alt":["מסיך"]},"13844":{"h":"מְסוּכָּן","r":"M01868","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סָכַן II) <i>critically ill.</i> <span class=\"citation\">Gitt. VI, 5</span> <span dir=\"rtl\">אף המ׳</span> the same applies to one taken sick; Y. ib. 48ᵃ, sq. <span dir=\"rtl\">מ׳ כל שקפץ וכ׳</span> <i>m’sukkan</i> is he who was suddenly overcome, contrad. to <a href=\"#\" data-headword=\"חוֹלֶה\">חוֹלֶה</a>. <span class=\"citation\">Ber. 62ᵇ</span> <span dir=\"rtl\">והוא סבר מ׳ הוא</span> and he thought his health was endangered (by a delay); <span class=\"citation\">Tam. 27ᵇ</span> <span dir=\"rtl\">דילמא מ׳ הוא</span>; a. fr.—Fem. <span dir=\"rtl\">מְסוּכֶּנֶת</span>. <span class=\"citation\">Ḥull. II, 6</span> <span dir=\"rtl\">השוחט את המ׳</span> he who slaughters a beast which threatens to die.—[<span class=\"citation\">Midr. Prov. ch. XXII</span> <span dir=\"rtl\">מסוכן בחייו</span>, v. <a href=\"#\" data-headword=\"סָכַן I\"><span dir=\"rtl\">סָכַן</span> I</a>].</div>","alt":[]},"13845":{"h":"מְסוּכְסָךְ","r":"M01869","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִכְסֵךְ I\">סִכְסֵךְ</a></div>","alt":["מְסוּכְסֶכֶת"]},"13846":{"h":"מְסוֹכְרָיָא","r":"M01870","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְכַר I\">סְכַר</a>) <i>stopper</i>. <span class=\"citation\">Sabb. 111ᵃ</span> bot.; <span class=\"citation\">Keth. 6ᵃ</span>; <span class=\"citation\">Bekh. 25ᵃ</span> <span dir=\"rtl\">מ׳ דנזייתא</span> (Ar. s. v. <a href=\"#\" data-headword=\"סְבַר IV\">סבר</a>, a. Ms. M. a. F. Sabb. l. c.: <span dir=\"rtl\">מסוב׳</span></div>","alt":["מְסוֹכְרָיָיא"]},"13847":{"h":"מסוליא","r":"M01871","html":"<div class=\"sense\">, read:</div>","alt":["מסולייא","מסוליים","מסולים"]},"13848":{"h":"מְסוּלְיָיס","r":"M01872","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"סוֹלְיָיס\">סוּלְיָיס</a>) <i>a shoe consisting of a mere sole</i>. <span class=\"citation\">Yeb. 103ᵇ</span> <span dir=\"rtl\">פרט לסנדל המ׳ וכ׳</span> to exclude the sandal which consists merely of a sole and has no heel; <span class=\"citation\">Yalk. Deut. 938</span> <span dir=\"rtl\">מסוליי׳</span>, <span dir=\"rtl\">מוסליי׳</span>; <span class=\"citation\">Kidd. 14ᵃ</span> sq. <span dir=\"rtl\">פרט למסולים</span> (Ar. <span dir=\"rtl\">לסוּלְיָיס</span>).</div>","alt":[]},"13849":{"h":"מסומיס","r":"M01873","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסִימִיס\">מְסִימִיס</a></div>","alt":[]},"13850":{"h":"מְסוּמָּר","r":"M01874","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סָמַר\">סָמַר</a></div>","alt":[]},"13851":{"h":"מָסוֹסָא","r":"M01875","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְסַס\">מְסַס</a>; v. <a href=\"#\" data-headword=\"הֶמְסֵס\">הֶמְסֵס</a>) <i>stomach</i> (of man). <span class=\"citation\">Koh. R. to XII, 4</span> (ref. to <a href=\"#\" data-headword=\"מַחֲנֶה\">מחנה</a>, ib.) <span dir=\"rtl\">ע&quot;י דלית מ׳ טחין</span> because the stomach grinds no more; (<span class=\"citation\">Sabb. 152ᵃ</span> <a href=\"#\" data-headword=\"קוֹרְקְבָן\">קורקבן</a>; <span class=\"citation\">Lev. R. s. 18</span> <a href=\"#\" data-headword=\"הֶמְסֵס\">המסס</a>).</div>","alt":[]},"13852":{"h":"מְסוֹסְטוּלָא","r":"M01876","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (μεσόστυλον, -α) <i>intercolumniation, space between two columns</i>. Y. Ned. III, 37ᵈ bot. <span dir=\"rtl\">אנא חמית … אוּרֵיה על תומני מ׳</span> (not <span dir=\"rtl\">עומני</span>) I saw the tanned slough of a serpent stretched over eight intercolumniations; <span class=\"citation\">Y. Shebu. III, 34ᵈ</span> <span dir=\"rtl\">עיביד על תמניא מסוסטל׳</span>, v. <a href=\"#\" data-headword=\"*אוּרָא II\"><span dir=\"rtl\">אוּרָא</span> II</a>.</div>","alt":[]},"13853":{"h":"מסוסלא","r":"M01877","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מסבסלה\">מסבסלה</a></div>","alt":[]},"13854":{"h":"מסופות","r":"M01878","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Sabb. VIII</span> (<span class=\"citation\">IX), 22</span> ed. Zuck., v. <a href=\"#\" data-headword=\"מְסִיפָס\">מְסִיפָס</a></div>","alt":[]},"13855":{"h":"מַסּוֹקָא","r":"M01879","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסּוֹקִיתָא\">next w.</a></div>","alt":["מסוקיותא"]},"13856":{"h":"מַסּוֹקִיתָא","r":"M01880","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסַק\">נְסַק</a>) <i>ascent, step</i>. <span class=\"citation\">Targ. Y. I Num. XXXIV, 4</span> (some ed. <a href=\"#\" data-headword=\"מַסּוֹקָא\">מסוקיותא</a>; Y. II <span dir=\"rtl\">מַסְקְיוּתָא</span>). <span class=\"citation\">Targ. Is. XV, 5</span>.—Pl. <span dir=\"rtl\">מַסּוֹקְיָין</span>. <span class=\"citation\">Targ. Y. Ex. XX, 23</span>; a. fr.—<span class=\"citation\">Targ. Ps. CXX, 1</span> <span dir=\"rtl\">על מסוקיין דתהומא</span> (ed. Wil. <span dir=\"rtl\">מַסּוֹקִין</span>) on the rise of the depths (v. <span class=\"citation\">Succ. 53ᵃ</span>); ib. CXXI, 1 <a href=\"#\" data-headword=\"מַסִּיקְיָין\">מַסִּיקְיָין</a> ed. Lag.; ib. CXXIII, 1 <a href=\"#\" data-headword=\"מַסִּקְיָין\">מַסִּקְיָין</a> (h. text <span dir=\"rtl\">המעלות</span>).—[<span class=\"citation\">Koh. R. to XII, 5</span> <span dir=\"rtl\">אית תמן מסוקיין</span> (not <a href=\"#\" data-headword=\"מסוריין\">מסוריין</a>) are there any steps to go up?, a Var. lect. inserted in the text; v. <a href=\"#\" data-headword=\"מַסָּקָא\">מַסָּקָא</a>.]</div>","alt":[]},"13857":{"h":"מְסוּקְתָא","r":"M01881","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַסּוֹקִיתָא\">preced.</a>) <i>going up</i>. <span class=\"citation\">Targ. Y. I Deut. XXXII, 49</span>.</div>","alt":[]},"13858":{"h":"מָסוֹר","r":"M01882","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָסַר\">מָסַר</a>) <i>informer, traitor</i> (delivering Jews into the hands of the Roman government). <span class=\"citation\">B. Kam. 119ᵃ</span> <span dir=\"rtl\">ממון מ׳</span> the property of an informer. <span class=\"citation\">Ker. 2ᵇ</span>; <span class=\"citation\">B. Kam. 5ᵃ</span> Ms. M. (ed. <span dir=\"rtl\">מוסר</span>, corr. acc.); a. fr.—Pl. <span dir=\"rtl\">מְסוֹרוֹת</span>. <span class=\"citation\">Y. Sot. IX, end, 24ᶜ</span>, a. e. <span dir=\"rtl\">מפני המ׳</span> (studying Greek was forbidden) on account of the informers (whose familiarity with Greek tempted them to treason, v. Bab. <span class=\"citation\">Sot. 49ᵇ</span>). <span class=\"citation\">R. Hash. 17ᵃ</span> <span dir=\"rtl\">המינין והמ׳</span> (v. Rabb. D. S. a. l. note 50) the heretics and the informers.—<i>Fem</i>. <span dir=\"rtl\">מָסוֹרָה</span>. <span class=\"citation\">Midr. Till. to Ps. XII</span> <span dir=\"rtl\">תהא אומתך מ׳ לך</span> (ed. Bub. <span dir=\"rtl\">אומתיה מסיראה</span>, corr. acc.) may thy own people turn informer against thee; <span class=\"citation\">Yalk. Ps. 656</span> (not <span dir=\"rtl\">אימתך</span>).</div>","alt":[]},"13859":{"h":"מסוריין","r":"M01883","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to XII, 5</span>, read: <a href=\"#\" data-headword=\"מַסִּיקְיָין\">מַסֹּוקְיָין</a>, v. <a href=\"#\" data-headword=\"מַסּוֹקִיתָא\">מַסֹּוקִיתָא</a></div>","alt":[]},"13860":{"h":"מַסּוֹרֶת","r":"M01884","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָסַר\">מָסַר</a>) (<i>a chain of</i>) <i>tradition</i>. <span class=\"citation\">Sot. 10ᵇ</span> <span dir=\"rtl\">דבר זה מ׳ בידינו מאבותינו וכ׳</span> we hold a tradition from our fathers that &amp;c. <span class=\"citation\">Ḥull. 63ᵇ</span> <span dir=\"rtl\">עוף טהור נאכל במ׳</span> as for eating clean birds we rely on tradition (there being no rules for distinguishing them in the Biblical law).—Esp. <i>the traditional Scriptural text without vowels</i>, contrad. to <span dir=\"rtl\">מקרא</span> the traditional vocalization, v. <a href=\"#\" data-headword=\"אֵם\">אֵם</a>. <span class=\"citation\">Y. Meg. IV, 74ᵈ</span> bot. (ref. to <span class=\"citation\">Neh. VIII, 8</span>) ‘they explained the reading’, <span dir=\"rtl\">זה המ׳</span> this means the traditional text; Bab. <span class=\"citation\">Meg. 3ᵃ</span> <span dir=\"rtl\">אלו המסורות</span> (some eds. <a href=\"#\" data-headword=\"מַסּוֹרֶת\">מסורת</a>; v. Rabb. D. S. a. l.); <span class=\"citation\">Ned. 37ᵇ</span> <span dir=\"rtl\">המסורות</span>. <span class=\"citation\">Ab. III, 13</span> <span dir=\"rtl\">מ׳ סייג לתורה</span> the tradition is the fence for (preserving the integrity of) the Torah. <span class=\"citation\">Zeb. 37ᵇ</span>, sq. <span dir=\"rtl\">אהני מקרא ואהני מ׳</span> the traditional vocalization is a help (in interpretation), and so is the traditional literal text (e. g. <span dir=\"rtl\">בסכת</span>, <span class=\"citation\">Lev. XXIII, 42</span>, which may be interpreted as singular number, and which is read as a plural); a. fr.—Pl. <span dir=\"rtl\">מַסֹּורוֹת</span>. Tanḥ. Vaëthḥ. 6 <span dir=\"rtl\">נטלו מ׳ חכמה וכ׳</span> the traditions of wisdom were taken from Moses and given to Joshua.—<span class=\"citation\">Meg. 3ᵃ</span>; <span class=\"citation\">Ned. 37ᵇ</span>, v. supra.—[מַסֹּורָה <i>Massorah</i>, the collection of textual readings systematically arranged.]</div>","alt":[]},"13861":{"h":"מַסֹּורְתָּא","r":"M01885","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job XV, 18</span>. <span class=\"citation\">Targ. Is. XXX, 11</span> <a href=\"#\" data-headword=\"מְסַרְתָּא\">מְסַרְתָּא</a> (Bxt. <a href=\"#\" data-headword=\"מסטונא\">מסטונא</a>, corr. acc.).</div>","alt":[]},"13862":{"h":"מסות","r":"M01886","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Pes. II</span> (<span class=\"citation\">III), 3</span> <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a> ed. Zuck. (Var. <span dir=\"rtl\">המסית</span>, <span dir=\"rtl\">חמסית</span>), read: <a href=\"#\" data-headword=\"חֲרוֹסֶת\">חְרוֹסֶת</a> or pl. <span dir=\"rtl\">חֲרוֹסוֹת</span> (v. <span class=\"citation\">Pes. 40ᵇ</span>).</div>","alt":[]},"13863":{"h":"מְסוּתָא","r":"M01887","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"מַסְחוּתָא\">מַסְחוּתָא</a> q. v.) <i>bath</i>. <span class=\"citation\">Snh. 62ᵇ</span>; <span class=\"citation\">Erub. 27ᵇ</span>, v. <a href=\"#\" data-headword=\"יְבַל\">יְבַל</a>. <span class=\"citation\">B. Mets. 6ᵃ</span>, sq. <span dir=\"rtl\">ההיא מ׳ … מנצו עלה וכ׳</span> (not <a href=\"#\" data-headword=\"עֲלִיָּה\">עליה</a>) there was a bath-house which two contested, one saying, it is mine &amp;c. <span class=\"citation\">Lev. R. s. 28</span>, end [read:] <span dir=\"rtl\">אסר מני מְסוּתֵיה</span> he put on his bathing apparel, v. <a href=\"#\" data-headword=\"זוֹנִיתָא I\">זַוְנִיתָא</a>.</div>","alt":[]},"13864":{"h":"מְסָחָא","r":"M01888","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסַח\">נְסַח</a>) <i>balance</i>, v. <a href=\"#\" data-headword=\"מְסָאתָא\">מְסָאתָא</a>.</div>","alt":[]},"13865":{"h":"מַסְחוּתָא","r":"M01889","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְחֵי\">סְחֵי</a>) <i>bath; bath-house</i>. <span class=\"citation\">Kidd. 33ᵃ</span> <span dir=\"rtl\">הוה יתיב בי מ׳</span> was sitting in the bath-house; v. <a href=\"#\" data-headword=\"מְסוּתָא\">מְסוּתָא</a>.</div>","alt":[]},"13866":{"h":"מַסְחֵיט","r":"M01890","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָחַט\">סָחַט</a>) <i>squeezing appliance, wringer</i>. <span class=\"citation\">Tosef. Kel. B. Mets. VI, 7</span> <span dir=\"rtl\">מ׳ של דלת</span> a wringer on hinges.</div>","alt":[]},"13867":{"h":"מסחייא","r":"M01891","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסַחֲרַיָּא\">מְסַחֲרַיָּא</a></div>","alt":[]},"13868":{"h":"מסחפא","r":"M01892","html":"<div class=\"sense\">, <span class=\"citation\">Targ. I Sam. XVII, 6</span> (Kimḥi in ed. Ven. I <span dir=\"rtl\">מחצפא</span>), read: <span dir=\"rtl\">מַחְסְפָא</span> (v. <a href=\"#\" data-headword=\"חֲסַף I\">חֲסַף</a>) <i>scaly</i>. [The entire clause <span dir=\"rtl\">ומ׳ דנחשא … קולסא</span> is a misplaced and corrupted gloss to verse 5, ref. to <span dir=\"rtl\">ושריון קשקשים</span> of the text, v. <a href=\"#\" data-headword=\"*גַּלְבִּין\">גַּלְבִּין</a> a. <a href=\"#\" data-headword=\"גִּלְדָּא\">גִּלְדָּא</a>.]</div>","alt":[]},"13869":{"h":"מְסַחֲרַיָּא","r":"M01893","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְחַר\">סְחַר</a>; cmp. <a href=\"#\" data-headword=\"אַסְחָרוּתָא\">אַסְחָרוּתָא</a>) <i>feasters, those who feast mourners</i>. Targ. II Esth. I, 2 (3) <span dir=\"rtl\">קברי מ׳</span> ed. Lag. (ed. <a href=\"#\" data-headword=\"מסחייא\">מסחייא</a>, <a href=\"#\" data-headword=\"מסאחייא\">מסאחייא</a>, corr. acc.; ed. Frf. <span dir=\"rtl\">מַרְזְחַיָּיא</span>).</div>","alt":[]},"13870":{"h":"מִסְחֲתָא","r":"M01894","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסַח\">נְסַח</a>) </div><div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"מְסָחָא\">מְסָחָא</a> <i>balance, pair of scales</i>. <span class=\"citation\">Targ. Ps. LXII, 10</span>.—Pl. <span dir=\"rtl\">מִסְחָאתָא</span>. <span class=\"citation\">Targ. Job VI, 2</span> ed. Lag. (ed. Wil. <a href=\"#\" data-headword=\"מִסְחֲתָא\">מְסַחְתָּא</a>). <span class=\"citation\">Ib. XXXI, 6</span> מסאחתא Ms. (corr. acc.; ed. <a href=\"#\" data-headword=\"מְשַׁחְתָּא\">מְשַׁחְתָּא</a>). <span class=\"citation\">Targ. Y. Deut. XXV, 15</span> (not <span dir=\"rtl\">מִסְחַאֲ׳</span>).</div><div class=\"sense\"><b>—2)</b> <i>weighing counter</i>, esp. <i>butcher’s stall</i>. <span class=\"citation\">Ḥull. 132ᵇ</span> <span dir=\"rtl\">קבע מ׳</span> he put up a permanent stall for selling meat. <span class=\"citation\">Shebu. 42ᵃ</span> <span dir=\"rtl\">איתיבת אמ׳ וכ׳</span> you sat by the stall and took your (advanced) money as the meat was being sold. <span class=\"citation\">B. Kam. 23ᵇ</span> <span dir=\"rtl\">תיב אמ׳ וכ׳</span> (sell your animal to the butcher, and) sit by the stall and get your money (v. Rabb. D. S. a. l. note); a. e.</div>","alt":["מְסַחְתָּא"]},"13871":{"h":"מִסְטוֹבָא","r":"M01895","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Ithpe. noun of <span dir=\"rtl\">סבב</span>) = <a href=\"#\" data-headword=\"אִיסטֵיב\">אִיסְטֵיב</a>, <i>porch</i>, esp. <i>dealer’s stall with a bench attached to the house</i>. Y. B. Bath. II, beg. 13ᵇ <span dir=\"rtl\">זבין … ושייר בה חד מ׳</span> sold his dwelling and reserved for himself one porch.</div>","alt":[]},"13872":{"h":"מִסְטוֹבֵיתָא","r":"M01896","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מִסְטוֹבָא\">same</a>. <span class=\"citation\">Cant. R. to VI, 12</span> <span dir=\"rtl\">אין הוא מסתכל לההיא מ׳ וכ׳</span> (not <span dir=\"rtl\">לההוא</span>) if he looks up to that stall where he used to sit tailoring &amp;c.—Pl. <a href=\"#\" data-headword=\"מִסְטוֹבֵיתָא\">מִסְטוֹבְיָיתָא</a>. <span class=\"citation\">Y. Bets. I, 60ᶜ</span> bot. <span dir=\"rtl\">לא … על מ׳ ברייתא וכ׳</span> sit not on the outer benches of the hall of Bar Ula, for they are cold.</div>","alt":["תָה"]},"13873":{"h":"מִסְטָוָוה","r":"M01897","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִיסְטְוָוא</a>, <a href=\"#\" data-headword=\"אִיסְטֵיו\">אִיסְטֵיו</a>). <span class=\"citation\">Y. Kil. IX, 32ᵃ</span> <span dir=\"rtl\">נתון ע&quot;ג מ׳</span> placed on a stationary stone bench, opp. <span dir=\"rtl\">מיטה</span>, couch. <span class=\"citation\">Y. Erub. VII, 24ᵇ</span> bot. <span dir=\"rtl\">עשה מ׳ על פני וכ׳</span> (not <span dir=\"rtl\">עשרה</span>) if he attached a porch along the whole front of the wall.—Pl. <span dir=\"rtl\">מִסְטְוָיוֹת</span>. <span class=\"citation\">Y. Pes. V, 32ᶜ</span> bot. <span dir=\"rtl\">מ׳ היו עושין להון</span> they made for them projecting boards (along the wall, that they should not step on the blood; Bab. <span class=\"citation\">Pes. 65ᵇ</span> <span dir=\"rtl\">דמסגי אאיצטבי</span>, v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִיסְטְבָא</a>).</div>","alt":[]},"13874":{"h":"מסטונא","r":"M01898","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Is. XXX, 11</span> Bxt. Lex. p. 1462, a corrupt., v. <a href=\"#\" data-headword=\"מַסֹּורְתָּא\">מַסֹּורְתָּא</a></div>","alt":[]},"13875":{"h":"מִסְטוֹר","r":"M01899","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָטַר\">סָטַר</a>) <i>a blow, slap</i>. Tanḥ. Ḥayé 3 <span dir=\"rtl\">סטרו מ׳</span> he slapped him in the face; a. e.; v. <a href=\"#\" data-headword=\"מִסְטר\">מִסְטָר</a>.—Pl. <a href=\"#\" data-headword=\"מִסְטוּרִין\">מִסְטוֹרִין</a>. <span class=\"citation\">Yalk. Koh. 968</span> (play on <a href=\"#\" data-headword=\"אַף I\">אף</a>, <span class=\"citation\">Koh. II, 9</span>) <span dir=\"rtl\">תורה שלמדתי באף נתקיימה לי … שלמדתי במ׳ היא עמדה לי</span> the lesson which I learned with ‘heat’ remained to me; … the very lesson which I learned with (my teachers’) slaps stood by me; Koh. R. to l. c. <span dir=\"rtl\">כל תורה שלמדתי בזקנתי פסטירין באף נתקיימה לי</span> (corr. acc.; v. Matt. K. a. l.).</div>","alt":[]},"13876":{"h":"מִסְטוּרִין","r":"M01900","html":"<div class=\"sense\"><i>secret</i>, v. <a href=\"#\" data-headword=\"מִסְטֵירִין\">מִסְטֵירִין</a>.</div>","alt":[]},"13877":{"h":"מַסְטֵי","r":"M01901","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְטֵי\">סְטֵי</a>) <i>one who diverts judgment from its straight path</i> (= h. <span dir=\"rtl\">מַטֵּה דִין</span>), <i>prevaricator</i>. <span class=\"citation\">Targ. Is. LVIII, 6</span> <span dir=\"rtl\">דין מ׳</span> (h. text <a href=\"#\" data-headword=\"מוֹטָה\">מוֹטָה</a>).—<span class=\"citation\">Gen. R. s. 50</span> (fictitious name of a Sodomite judge) <span dir=\"rtl\">רב מַסְטֵידִין</span> (= <a href=\"#\" data-headword=\"מַסְטֵידִין\">מַסְטֵי דין</a>, some ed. <a href=\"#\" data-headword=\"מִסְטֵירִין\">מסטירין</a>, corr. acc.) Chief Prevaricator (<span class=\"citation\">Snh. 109ᵇ</span> <span dir=\"rtl\">מצלי דינא</span>); Yalk. ib. 84 (corr. acc.).</div>","alt":[]},"13878":{"h":"מַסְטֵידִין","r":"M01902","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסְטֵי\">preced.</a></div>","alt":[]},"13879":{"h":"מַסְטִיכִי","r":"M01903","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (μαστίχη) <i>gum mastic</i>. <span class=\"citation\">Gen. R. s. 91</span> end; <span class=\"citation\">Yalk. Gen. 149</span> (expl. <a href=\"#\" data-headword=\"לָט\">לֹט</a>, <span class=\"citation\">Gen. XLIII, 11</span>; ed. <span dir=\"rtl\">מצטוכא</span>, <a href=\"#\" data-headword=\"מוצטבה\">מוצטבה</a>, <span dir=\"rtl\">מוצטכ׳</span> corr. acc.). <span class=\"citation\">Tosef. Sabb. XII</span> (<span class=\"citation\">XIII), 8</span>, v. <a href=\"#\" data-headword=\"לָעַס\">לָעַס</a>.</div>","alt":[]},"13880":{"h":"מסטירים","r":"M01904","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְטֵירִין\">next w.</a></div>","alt":[]},"13881":{"h":"מִסְטֵירִין","r":"M01905","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> sing. a. pl. (μυστήριον, -α) <i>secret</i>. <span class=\"citation\">Midr. Till. to Ps. IX, 6</span> <span dir=\"rtl\">מיסטורין זה אני וכ׳</span> ed. Bub. (ed. <a href=\"#\" data-headword=\"מִסְתּוֹרִין\">מסתורין</a>, corr. acc.) this secret I reveal to thee. <span class=\"citation\">Gen. R. s. 50</span>; s. 68 <span dir=\"rtl\">ע&quot;י שגלו מ׳ וכ׳</span> because they revealed the mysteries of the Lord (<span class=\"citation\">Gen. XIX, 13</span>); Yalk. ib. 84 <a href=\"#\" data-headword=\"מִסְתּוֹרִין\">מסתורין</a>. <span class=\"citation\">Gen. R. s. 71</span> <span dir=\"rtl\">בעלי מ׳</span> secret-keeping, discreet men. <span class=\"citation\">Gen. R. s. 98</span>; Tanḥ. Vayḥi 8; <span class=\"citation\">Pesik. R. s. 21</span> <a href=\"#\" data-headword=\"מסטירים\">מסטירים</a> (corr. acc.). <span class=\"citation\">Y. Gitt. II, 44ᵇ</span> top <span dir=\"rtl\">כתב מ׳</span> a secret letter; (<span class=\"citation\">Y. Sabb. XII, end, 13ᵈ</span> <span dir=\"rtl\">מילה מסטריקון</span>); a. fr.—<span class=\"citation\">Targ. Y. I Gen. XXVIII, 12</span> <a href=\"#\" data-headword=\"מִסְטֵירִין\">מַסְטִירִין</a> (some ed. <span dir=\"rtl\">מַסְתִּי׳</span>, corr. acc.). <span class=\"citation\">Targ. Y. Num. XVI, 26</span> <a href=\"#\" data-headword=\"מִסְטְרִין\">מְסַטְּרִין</a> (some ed. <a href=\"#\" data-headword=\"מִסְטְרִין\">מַסְטְרִין</a>, corr. acc.).—[<span class=\"citation\">Gen. R. s. 50</span>; <span class=\"citation\">Yalk. ib. 84</span>, v. <a href=\"#\" data-headword=\"מַסְטֵי\">מַסְטֵי</a>.]</div>","alt":["מִסְטוּ׳","מִיסְ׳"]},"13882":{"h":"מִסְטר","r":"M01906","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָטַר\">סָטַר</a>) <i>slap in the face</i>. <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">סטרו מ׳</span>, <span dir=\"rtl\">סטרן מ׳</span>, v. <a href=\"#\" data-headword=\"מִסְטוֹר\">מִסְטוֹר</a>. <span class=\"citation\">Num. R. s. 20</span>, end <span dir=\"rtl\">נתן מִשְׂטָר אחד וכ׳</span> he slapped one of the boys; (Tanḥ. ed. Bub. Balak 30, note 175 <a href=\"#\" data-headword=\"מִסְטר\">מסטר</a>).—V. <a href=\"#\" data-headword=\"מִסְטוֹר\">מִסְטוֹר</a>.</div>","alt":[]},"13883":{"h":"מִסְטְרִין","r":"M01907","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְטֵירִין\">מִסְטֵירִין</a></div>","alt":["(מַסְטְ׳","מְסַטְּ׳)"]},"13884":{"h":"מִסְטְרִיקוֹן","r":"M01908","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μυστηρικόν) <i>of a secret nature</i>. <span class=\"citation\">Y. Sabb. XII, end, 13ᵈ</span>, v. <a href=\"#\" data-headword=\"מִסְטֵירִין\">מִסְטֵירִין</a>.</div>","alt":[]},"13885":{"h":"מסטרני","r":"M01909","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מגיסטריני\">מגיסטריני</a></div>","alt":[]},"13886":{"h":"מסי","r":"M01910","html":"<div class=\"sense\"> (b. h.) <i>to melt, flow; to cause running off, effect curdling</i>. <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 25</span> <span dir=\"rtl\">שלא יִמְסֶה</span> that the manna might not melt.—Denom. <a href=\"#\" data-headword=\"מְסוֹ\">מְסוֹ</a>.</div><div class=\"sense\"><b>Hif. הִמְסָה</b> <div class=\"sense\"><i>to cause to flow</i>. <span class=\"citation\">Midr. Till. to Ps. VI, 7</span> <span dir=\"rtl\">התחיל בוכה ומַמְסֶה מטתו וכ׳</span> ed. Bub. (ed. <span dir=\"rtl\">וממחה</span>) he began to weep and make his bed flow with (his) tears; <span class=\"citation\">Yalk. Ps. 636</span>.</div></div><div class=\"sense\"><b>Pi. מִסָּה</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"מסטרני\">same</a>, <i>to dissolve, weaken</i>. <span class=\"citation\">Deut. R. s. 7</span> (play on <a href=\"#\" data-headword=\"מסות\">מַסּוֹת</a>, <span class=\"citation\">Deut. XXIX, 2</span>) <span dir=\"rtl\">המכות מְמַסּוֹת גופיהן וכ׳</span> the plagues weakened the bodies of the Egyptians; Yalk. ib. 940.</div></div><div class=\"sense\"><b>Nif. נִמְסָה</b> <div class=\"sense\"><i>to be melted, to fall away</i>. <span class=\"citation\">Tosef. Sot. III, 4</span> <span dir=\"rtl\">ירכה נִמְסֵית</span> her thigh will fall away.</div></div>","alt":["מָסָה"]},"13887":{"h":"מְסֵי","r":"M01911","html":"<div class=\"sense\">, <i>to flow, melt away</i>. <span class=\"citation\">Targ. II Sam. XVII, 10</span> <span dir=\"rtl\">מִמַס יִמְסֵי</span> (ed. Wil. <span dir=\"rtl\">יַמְסֵי</span> <i>Af</i>.), v. <a href=\"#\" data-headword=\"מְסַס\">מְסַס</a>.—Part. <a href=\"#\" data-headword=\"מְסֵי\">מָסֵי</a>, f. <a href=\"#\" data-headword=\"מַסְּיָא\">מַסְיָא</a>. <span class=\"citation\">Targ. O. Num. V, 21</span> (ed. Vienna <a href=\"#\" data-headword=\"מַסְּיָא\">מַסְּיָא</a> = <span dir=\"rtl\">מְמַסְּיָא</span>, v. infra).</div><div class=\"sense\"><b>Pa. מַסֵּי</b> <div class=\"sense\"><i>to cause melting, falling away</i>. <span class=\"citation\">Targ. Ps. XXXIX, 12</span> <a href=\"#\" data-headword=\"מַסְּיָא\">מַסְּיַת</a>. <span class=\"citation\">Targ. Y. Num. V, 22</span> <span dir=\"rtl\">למַסְיָא</span> = <span dir=\"rtl\">למְמַסְיָא</span>.—Part. pass. <a href=\"#\" data-headword=\"מְאַסָּא\">מְמַסָּא</a>, <span dir=\"rtl\">מְמַסֵּי</span>, f. (<span dir=\"rtl\">מְ</span>)<a href=\"#\" data-headword=\"מַסְּיָא\">מַסְּיָא</a>, v. supra. <span class=\"citation\">Pes. 28ᵃ</span> Rashi <span dir=\"rtl\">לא מְמַסָּה</span> is not dissolved in water, v. <a href=\"#\" data-headword=\"מְאִיס\">מְאִיס</a>.</div></div><div class=\"sense\"><b>Af. אַמְסֵי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"מסי\">same</a>. Targ. O. Num. l. c.; a. e.—Targ. II Sam. l. c., v. supra.</div></div><div class=\"sense\"><b>Ithpe. אִתְמְסִי</b> <div class=\"sense\"><i>to be melted, fall away</i>. <span class=\"citation\">Targ. Num. V, 27</span>. <span class=\"citation\">Targ. O. Lev. XXVI, 39</span> (v. <a href=\"#\" data-headword=\"יְמַס\">יְמַס</a>); a. fr.—<span class=\"citation\">Targ. Y. Gen. VII, 21</span> <span dir=\"rtl\">אִתְהַמְסִי</span> (not <span dir=\"rtl\">אתח׳</span>; h. text <span dir=\"rtl\">ויגוע</span>).</div></div><div class=\"sense\"><b>Ittaf. אִיתִּימְסִי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"מסי\">same</a>. <span class=\"citation\">Targ. Ps. LXXVIII, 6</span> Ms., v. <a href=\"#\" data-headword=\"מְאִיס\">מְאִיס</a>. <span class=\"citation\">Ib. LXVIII, 3</span> Ms. (ed. <i>Ithpe.</i>); a. fr. (in Ms.).</div></div>","alt":["מְסָא"]},"13888":{"h":"מַסֵּי","r":"M01912","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲסִי\">אֲסִי</a></div>","alt":["מַסֵּיָין"]},"13889":{"h":"מסיא","r":"M01913","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Is. III, 20</span> ed. Lag., v. <a href=\"#\" data-headword=\"מַזְיָא\">מַזְיָא</a></div>","alt":[]},"13890":{"h":"מַסְּיָא","r":"M01914","html":"<div class=\"sense\"> = <span dir=\"rtl\">מְמַסְּיָא</span>, v. <a href=\"#\" data-headword=\"מְסֵי\">מְסֵי</a></div>","alt":[]},"13891":{"h":"מְסִיב","r":"M01915","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Gen. IV, 8</span> <span dir=\"rtl\">מ׳ אפין</span> some ed., read: <a href=\"#\" data-headword=\"מִיסַּב\">מִיסַּב</a>.</div>","alt":[]},"13892":{"h":"מְסִיבָּה","r":"M01916","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">מְסִבּ׳</span>.</div>","alt":["מְסִיבְּתָא"]},"13893":{"h":"מְסִיָּיה","r":"M01917","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָסָה\">מָסָה</a>) <i>melting, losing courage</i>. <span class=\"citation\">Yalk. Ex. 251</span>; (Mekh. B’shall., Shir. s. 9 <a href=\"#\" data-headword=\"נְמִיסָה\">נְמִיסָה</a>).</div>","alt":[]},"13894":{"h":"מסייפא","r":"M01918","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְפְּיָיא\">מִסְפְּיָיא</a></div>","alt":[]},"13895":{"h":"מסיך","r":"M01919","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מסוך\">מסוך</a></div>","alt":[]},"13896":{"h":"*מְסִיכָּה","r":"M01920","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָכַךְ I\">סָכַךְ</a>, <i>Hif.</i> <span dir=\"rtl\">הסך את רגליו</span>) <i>easing one’s bowels</i>. <span class=\"citation\">Y. Yoma III, 40ᵇ</span> bot. <a href=\"#\" data-headword=\"סְמִיכָה\">סמיכה</a> (corr. acc.), v. <a href=\"#\" data-headword=\"הֶפְלֵג\">הֶפְלֵג</a>.</div>","alt":[]},"13897":{"h":"מְסִילָּה","r":"M01921","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>path, road</i>. <span class=\"citation\">Yalk. Deut. 907</span>, v. <a href=\"#\" data-headword=\"מִיל\">מִיל</a>.—Pl. <a href=\"#\" data-headword=\"מְצִילָּה\">מְסִילּוֹת</a>, <span dir=\"rtl\">מְסִלּ׳</span>. <span class=\"citation\">Ber. 59ᵇ</span>; <span class=\"citation\">Lev. R. s. 23</span> <span dir=\"rtl\">ככבים במְסִלּוֹתָם</span> the planets on re-entering their periodical orbits.</div>","alt":["מְסִלָּה"]},"13898":{"h":"מְסִימִיס","r":"M01922","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a popular corruption of semissis) <i>semissis</i>, a Roman value, equal to half an as or six ounces. <span class=\"citation\">Tosef. B. Bath. V, 12</span> <span dir=\"rtl\">מי׳ שני קונטרונין</span> a semissis is equal to two quadrantes; <span class=\"citation\">Kidd. 12ᵃ</span> <span dir=\"rtl\">מסמס שני קוטרונקין</span>; Y. ib. I, 58ᵈ <span dir=\"rtl\">שני קרדיונטס מסי׳</span>.—Pl. <span dir=\"rtl\">מְסִימִיסִין</span>, <span dir=\"rtl\">מִיסְמְסִין</span>, <span dir=\"rtl\">מוּסְמִיסִין</span>. Tosef. l. c. <span dir=\"rtl\">איסר שני מיס׳</span> an as has two semisses; Kidd. l. c. <span dir=\"rtl\">מוסמי׳</span>; Y. l. c. <span dir=\"rtl\">מסומיסין</span>.</div>","alt":["(מִיסְמֵס","מוּסְ׳)"]},"13899":{"h":"מסימס","r":"M01923","html":"<div class=\"sense\">, a species of <i>wood</i>, v. <a href=\"#\" data-headword=\"מִסְמֵס III\"><span dir=\"rtl\">מִסְמֵס</span> III</a>.</div>","alt":[]},"13900":{"h":"מְסִימְתָּא","r":"M01924","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסַמְתָּא\">מְסַמְתָּא</a></div>","alt":[]},"13901":{"h":"מסיע","r":"M01925","html":"<div class=\"sense\">, <span class=\"citation\">Y. Taan. IV, beg., 67ᵇ</span>, v. <a href=\"#\" data-headword=\"הֶסֵּיעַ\">הֶסֵּיעַ</a></div>","alt":[]},"13902":{"h":"מְסִיפָס","r":"M01926","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">מסיפסף</span>; <a href=\"#\" data-headword=\"סוּף\">סוּף</a>; cmp. <a href=\"#\" data-headword=\"פְּסִיפָּס\">פְּסִיפָּס</a>, <a href=\"#\" data-headword=\"פִּסְפָּס\">פִּסְפָּס</a> with which our w. interchanges) <i>border-mark, partition consisting of wooden or stone pegs</i>, contrad. to <a href=\"#\" data-headword=\"מְחִיצָה I\">מחיצה</a> or <a href=\"#\" data-headword=\"כּוֹתָל\">כותל</a> partition wall. <span class=\"citation\">Erub. 72ᵃ</span> (Ms. O. twice <span dir=\"rtl\">פסיפס</span>, v. Rabb. D. S. a. l. note 10), opp. to <span dir=\"rtl\">מחיצה עשרה</span> a partition ten hand-breadths high. <span class=\"citation\">B. Bath. 2ᵇ</span> <span dir=\"rtl\">במ׳ בעלמא</span> (Ms. M. <span dir=\"rtl\">בפְסִיסִין</span>, v. Rabb. D. S. a. l. note) where there are only pegs as border marks, opp. <a href=\"#\" data-headword=\"כּוֹתָל\">כותל</a>. Ib. bot. <span dir=\"rtl\">במ׳</span> (Ms. M. <span dir=\"rtl\">פס׳</span>, emended <span dir=\"rtl\">מס׳</span>). <span class=\"citation\">Ab. Zar. 70ᵇ</span>; Y. ib. V, 44ᵈ bot. <span dir=\"rtl\">חצר החלוקה במ׳</span> a court which is divided off by mere marks (cmp. <a href=\"#\" data-headword=\"*מְסוּגִין\">מְסוּגִין</a>). <span class=\"citation\">Tosef. Sabb. VIII</span> (<span class=\"citation\">IX), 22</span> [read:] <span dir=\"rtl\">כדי לעשותו מ׳</span>) Var. ed. Zuck. (ed. <a href=\"#\" data-headword=\"מסופות\">מסופות</a>) large enough to be used for a marking peg.—Pl. <span dir=\"rtl\">מְסִיפְסִין</span>. <span class=\"citation\">Yalk. Ex. 422</span> [read:] <span dir=\"rtl\">כמין מ׳ היו עשויות מלמעלה</span> a sort of marks were on top (to distinguish between the Holy and the Holy of Holies; ib. 370 <span dir=\"rtl\">כמין פספסין היה וכ׳</span>).</div>","alt":[]},"13903":{"h":"מָסִיק","r":"M01927","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָסַק\">מָסַק</a>) <i>olive harvest</i>. <span class=\"citation\">Y. B. Bath. III, 14ᵃ</span> top, v. <a href=\"#\" data-headword=\"בָּצִיר I\"><span dir=\"rtl\">בָּצִיר</span> I</a>. <span class=\"citation\">Ḥall. III, 9</span> <span dir=\"rtl\">זיתי מ׳</span> olives collected at the regular harvest, opp. <span dir=\"rtl\">זיתי ניקוף</span> gleanings (v. <a href=\"#\" data-headword=\"נִיקּוּף ²\"><span dir=\"rtl\">נִיקּוּף</span> II</a>); <span class=\"citation\">Y. Maasr. V, 51ᵈ</span> top (not <a href=\"#\" data-headword=\"מיסיק\">מיסיק</a>). <span class=\"citation\">Y. Yeb. XV, 14ᵈ</span> <span dir=\"rtl\">יצא בציר ונכנס מ׳</span> when the grape-cutting is over, the olive-harvest begins; a. e.—V. <a href=\"#\" data-headword=\"מְסִיקָה\">מְסִיקָה</a>.</div>","alt":[]},"13904":{"h":"מַסֵּיק","r":"M01928","html":"<div class=\"sense\">, part. <i>Af</i>. of <a href=\"#\" data-headword=\"נְסַק\">נְסַק</a>.</div>","alt":[]},"13905":{"h":"מַסִּיק I","r":"M01929","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָסַק\">נָסַק</a>) <i>reaching definite conclusions, decided</i>. <span class=\"citation\">Hor. 14ᵃ</span>, v. <a href=\"#\" data-headword=\"מַקְשֶׁה\">מַקְשֶׁה</a>.—V. <a href=\"#\" data-headword=\"נְסַק\">נְסַק</a>.</div>","alt":[]},"13906":{"h":"מַסִּיק II","r":"M01930","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָסַק\">נָסַק</a>; sub. <a href=\"#\" data-headword=\"מִיסִּים\">מִסִּים</a> &amp;c.) <i>one who levies contributions</i>, in gen. <i>a Roman collector, oppressor</i> (interch. with <a href=\"#\" data-headword=\"מֵצִיק\">מֵצִיק</a>). <span class=\"citation\">Tosef. Ohol. XVI, 13</span> (ed. Zuck. <a href=\"#\" data-headword=\"מֵצִיק\">מציק</a>); <span class=\"citation\">Y. Pes. I, 27ᶜ</span>; (Bab. <span class=\"citation\">ib. 9ᵃ</span>, a. <span class=\"citation\">Ab. Zar. 42ᵃ</span> <span dir=\"rtl\">מצ׳</span>).—Pl. <span dir=\"rtl\">מַסִּיקִין</span>. <span class=\"citation\">B. Kam. X, 5</span> <span dir=\"rtl\">ונטלוהו מ׳</span> and government officers confiscated it. <span class=\"citation\">Ib. 116ᵇ</span> <span dir=\"rtl\">מאן דאמר מס׳ … מצ׳ וכ׳</span> he who reads <i>massiḳin</i> is not at fault, nor is he who reads <i>m’tsikin</i> (ref. for the latter to <span dir=\"rtl\">מצוק</span>, <span class=\"citation\">Deut. XXVIII, 57</span>, for the former to Chald. <a href=\"#\" data-headword=\"סַקָּאָה\">סקאה</a> for <span dir=\"rtl\">צלצל</span>, <span class=\"citation\">ib. 42</span>). <span class=\"citation\">Y. Sabb. XVI, end, 15ᵈ</span> <span dir=\"rtl\">סופך לעשות במ׳</span> thou shalt be forced by the officers.—<span class=\"citation\">Y. Dem. VI, 25ᵇ</span> <span dir=\"rtl\">מן המ׳ שנו</span> it means that he rented the field from the officers (who had confiscated it).</div>","alt":[]},"13907":{"h":"מַסִּיקָא","r":"M01931","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">מַסִּיקַיָּא</span>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 42</span> (h. text <span dir=\"rtl\">צלצל</span>, v. <span class=\"citation\">B. Kam. 116ᵇ</span> quot. in <a href=\"#\" data-headword=\"מַסִּיק II\">preced.</a>).</div>","alt":[]},"13908":{"h":"מְסִיקָה","r":"M01932","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"מָסִיק\">מָסִיק</a>. <span class=\"citation\">Sabb. 17ᵃ</span>.—Pl. <span dir=\"rtl\">מְסִיקוֹת</span>. <span class=\"citation\">B. Bath. 36ᵇ</span> <span dir=\"rtl\">שלש מ׳</span> three olive-crops.</div>","alt":[]},"13909":{"h":"מַסִּיקְיָין","r":"M01933","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסּוֹקִיתָא\">מַסּוֹקִיתָא</a></div>","alt":[]},"13910":{"h":"מְסִירָה","r":"M01934","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָסַר\">מָסַר</a>) </div><div class=\"sense\"><b>1)</b> <i>harnessing, taking possession of a working animal by an act resembling harnessing</i>. <span class=\"citation\">Kidd. I, 4</span>, v. <a href=\"#\" data-headword=\"מוֹסֵרָה\">מוֹסֵרָה</a>. <span class=\"citation\">Tosef. ib. I, 8</span> <span dir=\"rtl\">איזו היא מ׳ מסר לו … ומוֹסִירָהּ</span> (ed. Zuck. <span dir=\"rtl\">ומוסֵירה</span>, Var. <span dir=\"rtl\">במוסרה</span>) what is <i>m’sirah?</i> He (the seller) hands him (the buyer) a bit and he harnesses it (the animal); <span class=\"citation\">Kidd. 22ᵇ</span> <span dir=\"rtl\">כיצד במ׳ אחזה וכ׳</span> what is <i>bimsirah</i> (<span class=\"citation\">Kidd. I, 4</span>)? He seizes its hoof, hair &amp;c., a. fr.</div><div class=\"sense\"><b>—2)</b> <i>handing, delivery</i>. <span class=\"citation\">Gitt. 9ᵇ</span>, a. fr. <span dir=\"rtl\">עדי מ׳</span>, v. <a href=\"#\" data-headword=\"כְּרַת\">כְּרַת</a>; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>levy</i>. <span class=\"citation\">Cant. R. to IV, 4</span> (ref. to <span class=\"citation\">Num. XXXI, 5</span>) <span dir=\"rtl\">שנים … במ׳</span> twelve thousand men were raised by levy, opp. <span dir=\"rtl\">בנדבה</span> as volunteers.</div>","alt":[]},"13911":{"h":"מְסִירִין","r":"M01935","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָרַר\">סִרַר</a>) <i>rebels</i>, v. <a href=\"#\" data-headword=\"מְסַרְבָּן\">מְסַרְבָּן</a>.</div>","alt":[]},"13912":{"h":"מֵסִית","r":"M01936","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*יָסַת\">יָסַת</a></div>","alt":["מַסִּית"]},"13913":{"h":"מֵסֵית","r":"M01937","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָתַת\">סָתַת</a>) <i>stone-cutter</i>. Pesik. S’liḥ., p. 166ᵃ; Yalk. Num. 744, v. <a href=\"#\" data-headword=\"גָּשַׁשׁ\">גָּשַׁשׁ</a>.</div>","alt":[]},"13914":{"h":"מָסַךְ I","r":"M01938","html":"<div class=\"sense\"><i>to temper, mix wine</i> (cmp. <a href=\"#\" data-headword=\"מָזַג\">מָזַג</a>). <span class=\"citation\">Ab. Zar. 58ᵇ</span>, v. <a href=\"#\" data-headword=\"מָזַג\">מָזַג</a>. <span class=\"citation\">Num. R. s. 10</span> יין מָסְכָה וכ׳ Eve mixed wine for Adam. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">היו מוֹסְכִים יין וכ׳</span> they mixed strong with light wine; a. e.</div>","alt":[]},"13915":{"h":"מָסַךְ II","r":"M01939","html":"<div class=\"sense\"><i>to cast</i> (<i>metal</i>). <span class=\"citation\">Y. Ber. I, 2ᵈ</span> top; <span class=\"citation\">Gen. R. s. 12</span>, end <span dir=\"rtl\">מוֹסֵךְ</span> Ar. (ed. Y. Ber. <span dir=\"rtl\">נוֹסֵךְ</span>; Gen. R. <span dir=\"rtl\">מוֹצֵק</span>), v. <a href=\"#\" data-headword=\"בּוּלָס\">בּוּלָס</a>.—[<span class=\"citation\">Yalk. Ex. 165</span> <span dir=\"rtl\">ממסכת</span>, read <a href=\"#\" data-headword=\"מַסֶּכֶת\">מֵסֶכֶת</a>, v. <a href=\"#\" data-headword=\"סוּךְ\">סוּךְ</a>.]</div>","alt":[]},"13916":{"h":"מֶסֶךְ","r":"M01940","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> סָכַךְ II <i>to be clear</i>; cmp. <span dir=\"rtl\">מוג</span>) <i>clarified, mixed drink</i>. <span class=\"citation\">Ex. R. s. 42</span>, end (play on <span dir=\"rtl\">מ̇ס̇כ̇ה̇</span>, <span class=\"citation\">Ex. XXXII, 8</span>) <span dir=\"rtl\">ק&quot;כ קנטרוין מנין מ̇ס̇&quot;ך̇ שהוא מעכיר ה׳</span> the gold in the calf weighed 120 centenaria, corresponding to the numerical value of <i>mesekh</i> (drink) which removes Hé (the Lord, i.e. leads to godlessness).</div>","alt":[]},"13917":{"h":"מָסָךְ","r":"M01941","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>web, screen, curtain</i>. <span class=\"citation\">Num. R. s. 6</span> <span dir=\"rtl\">מָסַךְ שער וכ׳</span> the curtain for the gate of the court. <span class=\"citation\">Yalk. Ex. 372</span>; a. e.</div>","alt":[]},"13918":{"h":"מִסְכָא","r":"M01942","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 96ᵇ</span>, v. <span dir=\"rtl\">נִסְכָּא III</span></div>","alt":[]},"13919":{"h":"מַסֵּכָה I","r":"M01943","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>molten image</i>. <span class=\"citation\">Snh. 103ᵇ</span> (play on <span class=\"citation\">Is. XXVIII, 20</span> <span dir=\"rtl\">והמסכה וכ׳</span>) <span dir=\"rtl\">כונס כנד מי הים תֵּעָשֶה לו מ׳ צרה</span> should a molten image be made a rival to him ‘who gathers the waters of the sea together like heaps’?; <span class=\"citation\">Num. R. s. 7</span>; <span class=\"citation\">Yoma 9ᵇ</span>. Sifra K’dosh., beg. (idols are called) <span dir=\"rtl\">מ׳ ע&quot;ש שהם ניסוכים</span> <i>massekhah</i>, because they are cast.</div>","alt":[]},"13920":{"h":"מַסֵּכָה II","r":"M01944","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>web, garment</i>. <span class=\"citation\">Ex. R. s. 42</span>, end (ref. to <span class=\"citation\">Ex. XXXII, 8</span>) <span dir=\"rtl\">מ׳ רעה הֵסַכְתֶּן לדורות משתי וכ׳</span> a bad web have you woven for future generations (follows the Chaldaic translation).—V. <a href=\"#\" data-headword=\"מַסֶּכֶת\">מַסֶּכֶת</a>.</div>","alt":[]},"13921":{"h":"*מַסֵּכָה III","r":"M01945","html":"<div class=\"sense\"> (homiletic play, = <span dir=\"rtl\">מַסֵּי כָה</span>, v. <a href=\"#\" data-headword=\"אֲסִי\">אֲסִי</a>) <i>thus healing</i>. <span class=\"citation\">Ex. R. s. 42</span>, end [read:] <span dir=\"rtl\">לשון סורסי הוא … כך אני מרפא אותן וכ׳</span> (v. <a href=\"#\" data-headword=\"סוּרְסִי\">סוּרְסִי</a>) it is a contraction; the Lord says, ‘Shall I thus cure them?’, as we read (<span class=\"citation\">Ex. XXXII, 8—9</span>): ‘They have made themselves a molten calf’ … ‘and the Lord said unto Moses, I have seen this people, and behold, it is a stiffnecked people’ (i.e. it is incurable).</div>","alt":[]},"13922":{"h":"מִסְכֵּין","r":"M01946","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְכֵּן\">מִסְכֵּן</a>, <a href=\"#\" data-headword=\"מִסְכֵּן\"><a href=\"#\" data-headword=\"מִסְכֵּן\">מִסְכֵּנ׳</a>.</a></div>","alt":["מִסְכֵּינָא","מַסְכֵּינוּ","מִסְכֵּינוּתָא"]},"13923":{"h":"*מִסְכָּן","r":"M01947","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִסְכֵּן I\">next w.</a>) <i>poverty</i>. <span class=\"citation\">Cant. R. to I, 4</span> (interpreting <span dir=\"rtl\">מַסְכְּנֵנִי</span>, v. <a href=\"#\" data-headword=\"מִסְכֵּן II\"><span dir=\"rtl\">מִסְכֵּן</span> II</a>; strike out <span dir=\"rtl\">דבר אחר</span>) <span dir=\"rtl\">ממִסְכָּנִי אחריך נרוצה</span> out of my poverty, we shall run after thee.</div>","alt":[]},"13924":{"h":"מִסְכֵּן I","r":"M01948","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>poor man;</i> (adj.) <i>scanty, scarce;</i> trnsf. <i>mean</i>. <span class=\"citation\">Midr. Prov. ch. XXII</span> <span dir=\"rtl\">מ׳ שהוא מְסוּכָּן בחייו</span> the poor man is called <i>misken</i>, because he is sparsely supplied with means of livelihood; <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">מפני שהוא בזוי לכל</span> he is called <i>misken</i>, because he is despised of all men (ref. to <span class=\"citation\">Koh. IX, 16</span>). <span class=\"citation\">Ruth R. to I, 1</span> (ref. to Koh. l. c.) <span dir=\"rtl\">וכי חכמתו של ר&quot;ע שהיה מ׳ בזויה היתה אלא מהו מ׳ מי שהוא בזוי בדבריו וכ׳</span> was the wisdom of R. Akiba who was a poor man despised? But what does <i>misken</i> here mean? One who proves himself mean by his own words (not practicing what he preaches); Koh. R. to l. c. [read:] <span dir=\"rtl\">אלא זה שהוא מ׳ בדבריו</span>; <span class=\"citation\">Yalk. Ruth 598</span> <span dir=\"rtl\">אלא ההוא דמ׳ בדבריו בזויה</span> (insert <span dir=\"rtl\">חכמתו</span>). Koh. R. l. c. <span dir=\"rtl\">אין מ׳ אלא מי שמְמַסְכֵּין דבריו</span> (not <span dir=\"rtl\">שמסכין</span>) behold, a <i>misken</i> is none but he who makes his words appear mean. Ib. to IX, 15 <span dir=\"rtl\">ולמה קורא אותו מ׳ שאינו מצוי בכל הבריות ואין וכ׳</span> and why does the text call him (the good genius in man) <i>misken</i> (scarce)? Because he is rare among men, and (<i>mean</i>) because the majority of people do not listen to him; ib. to IV, 13; a. fr.—Yalk. ib. 979; Y’lamd. to Num. XXIV, 5 quot. in Ar. <span dir=\"rtl\">שמ׳ מדברי תורה</span>, read: <span dir=\"rtl\">שמ׳ בדבריו</span>, v. supra.—Denom.</div>","alt":[]},"13925":{"h":"מִסְכֵּן II","r":"M01949","html":"<div class=\"sense\"><i>to make poor, make contemptible</i>. <span class=\"citation\">Koh. R. to IX, 16</span>, v. <a href=\"#\" data-headword=\"מִסְכֵּן I\">preced.</a> <span class=\"citation\">Ex. R. s. 1</span>; <span class=\"citation\">Sot. 11ᵃ</span> (play on <span dir=\"rtl\">מִסְכְּנוֹת</span>, <span class=\"citation\">Ex. I, 11</span>) <span dir=\"rtl\">שמְמַסְכְּנוֹת את בעליהן</span> (read: <span dir=\"rtl\">בוניהן</span>) for they (the buildings) impoverish their builders; <span class=\"citation\">Yalk. Ex. 162</span> <span dir=\"rtl\">שמסכנות</span> (corr. acc.). <span class=\"citation\">Cant. R. to I, 4</span> (play on <span dir=\"rtl\">משכני</span>, ib.) [read:] <span dir=\"rtl\">מַסְכְּנֵינִי אחריך נרוצה</span> make me (Israel) poor, and we shall run after thee (v. <a href=\"#\" data-headword=\"מִסְכֵּן I\">preced.</a>).</div><div class=\"sense\"><b>Ithpa. הִתְמַסְכֵּן</b> </div><div class=\"sense\"><b>Nithpa. נִתְמַסְכֵּן</b> <div class=\"sense\"><i>to become poor</i>. Sot. l. c. <span dir=\"rtl\">כל העוסק בבנין מִתְמַסְכֵּן</span> whoever makes building his business will get poor; <span class=\"citation\">Yeb. 63ᵃ</span>; Ex. R. l. c.; Yalk. Ex. l. c.</div></div>","alt":["מִסְכֵּין"]},"13926":{"h":"מִסְכֵּן","r":"M01950","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Targ. Koh. IV, 13</span>, sq. <span class=\"citation\">Targ. O. Deut. XV, 11</span>; a. e.—<span class=\"citation\">Y. B. Mets. II, 8ᶜ</span> top <span dir=\"rtl\">אינש מ׳</span> a poor man. Y. Peah VII, 21ᵇ top; a. fr.—Pl. <span dir=\"rtl\">מִסְכֵּנִין</span>, <span dir=\"rtl\">מִסְכֵּנַיָּא</span>, <a href=\"#\" data-headword=\"מִסְכֵּן\">מִסְכֵּי׳</a>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a>. Targ. Y. Deut. l. c. (not <span dir=\"rtl\">מַסְכְּנִין</span>). <span class=\"citation\">Targ. Prov. XXII, 7</span>; a. e.—Y. Peah l. c. <span dir=\"rtl\">יהב … דפלג למ׳</span> gave his son Samuel money to distribute among the poor. Y. Ḥag. II, 77ᵈ bot.; <span class=\"citation\">Y. Snh. VI, 23ᶜ</span> <span dir=\"rtl\">ייתון מ׳ וכ׳</span> let the poor come and eat it, that it may not go to ruin. <span class=\"citation\">Y. Sot. III, 19ᵃ</span>; <span class=\"citation\">Y. Peah VIII, 21ᵃ</span> bot. <span dir=\"rtl\">יליף זכי … מעשר מ׳</span> used to give him the tithes of the poor every third year; a. fr.—Denom.:</div>","alt":["מִסְכֵּנָא","מִסְכֵּי׳","מִיסְ׳"]},"13927":{"h":"מַסְכֵּן","r":"M01951","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"מִסְכֵּן II\"><span dir=\"rtl\">מִסְכֵּן</span> II</a>, <i>to make poor, reduce</i>. <span class=\"citation\">Targ. Ps. LVI, 8</span> (h. text <span dir=\"rtl\">הורד</span>). <span class=\"citation\">Ib. XCIV, 5</span> (h. text <a href=\"#\" data-headword=\"עני\">עִנָּה</a>). <span class=\"citation\">Targ. Job VI, 9</span> (h. text <span dir=\"rtl\">דִּכֵּא</span>); a. e.</div>","alt":["מַסְכֵּין"]},"13928":{"h":"מִסְכֵּנוּ","r":"M01952","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַסְכֵּן\">preced.</a>) <i>poverty, scarcity</i>. <span class=\"citation\">Targ. O. Deut. VIII, 9</span> (ed. Vien. <span dir=\"rtl\">עִצּוּרִין</span>). <span class=\"citation\">Targ. Job V, 11</span> <span dir=\"rtl\">אוכמי מי׳</span> those black from starvation (h. text <span dir=\"rtl\">קדרים</span>); a. e.—<span class=\"citation\">Lev. R. s. 35</span>; Pesik. Shimʿu, p. 117ᵃ; <span class=\"citation\">Yalk. Lev. 670</span>; <span class=\"citation\">Yalk. Is. 256</span> <span dir=\"rtl\">יאי מ׳ ליהודאי וכ׳</span> poverty is as becoming to Jews as a red line on a white horse; <span class=\"citation\">Lev. R. s. 13</span> <span dir=\"rtl\">מסכנותיה</span> (read <a href=\"#\" data-headword=\"מִסְכֵּין\">מסכינותא</a>).</div>","alt":["מִסְכֵּנוּתָא","מִסְכֵּי׳","מִי׳"]},"13929":{"h":"מַסְכְּנוּתָא","r":"M01953","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִסְכֵּנוּ\">preced.</a>) <i>making poor</i>. <span class=\"citation\">Targ. Jud. XIV, 15</span>.—[<span class=\"citation\">Targ. Ps. XXXIX, 12</span>, v. <a href=\"#\" data-headword=\"מַכְסָנוּתָא\">מַכְסָנוּתָא</a>.]</div>","alt":[]},"13930":{"h":"מְסַכְסֶכֶת","r":"M01954","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִכְסֵךְ I\">סִכְסֵךְ</a></div>","alt":[]},"13931":{"h":"מַסֶּכֶת","r":"M01955","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>web on the loom.</i> Ohol. VIII, 4 <span dir=\"rtl\">מ׳ הפרוסה</span> the spread web, i.e. the web hanging from the transverse beam (vestis pendens, v. Sm. Ant. s. v. Tela). <span class=\"citation\">Kel. XXI, 1</span> נפש המ׳ <i>the woof</i>, opp. to <span dir=\"rtl\">שתי עומד</span> the warp of the standing loom. <span class=\"citation\">Midr. Till. to Ps. XXXVIII</span>; <span class=\"citation\">Yalk. Ps. 733</span> <span dir=\"rtl\">אנו המ׳ וכ׳</span> we are the web, and Thou the weaver; a. e.</div><div class=\"sense\"><b>—2)</b>  (cmp. Lat. textus) <i>construction, Talmudic treatise</i>. <span class=\"citation\">Ruth R. to II, 9</span> (play on <span dir=\"rtl\">וַיַּסֵּךְ</span>, <span class=\"citation\">II Sam. XXIII, 16</span>) <span dir=\"rtl\">עשאה מ׳ וקבעה וכ׳</span> (not <a href=\"#\" data-headword=\"מַסֶּכְתָּא\">מסכתא</a>) he (David) constructed it and fixed it as a rule for future generations that the king forces the road &amp;c. (v. <span class=\"citation\">Snh. II, 4</span>); Midr. Sam. ch. XX; <span class=\"citation\">Y. Snh. II, 20ᶜ</span> top. <span class=\"citation\">Sabb. 114ᵃ</span>, v. <a href=\"#\" data-headword=\"כַּלָּה\">כַּלָּה</a>; a. fr.—Pl. <span dir=\"rtl\">מַסֶּכְתּוֹת</span>. <span class=\"citation\">Midr. Till. to Ps. CIV, 25</span> <span dir=\"rtl\">אלו המ׳ דבר וכ׳</span> those are the systematic collections of Bar <i>Ḳ</i>. &amp;c. <span class=\"citation\">Num. R. s. 18</span> <span dir=\"rtl\">ששים מ׳</span> sixty Talmudic treatises [editions, however, count sixty-three]; Tanḥ. Korah 12; <span class=\"citation\">Cant. R. to VI, 9</span> (not … <span dir=\"rtl\">תיות</span>); a. fr.</div>","alt":[]},"13932":{"h":"מַסֶּכְתָּא","r":"M01956","html":"<div class=\"sense\">, <i>text, treatise</i> &amp;c. <span class=\"citation\">Snh. 49ᵃ</span> <span dir=\"rtl\">דפתיח להו במ׳</span> a legal subject had just been opened for them (for discussion, and he would not disturb them). <span class=\"citation\">Hor. 10ᵇ</span> <span dir=\"rtl\">אוקימתון מ׳ פלן וכ׳</span> have you put up such and such a web, i.e. have you mastered this and that subject?</div>","alt":[]},"13933":{"h":"מְסִלָּה","r":"M01957","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסִילָּה\">מְסִילָּה</a></div>","alt":[]},"13934":{"h":"מְסַלְיָא","r":"M01958","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְלֵי\">סְלֵי</a>) <i>rejectable, drossy</i>. <span class=\"citation\">Targ. Prov. XXVI, 23</span> <span dir=\"rtl\">כספא מ׳</span> (h. text <span dir=\"rtl\">כסף סיגים</span>).</div>","alt":[]},"13935":{"h":"מְסַלְסְלָה","r":"M01959","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סִלְסֵל\">סִלְסֵל</a>) <i>hair-dresser</i>. <span class=\"citation\">Lam. R. to I, 15</span> (expl. <span dir=\"rtl\">סִלָּה</span>, ib.) [read:] <span dir=\"rtl\">סרקן במסרק שכן בערביא צווחין למסרוקה מ׳</span> he combed them (carded their skins) with an (iron) comb, for in Arabia they call the hair-comber hair-curler.</div>","alt":[]},"13936":{"h":"מְסַמָּא","r":"M01960","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָמָא\">סָמָא</a>) <i>closing a cavity</i>, <span dir=\"rtl\">אבן מ׳</span>, v. <a href=\"#\" data-headword=\"אֶבֶן\">אֶבֶן</a>. <span class=\"citation\">Nidd. 69ᵇ</span> <span dir=\"rtl\">באבן מ׳</span> when the apparent corpse lies on a stone under which there is a cavity; <span class=\"citation\">Sabb. 82ᵇ</span> (Ms. M. <span dir=\"rtl\">מוסמא</span>, v. Rabb. D. S. a. l. note). Sifra M’tsora, Zab., Par. 2, ch. III; a. fr.</div>","alt":["מְסַמָּה"]},"13937":{"h":"מסמים","r":"M01961","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְמֵס III\"><span dir=\"rtl\">מִסְמֵס</span> III</a></div>","alt":[]},"13938":{"h":"מִסְמֵס I","r":"M01962","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מָסַס\">מָסַס</a>) <i>to melt, dissolve</i>.</div><div class=\"sense\"><b>Nithpa. נִתְמַסְמֵס</b> <div class=\"sense\"><i>to be molten, to be in a state of dissolution</i> or <i>liquefaction</i>. <span class=\"citation\">Ḥull. 45ᵇ</span>, v. <a href=\"#\" data-headword=\"מִזְמֵז\">מִזְמֵז</a>. <span class=\"citation\">Ib. 53ᵇ</span> <span dir=\"rtl\">נ׳ הבשר</span> if (in one spot of an animal known to have been attacked by a beast of prey) the flesh appears decayed; <span class=\"citation\">ib.</span> <span dir=\"rtl\">היכי דמי נ׳</span> what do you mean by ‘decayed’ (Answ.) <span dir=\"rtl\">כל שחרופא וכ׳</span> what a physician would peel off, until he comes on sound flesh; <span class=\"citation\">ib. 77ᵃ</span> <span dir=\"rtl\">מִתְמַסְמֵס</span>. Y. Ter. VIII, 46ᵃ top <span dir=\"rtl\">שנִיתְמַסְמְסוּ בני מעיה</span> (a melon) the core of which is liquefied.</div></div>","alt":[]},"13939":{"h":"מַסְמֵס","r":"M01963","html":"<div class=\"sense\"><b>1)</b> <i>to melt, make faint</i>. <span class=\"citation\">Targ. Y. Deut. I, 28</span> <span dir=\"rtl\">מַסְמִיסוּ</span> (not <span dir=\"rtl\">מסמיסן</span>; h. text <span dir=\"rtl\">הֵמַסּוּ</span>).—Y. Shek. V, 48ᵈ היי דין חמר מְמַסְמֵס מעיא Bab. ed. (v. Rabb. D. S. a. l. p. 43; oth. ed. <a href=\"#\" data-headword=\"סמס\">סמס</a>; Ms. M. <a href=\"#\" data-headword=\"סמי\">סמי</a>) which wine loosens the bowels.</div><div class=\"sense\"><b>—2)</b> <i>to soil, make loathsome</i>. <span class=\"citation\">Ḥull. 18ᵃ</span> <span dir=\"rtl\">מְמַסְמֵיס ליה בפרתא</span> the authority soils the meat with dung, so that it cannot be sold &amp;c.—Part. pass. <span dir=\"rtl\">מְמַסְמַס</span>. <span class=\"citation\">Ib. 28ᵃ</span> <span dir=\"rtl\">כי ממ׳ קועיה דמא</span> its throat stained with blood; <span class=\"citation\">ib. 53ᵇ</span></div><div class=\"sense\"><b>Ithpa. אִיתְמַסְמֵס</b> <div class=\"sense\"><i>to be dissolved, melt away, perish</i>. <span class=\"citation\">Targ. Job IX, 23</span> (h. text <a href=\"#\" data-headword=\"מִסַּת\">מַסַּת</a>).</div></div>","alt":[]},"13940":{"h":"מִסְמֵס II","r":"M01964","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"מִשְׁמֵשׁ\">מִשְׁמֵשׁ</a>) </div><div class=\"sense\"><b>1)</b> <i>to press, squeeze</i>.—<i>Part. pass</i>. <span dir=\"rtl\">מְמוּסְמָס</span> <i>mashed, shapeless</i>. <span class=\"citation\">Num. R. s. 14</span> (play on <span dir=\"rtl\">מ̇שמ̇ר̇ו̇ת̇</span>, <span class=\"citation\">Koh. XII, 10</span>) <span dir=\"rtl\">בשעה שהם יוצאים מְ֗מוּסְ֗מָסִים הם מ̇ר̇ו̇ת̇ וכ׳</span> when they (the words of the Law) come out disfigured, they are bitter (drops) to those who hear them; v. <a href=\"#\" data-headword=\"מַס I\"><span dir=\"rtl\">מַס</span> I</a>; Y. Snh. X, 28ᵃ bot.—<span class=\"citation\">Nidd. 24ᵃ</span> <span dir=\"rtl\">מי שפניו מוּסְמָסִים</span> (<span dir=\"rtl\">מוּסְמָסִין</span>) (= <span dir=\"rtl\">מְמוּ׳</span>) a foetus whose face is mashed, contrad. to <span dir=\"rtl\">טוחות</span>, v. <a href=\"#\" data-headword=\"טוּחַ I\"><span dir=\"rtl\">טוּחַ</span> I</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"אָמַץ\">אָמַץ</a>) <i>to press, urge</i>, esp. (of medical treatment) <i>to sustain vital energies</i>. <span class=\"citation\">Gen. R. s. 82</span> <span dir=\"rtl\">כך מְמַסְמְסִין נפשה וכ׳</span> this is the way they stimulate the vital energy of the travailing woman; (Yalk. ib. 136 <span dir=\"rtl\">משיבין</span>); <span class=\"citation\">Yalk. Is. 263</span> <span dir=\"rtl\">שמסמסין את החיה</span> (corr. acc.).</div>","alt":[]},"13941":{"h":"מַסְמֵס ²","r":"M01965","html":"<div class=\"sense\"><b>1)</b> <i>to press, squeeze</i>. <span class=\"citation\">Ḥull. 4ᵃ</span> <span dir=\"rtl\">מְמַסְמֵס ליה מַסְמוּסֵי</span> he holds the bird’s head closely in his hand (so that no mark, if there was any on it, could be recognized). </div><div class=\"sense\"><b>—2)</b> <i>to stimulate, sustain strength</i>. <span class=\"citation\">Yeb. 42ᵇ</span> <span dir=\"rtl\">מְמַסְמְסָא ליה וכ׳</span> she may sustain the child’s strength with eggs and milk (replacing the mother’s milk).</div><div class=\"sense\"><b>Ithpa. אִתְמַסְמֵס  אִימַּ׳</b> <div class=\"sense\"><i>to be squeezed, mashed</i>. Y. Yeb. VIII, 9ᵃ top; Y. Sabb. XIX, 17ᵃ bot. [read:] <span dir=\"rtl\">אתיליד ליה חד בר כד מִימַּסְמֵס ביה ומית</span> a son was born to him with his membrum mashed, and he died.</div></div>","alt":[]},"13942":{"h":"מִסְמֵס III","r":"M01966","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מִסְמֵס I\"><span dir=\"rtl\">מִסְמֵס</span> I</a>) <i>polished wood</i>, prob. (= <a href=\"#\" data-headword=\"אַלְמוּג\">אַלְמוּג</a>, cmp. <a href=\"#\" data-headword=\"מוּג\">מוּג</a>) <i>coral-wood</i>. <span class=\"citation\">Ḥag. 26ᵇ</span> כלי מ׳ Ms. M. (some ed. <a href=\"#\" data-headword=\"מסמים\">מסמים</a>, read <a href=\"#\" data-headword=\"מִסְמֵס III\">מסמיס</a>; Ar. <a href=\"#\" data-headword=\"מסימס\">מסימס</a>) vessels of polished wood, opp. to <span dir=\"rtl\">כלי אכסלגום</span>; <span class=\"citation\">Men. 97ᵃ</span>.—[<span class=\"citation\">Kidd. 12ᵃ</span> <a href=\"#\" data-headword=\"מַסְמֵס\">מסמס</a>, v. <a href=\"#\" data-headword=\"מְסִימִיס\">מְסִימִיס</a>.]</div>","alt":["מִסְמֵיס"]},"13943":{"h":"מַסְמָסָה","r":"M01967","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲמַסְמָסָה\">הֲמַסְמָסָה</a></div>","alt":[]},"13944":{"h":"מסמסתא","r":"M01968","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Ez. XLIII, 14</span> Ar., v. <a href=\"#\" data-headword=\"מְסַמְתָּא\">מְסַמְתָּא</a></div>","alt":[]},"13945":{"h":"מַסְמָר","r":"M01969","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>a pointed object, nail, pin</i>. <span class=\"citation\">Sabb. VI, 10</span> (<span class=\"citation\">67ᵃ</span>) <span dir=\"rtl\">מ׳ מן הצלוב</span> (Y. ed. <span dir=\"rtl\">מ׳ הצלוב</span>) a nail from the gallows of an impaled convict (used as an amulet). <span class=\"citation\">Kel. XII, 4</span> <span dir=\"rtl\">מ׳ הגרע</span> the blood-letter’s pin (v. infra); <span dir=\"rtl\">מ׳ של אבן השעות</span> the style of the sun-dial; <span dir=\"rtl\">מ׳ הגרדי</span> the weaver’s pin. Ib. 5 <span dir=\"rtl\">מ׳ שהתקינו וכ׳</span>; <span class=\"citation\">Tosef. Kel. B. Mets. II, 14</span> <span dir=\"rtl\">מ׳ שעקמו וכ׳</span> an iron pin which was bent in order to be used as a key. Kel. l. c. <span dir=\"rtl\">מ׳ של שלחני</span> the banker’s pin for fastening the shutters, v. <a href=\"#\" data-headword=\"תָּרִיס ²\">תְּרִיס</a>.—<span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">מ׳ שיש לו שושנה</span> a nail which has a big knob.—<span class=\"citation\">Tosef. Kel. B. Mets. IV, 3</span> <span dir=\"rtl\">מקל שעשה בראשו מ׳ להיות תופס בו וכ׳</span> a staff to the end of which a pin was attached for the sake of taking hold of the threshing floor (of making it stationary); <span class=\"citation\">ib. V, 10</span>. Ib. <span class=\"citation\">B. Bath. VII, 2</span> <span dir=\"rtl\">חוט המ׳ של וכ׳</span> the builder’s cord to which a pin is attached (i.e. plumb-line). Ib. <span class=\"citation\">B. Mets. II, 11</span> <span dir=\"rtl\">מ׳ הגרוע</span> the scraper’s pin (fastened to the smith’s block); a. fr.—Pl. <span dir=\"rtl\">מַסְמְרִים</span>, <span dir=\"rtl\">מַסְמְרִין</span>, <span dir=\"rtl\">מַסְמְרוֹת</span>. <span class=\"citation\">Gen. R. s. 68</span>, end. <span class=\"citation\">B. Bath. 7ᵇ</span> <span dir=\"rtl\">קבע בה מ׳</span> drive nails into it, i.e. remember it well. <span class=\"citation\">Tosef. Kel. B. Mets. II, 11</span> <span dir=\"rtl\">גולת חנוני שכולה מ׳</span> a store-keeper’s bowl (?) studded all over with nails. Tanḥ. B’haăl. 15 (ref. to <span class=\"citation\">Koh. XII, 11</span>) <span dir=\"rtl\">כתיב כמשמרות ואנו קורין מ׳ וכ׳</span> it is written <i>k’mishm’roth</i> (like guards) and we read <i>k’masm’roth</i> (like nails) to teach thee, if thou drivest them like a nail into thy heart, they will guard thee; <span class=\"citation\">Num. R. s. 4</span>. <span class=\"citation\">Esth. R. to VI, 10</span> אני … חבלים ומ׳ I prepared for thee ropes and nails (for impaling); a. fr.</div><div class=\"sense\"><b>—2)</b>  (<i>pl.</i>) <i>cloves</i>. Num. R. l. c. <span dir=\"rtl\">ערבין … כמ׳ נטועים</span> as sweet to their hearers as cloves.</div><div class=\"sense\"><b>—3)</b> <i>a peg-shaped attachment to a loaf, knob</i>. <span class=\"citation\">T’bul Yom I, 3</span> <span dir=\"rtl\">מ׳ שאחר הככר</span> the knob on the back of the loaf (supposed to serve as trade-mark).</div><div class=\"sense\"><b>—4)</b>  a <i>wart</i> or <i>corn</i> (cmp. Lat. clavus).—Pl. <span dir=\"rtl\">מַסְמְרוֹת</span>. Sifra Thazr. Neg., Par. 1, ch. II <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a>; <span class=\"citation\">Tosef. Neg. II, 12</span> <span dir=\"rtl\">המַסְמֶרֶת</span> (<i>sing</i>.).</div>","alt":[]},"13946":{"h":"מַסְמָר ²","r":"M01970","html":"<div class=\"sense\">, <i>pin, nail</i>. <span class=\"citation\">Targ. Y. Num. XXV, 3</span>.—Y. Ḥag. III, beg. 78ᵈ <span dir=\"rtl\">כל חד וחד נסיב חד מ׳ וכ׳</span> each took one nail and drove it in. Y. Pes. V, 32ᵇ top [read:] <span dir=\"rtl\">הא קביעא גבך כמסמרא</span> let this be fixed in thy memory like a nail; <span class=\"citation\">Y. Yeb. XIII, 13ᶜ</span> top <span dir=\"rtl\">במיסמרה</span> (corr. acc.); a. e.—Pl. <span dir=\"rtl\">מַסְמְרִין</span>, <span dir=\"rtl\">מַסְמְרַיָּא</span>, <span dir=\"rtl\">רַיָּה …</span> <span class=\"citation\">Targ. Jer. X, 4</span>; a. e.—<span class=\"citation\">Y. B. Bath. II, 13ᵇ</span> bot. [read:] <span dir=\"rtl\">ממחין אילין לאילין מ׳ דנווליה</span> refused to one another the fastening of the weaver’s pin to the party wall.—[<a href=\"#\" data-headword=\"מַסְמָר ²\">מְסַמְּרָא</a>, v. <a href=\"#\" data-headword=\"סְמַר I\">סְמַר</a>.]</div>","alt":["מַסְמְרָא"]},"13947":{"h":"מַסְמֶרֶת","r":"M01971","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>wart</i> or <i>corn</i>, v. <a href=\"#\" data-headword=\"מַסְמָר\">מַסְמָר</a> h., end.</div>","alt":[]},"13948":{"h":"מְסַמְתָּא","r":"M01972","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סוּם\">סוּם</a>) <i>one of the marked-off tiers</i> or <i>settles of the altar</i> (v. <span class=\"citation\">Midd. III, 1</span>). <span class=\"citation\">Targ. Ez. XLIII, 14</span>; <span class=\"citation\">17</span> (ed. Lag. <span dir=\"rtl\">מְסִימְ׳</span> a. <span dir=\"rtl\">מְסַמְ׳</span>; ed. Wil. first time <a href=\"#\" data-headword=\"מְסַתְּמָתָא\">מְסַתְּמָתָא</a>, Ar. <a href=\"#\" data-headword=\"מסמסתא\">מסמסתא</a>; corr. acc.; h. text <a href=\"#\" data-headword=\"עֲזָרָה\">עזרה</a>).</div>","alt":[]},"13949":{"h":"מְסַן","r":"M01973","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מְסָאנָא\">מְסָאנָא</a>) <i>shoe</i>. <span class=\"citation\">Targ. O. Gen. XIV, 23</span>. <span class=\"citation\">Targ. Ez. XVI, 10</span>; a. fr.—<span class=\"citation\">Lam. R. to I, 5</span> <span dir=\"rtl\">חד מ׳ דידיה</span> one of his shoes; <span dir=\"rtl\">חד מ׳ חורן</span> the other shoe; a. e.—<span class=\"citation\">Kidd. 22ᵇ</span> bot. <span dir=\"rtl\">מְסָנָאִי</span> (prob. to be read: <span dir=\"rtl\">מְסָאנִי</span>) my shoe.—Pl. <span dir=\"rtl\">מְסָנִין</span>, <span dir=\"rtl\">מְסָנַיָּא</span>. <span class=\"citation\">Targ. Josh. IX, 5</span> (ed. Wil. <span dir=\"rtl\">מְסָנָן</span>). <span class=\"citation\">Targ. Is. III, 18</span> (h. text <span dir=\"rtl\">עכסים</span>).—Hebr. pl. <span dir=\"rtl\">מְסָנִים</span>. <span class=\"citation\">Y. Pes. X, beg. 37ᵇ</span>, v. <a href=\"#\" data-headword=\"צוֹצָל\">צוֹצָל</a>.</div>","alt":["מְסָנָא"]},"13950":{"h":"מַסְנָא","r":"M01974","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסְנָנָא\">next w.</a></div>","alt":[]},"13951":{"h":"מַסְנָנָא","r":"M01975","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְנַן\">סְנַן</a>) <i>pure gold</i>. <span class=\"citation\">Targ. Is. XIII, 12</span> (ed. Wil. <a href=\"#\" data-headword=\"מַסְנָא\">מַסְנָא</a>; ed. Lag. <span dir=\"rtl\">מסננה</span>; h. text <span dir=\"rtl\">כתם</span>).</div>","alt":[]},"13952":{"h":"מְסַנֶּנֶת","r":"M01976","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָנַן\">סָנַן</a>) <i>strainer</i>; <i>the strained mass</i>. <span class=\"citation\">Sabb. XX, 2</span> (<span class=\"citation\">139ᵇ</span>) <span dir=\"rtl\">מ׳ של חרדל</span> a mustard mixture in the strainer (v. Rashi a. l.). Ib. 134ᵃ <span dir=\"rtl\">אין מסננין … במ׳ שלו</span> you must not strain a mustard mixture (on the Holy Day) in the strainer designated for it.</div>","alt":[]},"13953":{"h":"מְסַנְתָּא","r":"M01977","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְסַנֶּנֶת\">preced.</a>) <i>sieve, basket</i>. Y. Dem. II, 21ᵈ bot. <span class=\"citation\">Ib.</span> <a href=\"#\" data-headword=\"מסאנא\">מסאנא</a> (corr. acc.).</div>","alt":[]},"13954":{"h":"מָסַס","r":"M01978","html":"<div class=\"sense\"> (b. h.) <i>to melt, dissolve</i>.</div><div class=\"sense\"><b>Nif. נָמַס  נָמֵס</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"נִימּוֹס\">נִימּוֹס</a>, <span dir=\"rtl\">נִימַּס</span> <i>to melt, be liquefied; to fall away; to faint; to despair</i>. <span class=\"citation\">Ex. R. s. 25</span> <span dir=\"rtl\">נִימּוֹסִּין</span> (Var. <span dir=\"rtl\">נִימַּסִּין</span>) they faint. <span class=\"citation\">Yalk. ib. 251</span> <span dir=\"rtl\">התחילו נְמַסִּין</span> they began to lose heart; Mekh. B’shall., Shir., s. 9 <span dir=\"rtl\">לֵהָמֵס</span>. <span class=\"citation\">Deut. R. s. 1</span>, end <span dir=\"rtl\">תִּימַּס עינו וכ׳</span> may this man’s (thy) eye run out. <span class=\"citation\">Maasr. I, 2</span> <span dir=\"rtl\">הרמונים משיִמַּסּוּ</span> pomegranates are subject to tithes when their core becomes pulpy; expl. Y. ib. 48ᵈ bot. <span dir=\"rtl\">משיתמעך אוכל וכ׳</span> (cmp. <a href=\"#\" data-headword=\"מִסְמֵס II\"><span dir=\"rtl\">מִסְמֵס</span> II</a>) when the eatable portion (core) can be mashed under one’s fingers; [anoth. definition taking our w. in the sense of <i>falling away, diminution</i>; <span dir=\"rtl\">משיכניסו מחצה</span> when the ripening core is reduced to half the capacity of the cavity,—upon which the remark is made, <span dir=\"rtl\">דילמא … הֵמַסּוּ … פלגון לבבנו</span> perhaps he learned it from the homiletical teachers who interpret <i>hemassu</i> &amp;c. (<span class=\"citation\">Deut. I, 28</span>), they divided our hearts (an allusion to <span class=\"citation\">Num. R. s. 17</span>)].</div></div><div class=\"sense\"><b>Hif. הֵמֵס</b> <div class=\"sense\"><i>to cause to melt away</i>. <span class=\"citation\">Deut. R. s. 2</span>, beg. (ref. to <span class=\"citation\">Ps. XXXIX, 12</span>) <span dir=\"rtl\">כל חמדה … הֵמַסְתָּ אותה וכ׳</span> (not <span dir=\"rtl\">אותו</span>) all the delight which Moses longed for, to enter the land,—thou hast caused it to decay as a moth enters garments and makes them decay. V. <a href=\"#\" data-headword=\"מָסָה\">מָסָה</a>.</div></div>","alt":[]},"13955":{"h":"מְסַס","r":"M01979","html":"<div class=\"sense\"> <span class=\"citation\">Targ. II Sam. XVII, 10</span> <span dir=\"rtl\">מִמַס ימסי</span> (ed. Lag. <span dir=\"rtl\">מִמְסָא מסי</span>), v. <a href=\"#\" data-headword=\"מְסֵי\">מְסֵי</a></div><div class=\"sense\"><b>Ithpe. אִתְמְסַס</b> <div class=\"sense\"><i>to melt, decay</i>. <span class=\"citation\">Targ. Ps. LXXV, 4</span>.—[<span dir=\"rtl\">אִמִּיס</span>, v. <a href=\"#\" data-headword=\"מְאִיס\">מְאִיס</a>.]</div></div>","alt":[]},"13956":{"h":"מָסָס","r":"M01980","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>stomach</i>, v. <a href=\"#\" data-headword=\"הֶמְסֵס\">הֶמְסֵס</a>.</div>","alt":[]},"13957":{"h":"מַסָּסָא","r":"M01981","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסָּאסָא\">מַסָּאסָא</a></div>","alt":[]},"13958":{"h":"מססטולא","r":"M01982","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסוֹסְטוּלָא\">מְסוֹסְטוּלָא</a></div>","alt":[]},"13959":{"h":"מַסָּע","r":"M01983","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>removal; journey; station</i>. <span class=\"citation\">Cant. R. to III, 6</span> <span dir=\"rtl\">ממ׳ למ׳</span> from station to station; a. fr.—Pl. <span dir=\"rtl\">מַסָּעוֹת</span> (<i>fem</i>.). <span class=\"citation\">Snh. 94ᵇ</span> <span dir=\"rtl\">עשר מ׳ נסע וכ׳</span> that wicked man (Sennacherib) marched ten journeys in that one day; <span class=\"citation\">Yalk. Is. 284</span>. Tanḥ. B’midb. 2 <span dir=\"rtl\">ובאה עמהן במ׳</span> and it (the well) went with them on their journeys; <span class=\"citation\">Num. R. s. 1</span>. Tosef. <span class=\"citation\">R. Hash. I</span>II (II), 3 <span dir=\"rtl\">ובמ׳</span> and the signal for marching (<span class=\"citation\">Num. X, 2-8</span>); a. fr.—<span class=\"citation\">Pesik. R. s. 16</span> <span dir=\"rtl\">המַסָּעִים</span> the marches in the desert.—[Tosef. <span class=\"citation\">R. Hash. I</span>I (I), 2 <span dir=\"rtl\">מסעות</span>, <a href=\"#\" data-headword=\"מסעיות\">מסעיות</a>, v. <a href=\"#\" data-headword=\"מַשּׂוּאָה\">מַשּׂוּאָה</a>.]</div>","alt":[]},"13960":{"h":"מְסָעֵד","r":"M01984","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָעַד\">סָעַד</a>) <i>assistant, attendant</i>.—Pl. <span dir=\"rtl\">מְסָעֲדִים</span>. <span class=\"citation\">Par. III, 6</span> <span dir=\"rtl\">פרה וכל מְסָעֲדֶיהָ</span> the red cow and all her attendants.</div>","alt":[]},"13961":{"h":"מסעיות","r":"M01985","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשּׂוּאָה\">מַשּׂוּאָה</a></div>","alt":[]},"13962":{"h":"מִסְפֵּד","r":"M01986","html":"<div class=\"sense\"> m. (b. h.) = <a href=\"#\" data-headword=\"הֶסְפֵּד\">הֶסְפְּד</a>. Lam. R. introd. (R. Joḥ. 1) <span dir=\"rtl\">מה לכם קושרין מ׳</span> why do you compose these lamentations?, v. <a href=\"#\" data-headword=\"הֶסְפֵּד\">הֶסְפֵּד</a></div>","alt":[]},"13963":{"h":"מִסְפַּד","r":"M01987","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. L, 10</span>. <span class=\"citation\">Targ. Y. Deut. X, 6</span>; a. e.—Pl. <span dir=\"rtl\">מִסְפְּדַיָּא</span>. <span class=\"citation\">Targ. Am. V, 16</span> (ed. Lag. a. oth. <i>sing</i>.).</div>","alt":["מִסְפֵּד","מִסְפְּדָא"]},"13964":{"h":"מספוטמיא","r":"M01988","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְפַּמְיָא\">אִסְפַּמְיָא</a></div>","alt":[]},"13965":{"h":"מִסְפּוֹרֶת","r":"M01989","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"מִסְפֶּרֶת\">מִסְפֶּרֶת</a></div>","alt":[]},"13966":{"h":"מִסְפְּיָיא","r":"M01990","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְפֵי\">סְפֵי</a>) <i>fearfulness</i>. <span class=\"citation\">Targ. Job XLI, 17</span> (Ms. <span dir=\"rtl\">מִסְיָיפ׳</span>; h. text <span dir=\"rtl\">שֵׂת</span>). <span class=\"citation\">Ib. XXXI, 23</span> (ed. Lag. <span dir=\"rtl\">מסייפ׳</span>; Ms. Var. <a href=\"#\" data-headword=\"סַפְיָיא\">סַפְיָיא</a>; h. text <a href=\"#\" data-headword=\"שְׂאֵת\">שְׂאֵת</a>).</div>","alt":[]},"13967":{"h":"מִסְפְּק","r":"M01991","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סָפַק II; v. <a href=\"#\" data-headword=\"סָפֵק\">סָפֵק</a>) <i>strait, dilemma; difficulty</i>. <span class=\"citation\">Y. Sot. III, 19ᵃ</span> bot. <span dir=\"rtl\">הכניסה עצמה למ׳ הזה המרובה</span> she placed herself in such a dilemma (to be suspected of adultery and to have to drink the waters of jealousy). <span class=\"citation\">Y. Gitt. VIII, 49ᶜ</span> bot. <span dir=\"rtl\">מה ראית להכניס עצמך למי׳ הזה וכ׳</span> what was thy reason for taking such a responsibility (by deciding in favor of a lenient opinion)?—<span class=\"citation\">Esth. R. to II, 3</span> <span dir=\"rtl\">באו לידי המ׳ הזה</span> they (the Persian matrons) came to that trouble (to have to compete with all maidens of the country); a. e.</div>","alt":["מִי׳"]},"13968":{"h":"מְסַפְּקָא","r":"M01992","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סְפַק II) </div><div class=\"sense\"><b>1)</b> <i>sufficiency</i>. <span class=\"citation\">Y. Ber. IV, 8ᵃ</span> top [read:] <span dir=\"rtl\">אית לך מ׳ לכל חדא וחדא אדכרה מינהון</span> you have enough material for each Divine Name out of them (the combined benedictions); <span class=\"citation\">Y. Taan. II, 65ᶜ</span> top.</div><div class=\"sense\"><b>—2)</b> <i>Pa</i>. of <a href=\"#\" data-headword=\"סְפַק\">סְפַק</a>, q. v.</div>","alt":["מְסַפְּקָה"]},"13969":{"h":"מִסְפָּר","r":"M01993","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>number, count</i>. <span class=\"citation\">Cant. R. to VI, 9</span> (ref. to <span class=\"citation\">II Sam. XXIV, 9</span>) <span dir=\"rtl\">מ׳ זה המנין וכ׳</span> <i>mispar</i> means counting, <i>mifḳad</i>, summing up. <span class=\"citation\">Pesik. R. s. 11</span> <span dir=\"rtl\">היו מ׳</span> they were a limited number; <span dir=\"rtl\">שלא במ׳</span> innumerable; a. fr.</div>","alt":[]},"13970":{"h":"מַסְפָּר","r":"M01994","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְפַר\">סְפַר</a>) <i>tool for cutting hair, razor, scissors</i>. <span class=\"citation\">Targ. O. Num. VI, 5</span>. <span class=\"citation\">Targ. Ez. V, 1</span> (not <a href=\"#\" data-headword=\"מִסְטֵירִין\">מִסְ׳</a>); a. e.—<span class=\"citation\">Snh. 96ᵃ</span> <span dir=\"rtl\">הבו לי מ׳</span> (Ms. F. <a href=\"#\" data-headword=\"מַסְפַּרְתָּא\">מַסְפַּרְתָּא</a>) give me a razor; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ויהבו ליה מספרתא</span>; <span class=\"citation\">Yalk. Is. 276</span> <a href=\"#\" data-headword=\"מַסְפָּר\">מספרא</a>.</div>","alt":["מַסֵפְּרָא"]},"13971":{"h":"מַסְפָּרַיִים","r":"M01995","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> du. (<a href=\"#\" data-headword=\"מַסְפָּר\">preced.</a>) <i>shears, scissors.</i> <span class=\"citation\">Kel. XVI, 8</span> <span dir=\"rtl\">תיק מספרת ומ׳</span> the sheath of a shearing knife or of scissors. <span class=\"citation\">Y. M. Kat. III, 82ᵃ</span> top <span dir=\"rtl\">במ׳</span> with scissors, contrad. to <span dir=\"rtl\">סכין</span> a. <a href=\"#\" data-headword=\"מִסְפֶּרֶת\">מספרת</a>; Bab. <span class=\"citation\">M. Kat. 17ᵇ</span>; a. e.—[<span class=\"citation\">Tosef. Kel. B. Mets. IV, 5</span> <a href=\"#\" data-headword=\"מַסְפָּרַיִים\">מספרים</a> ed. Zuck., read <span dir=\"rtl\">מַסְמְרִים</span>.]</div>","alt":["מַסְפָּרַיִם"]},"13972":{"h":"מִסְפֶּרֶת","r":"M01996","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַסְפָּרַיִים\">preced.</a>) <i>shearing knife, clipping tool.</i> <span class=\"citation\">Kel. XVI, 8</span>, v. <a href=\"#\" data-headword=\"מַסְפָּרַיִים\">preced.</a> <span class=\"citation\">M. Kat. 17ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"מַסְפָּרַיִים\">preced.</a> <span class=\"citation\">Kel. XIII, 1</span> (Maim. <span dir=\"rtl\">מספו׳</span>, ed. Dehr. <a href=\"#\" data-headword=\"מִסְפֶּרֶת\">מספרת</a>). <span class=\"citation\">Tosef. Kel. B. Mets. III, 4</span> <span dir=\"rtl\">מ׳ של פרקים</span> shears consisting of separable blades; <span class=\"citation\">Sabb. 48ᵇ</span>; <span class=\"citation\">58ᵇ</span> <span dir=\"rtl\">מספו׳</span>. <span class=\"citation\">Tosef. Bets. III, 19</span>, v. <a href=\"#\" data-headword=\"סָפַר\">סָפַר</a>; a. e.</div>","alt":["מִסְפּוֹרֶת"]},"13973":{"h":"מַסְפַּרְתָּא","r":"M01997","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"מַסְפָּר\">מַסְפָּר</a></div>","alt":[]},"13974":{"h":"מָסַק","r":"M01998","html":"<div class=\"sense\"> (denom. of a noun <a href=\"#\" data-headword=\"מַסָּק\">מַסָּק</a>, fr. <span dir=\"rtl\">נסק</span> <i>to ascend</i>) <i>to harvest olives</i>, opp. to <a href=\"#\" data-headword=\"נָקַף I\">נקף</a> to pick, glean. <span class=\"citation\">Tosef. Dem. VI, 6</span> <span dir=\"rtl\">ישראל שקיבל … זיתיו לִמְסוֹק בזתים</span> if an Israelite rented from a fellow Israelite … his olive trees for harvesting, the rent to be payable in olives; <span dir=\"rtl\">זיתיו למסוק בשמן</span> payable in oil; Y. ib. VI, 25ᵇ top. <span class=\"citation\">Neg. II, 4</span> <span dir=\"rtl\">כמוֹסֵק וכ׳</span> in the position of one taking olives down. <span class=\"citation\">Tosef. Toh. X, 4</span> <span dir=\"rtl\">עד שלא מְסָקָן</span> before he plucked them; a. fr.—Part. pass. <span dir=\"rtl\">מָסוּק</span>; pl. <span dir=\"rtl\">מְסוּקִין</span>. <span class=\"citation\">Tosef. B. Mets. IX, 1</span>.—Denom. <a href=\"#\" data-headword=\"מָסִיק\">מָסִיק</a>, <a href=\"#\" data-headword=\"מְסִיקָה\">מְסִיקָה</a>.</div>","alt":[]},"13975":{"h":"מַסָּק","r":"M01999","html":"<div class=\"sense\"> part. <i>Af</i>. of <a href=\"#\" data-headword=\"נָסַק\">נָסַק</a>.</div>","alt":[]},"13976":{"h":"מַסָּקָא","r":"M02000","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסַק\">נְסַק</a>) <i>ascent</i>.—Pl. <span dir=\"rtl\">מַסָּקִין</span>. <span class=\"citation\">Lev. R. s. 18</span>; <span class=\"citation\">Koh. R. to XII, 5</span>; v. <a href=\"#\" data-headword=\"מָחוֹתִיתָא\">מָחוֹתִיתָא</a>.</div>","alt":[]},"13977":{"h":"מַסְקָאנָא","r":"M02001","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסְקָנָא\">מַסְקָנָא</a></div>","alt":[]},"13978":{"h":"מסקום","r":"M02002","html":"<div class=\"sense\">, <span class=\"citation\">Y. Bicc. III, 65ᵈ</span>, v. <a href=\"#\" data-headword=\"דְּמַסְקוֹס\">דְּמַסְקוֹס</a></div>","alt":[]},"13979":{"h":"מַסְקָנָא","r":"M02003","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסַק\">נְסַק</a>) </div><div class=\"sense\"><b>1)</b> <i>ascent, height, steps</i>. <span class=\"citation\">Targ. I Sam. IX, 11</span> (ed. Lag. <a href=\"#\" data-headword=\"מַסְקָאנָא\">מַסְקָאנָא</a>). <span class=\"citation\">Targ. Is. XXXVIII, 8</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>final result, upshot</i>. <span class=\"citation\">Meg. 14ᵇ</span> <span dir=\"rtl\">ומ׳ הכי הואי</span> and so it finally came to pass.</div>","alt":[]},"13980":{"h":"מַסִּקְיָין","r":"M02004","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסּוֹקִיתָא\">מַסּוֹקִיתָא</a></div>","alt":[]},"13981":{"h":"מַסְקָתָא","r":"M02005","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַסִּקְיָין\">preced.</a> wds.) <i>going up, procession</i>. <span class=\"citation\">Targ. II Chr. IX, 4</span>.</div>","alt":[]},"13982":{"h":"מָסַר","r":"M02006","html":"<div class=\"sense\"><b>1)</b> <i>to seize</i> (v. <span class=\"citation\">Num. XXXI, 5</span>).—Denom. <a href=\"#\" data-headword=\"מְסִירָה\">מְסִירָה</a> 1.</div><div class=\"sense\"><b>—2)</b> <i>to hand over; to deliver, transmit.</i> <span class=\"citation\">Ab. I, 1</span> <span dir=\"rtl\">ומְסָרָהּ וכ׳</span> and handed it (the Law) over to &amp;c. (in the chain of tradition). <span class=\"citation\">B. Mets. 8ᵇ</span> (expl. <a href=\"#\" data-headword=\"מוֹסֵירָה\">מוֹסֵירָה</a>) <span dir=\"rtl\">כאדם המוֹסֵר דבר וכ׳</span> like one handing over (giving possession) &amp;c. <span class=\"citation\">Ib. 111ᵇ</span> bot. (expl. <span dir=\"rtl\">נשא את נפשו</span>, <span class=\"citation\">Deut. XXIV, 15</span>) <span dir=\"rtl\">דבר שמסר את נפשו עליו</span> Ms. M. (ed. <span dir=\"rtl\">המוסר</span>, v. Rabb. D. S. a. l. note) a labor for which he binds (obligates) himself; [oth. explan.] ib. 112ᵃ <span dir=\"rtl\">מ׳ את עצמו למיתה</span> (Ms. M. <span dir=\"rtl\">מ׳ לו נפשו עליו</span>) he delivered himself to death, i.e. risked his life; (Ms. M. for which he surrendered his life to the employer); <span class=\"citation\">Sifré Deut. 279</span> <span dir=\"rtl\">מ׳ לך את נפשו</span> he surrendered his life to thee (the employer); a. v. fr.—<span dir=\"rtl\">מ׳ דין על</span> to surrender one’s case against a man (to Providence); v. <a href=\"#\" data-headword=\"דִּין\">דִּין</a>. <span class=\"citation\">B. Kam. 93ᵃ</span>; <span class=\"citation\">R. Hash. 16ᵇ</span>; a. e.—Esp. a) <i>to surrender a person to the authorities, to inform against</i>. <span class=\"citation\">Gitt. 7ᵃ</span> <span dir=\"rtl\">ובידי למָסְרָם למלכות</span> it is in my power to bring them to judgment through the (Roman) government. <span class=\"citation\">Tosef. Ter. VII, 20</span> <span dir=\"rtl\">יהרגו כולם ולא יִמְסְרוּ וכ׳</span> let them all suffer death rather than surrender one Israelite &amp;c.; a. fr.—V. <a href=\"#\" data-headword=\"מָסוֹר\">מָסוֹר</a>.—b) <span dir=\"rtl\">מ׳ עצמו</span> (sub. <span dir=\"rtl\">למיתה</span>) <i>to suffer martyrdom</i>. <span class=\"citation\">Pes. 53ᵇ</span> <span dir=\"rtl\">שמָסְרוּ עצמן על קדושת וכ׳</span> who were ready to suffer death for the sanctification of the Name (of the Lord). <span class=\"citation\">Yalk. Ex. 182</span> <span dir=\"rtl\">אומה המוֹסֶרֶת עצמה וכ׳</span> a people that is ready to die for the unity of my Name; a. fr.—Part. pass. <a href=\"#\" data-headword=\"מָסוֹר\">מָסוּר</a>; f. <span dir=\"rtl\">מְסוּרָה</span>; pl. <span dir=\"rtl\">מְסוּרִים</span>, <span dir=\"rtl\">מְסוּרִין</span>; <span dir=\"rtl\">מְסוּרוֹת</span>. <span class=\"citation\">Kidd. 32ᵇ</span>; <span class=\"citation\">B. Mets. 58ᵇ</span> <span dir=\"rtl\">דבר המ׳ ללב וכ׳</span> to an injunction which is entrusted to the heart (over which human authorities have no control), the Text adds, ‘and thou shalt be afraid of thy God.’ Mekh. Ki Thissa (ref. to <span dir=\"rtl\">לכם</span>, <span class=\"citation\">Ex. XXXI, 14</span>) <span dir=\"rtl\">לכם שבת מ׳ ואי אתם מ׳ לשבת</span> the Sabbath is given in your charge, but you are not surrendered to the Sabbath, i.e., there are higher objects for which the Sabbath law must eventually be violated; <span class=\"citation\">Yoma 85ᵇ</span>; a. fr.</div><div class=\"sense\"><b>Nif. נִמְסָר</b> <div class=\"sense\"><i>to be delivered, transmitted</i>. <span class=\"citation\">Num. R. s. 4</span> <span dir=\"rtl\">נִמְסְרָה לו בכורה</span> the birth-right (priesthood) was transferred to him. <span class=\"citation\">B. Kam. 82ᵇ</span> <span dir=\"rtl\">אין נִמְסָרִים בידכם</span> they will not be given into your hands, you will have no power over them; <span class=\"citation\">Men. 64ᵇ</span>. Y. Yoma III, 40ᵈ bot. <span dir=\"rtl\">לא היה נִמְסָר וכ׳</span> it (the pronunciation of the Tetragrammaton) was not communicated to any but &amp;c.; a. fr.</div></div>","alt":[]},"13983":{"h":"מְסַר","r":"M02007","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. XXXIX, 8</span>. <span class=\"citation\">Targ. Am. I, 6</span>. <span class=\"citation\">Targ. O. Deut. XXIV, 15</span>; a. fr.—Part. pass. <span dir=\"rtl\">מָסִיר</span>; f. <a href=\"#\" data-headword=\"מְסִירָה\">מְסִירָא</a>; pl. <a href=\"#\" data-headword=\"מְסִירִין\">מְסִירִין</a>; <a href=\"#\" data-headword=\"מְסִירָה\">מְסִירָן</a>. <span class=\"citation\">Targ. Num. III, 9</span>; a. fr.—[<span class=\"citation\">Targ. Y. II, Gen. XVI, 5</span> <span dir=\"rtl\">מְסָרִין בידך</span>, a corrupt., prob. to be read: <span dir=\"rtl\">מַסְרִית עלך</span>; cmp. <span class=\"citation\">B. Kam. 93ᵃ</span>.]—<span class=\"citation\">B. Mets. 8ᵇ</span> <span dir=\"rtl\">מאן קא מ׳ ליה דליקני</span> who is there to deliver it to him, that he might take possession? <span class=\"citation\">Y. Yoma III, 40ᵈ</span> bot. <span dir=\"rtl\">אנא מָסֵר יתיה לך</span> I will transmit it (the pronunciation of the Tetragrammaton) to you. <span class=\"citation\">Koh. R. to III, 11</span> [read:] <span dir=\"rtl\">אית הכי בר נש דאִימְסוֹר ליה</span> is there a person here to whom I might communicate it?; <span dir=\"rtl\">כד אתי מִימְסַר</span> when he was about to communicate it. <span class=\"citation\">Kidd. 12ᵇ</span> <span dir=\"rtl\">דמ׳ מודעא וכ׳</span> who enters a protest against his own letter of divorce. <span class=\"citation\">Ber. 20ᵃ</span> <span dir=\"rtl\">הוו קא מָסְרֵי נפשייהו וכ׳</span> were ready to suffer martyrdom for the sanctification of the Name; <span dir=\"rtl\">אנן לא מַסְרִינָן וכ׳</span> we are not ready to suffer &amp;c.; a. fr.</div><div class=\"sense\"><b>Ithpe. אִתְמְסַר  אִימְּסַר</b> <div class=\"sense\"><i>to be surrendered, transmitted; to surrender one’s self</i>. <span class=\"citation\">Targ. Lev. XXVI, 25</span>. <span class=\"citation\">Targ. Ps. LXXIX, 11</span>; a. e.—<span class=\"citation\">Gitt. 66ᵇ</span> <span dir=\"rtl\">מִימַּסְרָן</span>; <span class=\"citation\">29ᵃ</span> <span dir=\"rtl\">מִמַּסְרָן</span>, v. <a href=\"#\" data-headword=\"מִילָּא II\"><span dir=\"rtl\">מִילָּא</span> II</a>. <span class=\"citation\">Snh. 26ᵃ</span> <span dir=\"rtl\">מִימַּסְרֵי</span> have decided to surrender (to capitulate). Koh. R. l. c. <span dir=\"rtl\">ולא קבל עליה מִימְּסֵר ליה מימסר</span> (some ed. <span dir=\"rtl\">למימסר ליה</span>) he declined to have the Tetragrammaton transmitted to him (v. Y. Yoma l. c.).</div></div>","alt":["(מָסַר) I"]},"13984":{"h":"מְסַר II","r":"M02008","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מְסָרָא\">מְסָרָא</a>) <i>to saw</i>. <span class=\"citation\">Targ. Is. XLIV, 13</span>. <span class=\"citation\">Targ. II Sam. XII, 31</span> (ed. Wil. <a href=\"#\" data-headword=\"מְסַר\">מְסַר</a>); <span class=\"citation\">Targ. I Chr. XX, 3</span> (ed. Rahm. <a href=\"#\" data-headword=\"מְסַאר\">מסאר</a>).—Part. pass. <span dir=\"rtl\">מְמַסַּר</span>. <span class=\"citation\">Targ. I Kings VII, 9</span>.</div>","alt":["מַסֵּר"]},"13985":{"h":"מַסָּר","r":"M02009","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>a tool with rough edges</i> or <i>teeth, file, saw</i>. <span class=\"citation\">Sabb. XVII, 4</span> <span dir=\"rtl\">מ׳ הגדול</span> saw for cutting wood. <span class=\"citation\">Kel. XXI, 3</span>; <span class=\"citation\">Tosef. Kel. B. Bath. I, 8</span> <span dir=\"rtl\">מלבן של מ׳ הגדול</span> the frame of the saw. <span class=\"citation\">Y. Succ. III, 53ᶜ</span> bot. <span dir=\"rtl\">כמין מ׳</span> leaves serrated like a saw, v. <a href=\"#\" data-headword=\"מַגָּל\">מַגָּל</a>; <span class=\"citation\">Tosef. Succ. II, 7</span>; Bab. <span class=\"citation\">Succ. 34ᵃ</span> <span dir=\"rtl\">דומה למ׳</span>. <span class=\"citation\">Gen. R. s. 6</span>; Midr. Sam. ch. IX, v. <a href=\"#\" data-headword=\"נָסַר\">נָסַר</a>; <span class=\"citation\">Ex. R. s. 5</span> <span dir=\"rtl\">כס׳</span> (Var. <span dir=\"rtl\">כמַסְמָר</span>); a. e.</div>","alt":[]},"13986":{"h":"מְסָרָא","r":"M02010","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. X, 15</span> (ed. Wil. <a href=\"#\" data-headword=\"מְסָרָא\">מַסְרָא</a>).—Pl. <span dir=\"rtl\">מְסָרִין</span>. <span class=\"citation\">Targ. I Kings VII, 9</span>. <span class=\"citation\">Targ. II Sam. XII, 31</span>; <span class=\"citation\">Targ. I Chr. XX, 3</span> (ed. Rahm. <span dir=\"rtl\">מְסָארִין</span>).</div>","alt":[]},"13987":{"h":"מְסָרְבָא","r":"M02011","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">מְסָרְבִין</span>, v. <a href=\"#\" data-headword=\"מְסַרְבָּן\">מְסַרְבָּן</a>.</div>","alt":[]},"13988":{"h":"מְסַרְבַּיי","r":"M02012","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>M’sarbay</i>, by-name of the family of Jojarib. <span class=\"citation\">Y. Taan. IV, 68ᵈ</span> <span dir=\"rtl\">מ׳ מ̇ס̇ר̇ ב̇י̇י̇תא וכ׳</span> he was surnamed M., because he surrendered the Temple to the enemy; … <span dir=\"rtl\">יה הֵרִיב … על שמ̇ר̇ו וס̇ר̇ב̇ו בו</span> the Lord went into judgment … because they rebelled against him.</div>","alt":[]},"13989":{"h":"מְסַרְבָּן","r":"M02013","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סְרַב I) <i>rebellious</i>. <span class=\"citation\">Targ. Ps. LXXVIII, 8</span> (ed. Lag. <a href=\"#\" data-headword=\"מְסַרְהֲבָן\">מסרהבן</a>, Var. <a href=\"#\" data-headword=\"מְסִירִין\">מסירין</a>; ed. Wil. <span dir=\"rtl\">מְסָרְבִין</span> (pl. followed by sing. <span dir=\"rtl\">מרגיז</span>; Ms. <a href=\"#\" data-headword=\"מְסַרְהֲוָון\">מסרהוון</a>). <span class=\"citation\">Targ. Is. LXV, 2</span>.</div>","alt":["מְסַרְבָּנָא"]},"13990":{"h":"מסרדי","r":"M02014","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*מוּטַרְדֵּי\">מוּטַרְדֵּי</a></div>","alt":[]},"13991":{"h":"מְסַרְהֲבָא","r":"M02015","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סַרְהֵב\">סַרְהֵב</a>) </div><div class=\"sense\"><b>1)</b> <i>impatient, impetuous</i>. <span class=\"citation\">Targ. Prov. XXI, 5</span> (h. text <span dir=\"rtl\">אָץ</span>).</div><div class=\"sense\"><b>—2)</b> <i>rebellious</i>.—Pl. <a href=\"#\" data-headword=\"מְסַרְהוֹבִין\">מְסַרְהֲבִין</a>. <span class=\"citation\">Targ. Y. Deut. XXXI, 27</span>. <span class=\"citation\">Targ. Ps. LXVI, 7</span> ed. Wil. (ed. Lag. <a href=\"#\" data-headword=\"מְסַרְהוֹבִין\">מְסַרְהוֹבִין</a>; Ms. <a href=\"#\" data-headword=\"מְסַרְהוֹבִין\">מְסַרְהֲוִוין</a>; h. text <span dir=\"rtl\">סררים</span>).</div>","alt":[]},"13992":{"h":"מְסַרְהֲבָאִית","r":"M02016","html":"<div class=\"sense\"> adv. (<a href=\"#\" data-headword=\"מְסַרְהֲבָא\">preced.</a>) <i>impetuously</i>. <span class=\"citation\">Targ. Prov. XXV, 8</span> (h. text <span dir=\"rtl\">מהר</span>).</div>","alt":[]},"13993":{"h":"מְסַרְהֲבָן","r":"M02017","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסַרְבָּן\">מְסַרְבָּן</a></div>","alt":[]},"13994":{"h":"מְסַרְהוֹבִין","r":"M02018","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסַרְהֲבָא\">מְסַרְהֲבָא</a></div>","alt":["מְסַרְהֲוִוין"]},"13995":{"h":"מְסַרְהֲוָון","r":"M02019","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסַרְבָּן\">מְסַרְבָּן</a></div>","alt":[]},"13996":{"h":"מסרוכי","r":"M02020","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסְרֵךְ\">מַסְרֵךְ</a></div>","alt":[]},"13997":{"h":"מסרולה","r":"M02021","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ned. VII, beg. 40ᵇ</span> <span dir=\"rtl\">מ׳ ופלולויה</span>, a corrupt. for <span dir=\"rtl\">מְלִיסּוֹפִילּוֹן</span> m. (μελισσόφυλλον, cmp. Syr. <span dir=\"rtl\">מהליססופוללון</span>, <span dir=\"rtl\">מיליסופולון</span>, P. Sm. 2025; 2091) <i>Melissophyllon, melissa</i> or <i>baum</i>, an herb (v. Sm. Ant. s. v.); v. <a href=\"#\" data-headword=\"הֵמְטַלְיָא\">הֵמְטַלְיָא</a>.</div>","alt":[]},"13998":{"h":"מַסְרוֹק","r":"M02022","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסְרֵק\">מַסְרֵק</a></div>","alt":[]},"13999":{"h":"מַסְרוֹקָה","r":"M02023","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סְרַק II) <i>hair-comber</i>. <span class=\"citation\">Lam. R. to I, 15</span>, v. <a href=\"#\" data-headword=\"מְסַלְסְלָה\">מְסַלְסְלָה</a>.</div>","alt":[]}};
